quests[11145] = { id = 11145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Grimmtotem", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, {class}, aber bringt mir meine Männer lebend zurück.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 5 Gefangene von Theramore befreit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11146] = { id = 11146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenfänger", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. Ich an Eurer Stelle würde sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 6 Raptoren einfangt. Ihr könnt entweder Blutsumpfraptoren oder Blutsumpfkreischer einfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11147] = { id = 11147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Raptoren los", description = "Jetzt, da wir unsere Raptoren haben, besteht unser nächster Schritt darin, sie für einen Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem... nun, eigentlich ist es ja auch völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren werden sich um den Rest kümmern.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr den Raptorenköder bei der Windmühle im Dorf der Schwarzhufe platziert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11148] = { id = 11148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Grimmtotem", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager im Nordwesten.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen. Ausgehend von der Größe ihrer Angriffstrupps, schätzen wir jedoch, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", sourceObjective = "Hauptmann Darill bei der Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11149] = { id = 11149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Unterstützung", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich wüsste aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, im Süden, liegt ein kleines Gehöft, das Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und angesehene Wahrsagerin. Folgt der Straße Richtung Süden bis zu ihrem Hof und bittet sie, Euch bei der Suche nach den Tätern, die für das Massaker beim Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, zu helfen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof.", sourceObjectiveStatus = "unverified-source-field" }
quests[11150] = { id = 11150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", sourceObjective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11151] = { id = 11151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit im Namen der Familie Hyal", description = "Die Grimmtotem waren zwar lediglich eine Plage für mich, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um Jim Hyals Familie zu retten, aber vielleicht denken die Grimmtotem demnächst zweimal nach, bevor sie jemanden aus Theramore angreifen.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11152] = { id = 11152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich Frieden", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder der Gerechtigkeit überantwortet wurden.\n\n<Hauptmann Mumm fertigt einen kleinen Blumenkranz an.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Steine auf dem Friedhof genau nördlich der Tore von Theramore.", sourceObjective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11153] = { id = 11153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbrecht die Blockade", description = "Alle unsere Schiffe sind gesunken! Wir benötigen Eure Hilfe, um die Piratenblockade in der Straße der Trümmer zu durchbrechen!\n\nNehmt diese Splitterbomben und lasst Euch vom Zeppelin mitnehmen, den Eggenmeiser uns 'ausgeliehen' hat. Er wird Euch über die Schiffe der Piraten, dieser Gauner, hinwegfliegen und Ihr werdet ihnen die Hölle heiß machen!\n\nWenn Ihr sie nicht in Stücke bomben könnt, dann werden wir die Blockade wohl nie durchbrechen können.", sourceObjective = "Nehmt Petrovs Splitterbomben und werft sie auf die Piraten. Beseitigt 25 Piraten der Blockade und 10 Kanonen der Blockade. Kehrt zu Bombenschütze Petrov in Westwacht zurück, sobald Ihr den Auftrag erfüllt habt.", completion = "Das wollte ich hören! Ihr habt was drauf, {name}, so viel ist klar!\n\nDenkt Ihr, dass Ihr morgen wiederkommen könntet? Bis dahin haben wir neue Splitterbomben. Ich würde Euch ja wieder losschicken, aber mein Gehilfe Feknut ist noch nicht vom Guanosammeln zurück - Fledermausguano. Den brauchen wir für die Bomben.\n\nWieso braucht der eigentlich so lange?", sourceObjectiveStatus = "unverified-source-field" }
quests[11154] = { id = 11154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt ihnen eine Guanoangst ein!", description = "Ihr, ja Ihr... Ich brauche Eure Hilfe!\n\nPetrov hat mich hier hochgeschickt, damit ich Fledermausguano für die Splitterbomben, die er in Westwacht herstellt, sammle. Er hat mich in mein Verderben geschickt!\n\nDie Dunkelklauenfledermäuse hängen im nördlichen Bruchwald herum. Ich werde jedoch keinen Schritt von dieser Plattform machen, außer um nach Hause zu gehen!\n\nAber Ihr... Ihr könntet ihn für mich besorgen! Ja? Och büdde!!\n\nHier, nehmt diese Knallfrösche. Ich denke mir, dass wenn man sie unter den Fledermäusen losgehen lässt, sie sich so erschrecken werden, dass der Guano von alleine kommt!", sourceObjective = "Sammelt 10 Stück Dunkelklauenguano ein und bringt sie zu Ingenieur Feknut am Stählernen Tor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11155] = { id = 11155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder Schaufelhauersuppe?", description = "Nachdem ein Großteil unseres Viehs verschwunden ist, sollten wir uns schnell mit neuen Vorräten eindecken - oder die Bestien in dieser Gegend werden unser kleinstes Problem sein!\n\nDa ich für die Versorgung dieser Meute verantwortlich bin, werde ich Euch nach Osten schicken, um mir etwas Fleisch zu besorgen. Genauer gesagt will ich uns ein wenig Schaufelhauerfleisch zubereiten.\n\nNehmt Euch jedoch vor den Hirschen in Acht... die sind gefährlich!", sourceObjective = "Küchenchefin Schwarzkessel hat Euch gebeten, ihr 6 Schaufelhauerfleisch zu beschaffen. Sie befindet sich in Westwacht.", progress = "Nichts geht über das zarte Fleisch, das man aus der Seite eines Schaufelhauers schneidet!", completion = "Damit werde ich eine feine Mahlzeit für die Jungs auftischen können.\n\n<Die Köchin lehnt sich etwas vor und flüstert Euch ins Ohr.>\n\nHier, mein Junge, nehmt Euch etwas hiervon. Ihr seht so aus, als könntet Ihr etwas mehr auf den Knochen vertragen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11156] = { id = 11156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuber des Grollhornpostens", description = "Die Grimmtotem beim Grollhornposten im Norden werden mit jedem Tag dreister. In der Nacht kann man sie oft von ihren Taten singen hören, wie sie diejenigen vertrieben haben, die sich hier niederlassen wollten.\n\nSie haben fest vor, uns von Tabethas Hof zu vertreiben, obwohl sie schon Generationen von Schülern hier ausgebildet hat. Wir haben den Hof so gut es geht verteidigt, aber Lehrling Garion wurde bei dem letzten Angriff verletzt.\n\nGeht zum Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Die Überfälle müssen ein Ende nehmen.", sourceObjective = "Tötet 12 Grimmtotem des Grollhornpostens und kehrt zu Lehrling Morlann auf Tabethas Hof zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11157] = { id = 11157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelege des Bösen", description = "{name}, in dieser Sache vertraue ich nur Euch. Die Protowelpen und Eier der Protodrachen im südöstlich gelegenen brennenden Wald müssen beseitigt werden!\n\nSeitdem wir hier angekommen sind, steht die Glutstätte in Flammen. Da muss irgendeine abartige Magie am Werk sein - und seit Kurzem scheint sie zu wachsen. Meine Männer sagen mir, dass wenn wir nicht schon bald etwas unternehmen, wir in ein paar Wochen vom Feuer umgeben sein werden!\n\nBegebt Euch dorthin und beseitigt die Gefahr, indem Ihr die Protowelpen und die Eier zerstört.", sourceObjective = "Zerstört 15 Eier der Protodrachen und 15 Protowelpen. Kehrt danach zu Hauptmann Adams in Westwacht zurück.", completion = "Gute Arbeit! Mit ein bisschen Glück wird die Vernichtung ihres Geleges und ihrer Welpen die feurigen Bestien vertreiben und verhindern, dass sich das magische Feuer ausbreitet.\n\nWartet... Was ist das für ein Geräusch? Hört sich an, wie das Schlagen von Schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11158] = { id = 11158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsumpffedern", description = "Überrascht Euch Broggs Anwesenheit, {race}? Keine Sorge! Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könntet es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für die Zerstörung unserer alten Heimat und den Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um die Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe. Für das Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus dem Blutsumpfbau.", sourceObjective = "Bringt 5 Blutsumpffedern zu Brogg in Morastwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[11159] = { id = 11159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Festung der Steinbrecher", description = "Brogg hat das Totem fertig gestellt, mit dem Ihr den Geistern seiner Freunde Frieden geben könnt. Als die Drachkin über uns herfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk. Seitdem hoffte er auf einen gemeinsamen Gegenangriff aller überlebenden Steinbrecher.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher im Norden. Verwendet es in der Nähe von Ogerskeletten, um ihre Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", sourceObjective = "Brogg in Morastwinkel möchte, dass Ihr 10 Geister der Steinbrecher tötet, um sie so ihrer letzten Ruhe zu überantworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11160] = { id = 11160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Banner der Steinbrecher", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort, dem heutigen Flammenbau, aufbewahrt wurde. Brogg braucht das Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben.\n\nDer alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Das Banner befindet sich tief in der Höhle. Seid vorsichtig, {name}.", sourceObjective = "Beschafft das Banner der Steinbrecher und bringt es Brogg in Morastwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[11161] = { id = 11161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz der Feindschaft", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leiche an. Denkt daran, dass nur tote Drachkin ihre Essenzen freigeben!\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", sourceObjective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[11162] = { id = 11162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung für den schwarzen Drachenschwarm", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. {name}, Ihr habt mir sehr dabei geholfen, mich auf diesen Moment vorzubereiten. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr auf eine Höhle trefft, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden Ihr Land zurückerobern!", sourceObjective = "Stellt das Banner der Steinbrecher nahe des Eingangs zu Onyxias Hort auf, wartet auf ihre Reaktion und kehrt anschließend zu Brogg in Morastwinkel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11163] = { id = 11163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agentin mit Herz", description = "<Donna sieht sich um und beginnt zu flüstern.>\n\n{name}, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", sourceObjective = "Meldet Euch bei Donna Brascoe, um eine Belohnung für Euer Heldentum in Zul'Aman zu erhalten. Donna hält sich momentan in den Geisterlanden, direkt außerhalb von Zul'Aman auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[11164] = { id = 11164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger der verlorenen Hauer", description = "Hey Mann! Du bist neu hier, oder? Kannst du mir einen Gefallen tun?\n\nBudd will seiner Waldtrollverkleidung den letzten Schliff verpass'n. Meinte, dass er schon fast fertig is' und nur noch eine letzte Sache braucht. Hauer.\n\nMeine Kürschnerkünste wär'n hier reine Zeitverschwendung. Trollhauer rauszieh'n... ah, bei so was würde mir sofort schlecht werd'n. \n\nBring mir 10 Trollhauer, ja, Mann?", sourceObjective = "Prigmon möchte, dass Ihr 10 Hauer eines Waldtrolls von Trollen in Zul'Aman einsammelt. Bringt sie zu ihm bei Budds Lager in den Geisterlanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11165] = { id = 11165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Troll unter Trollen", description = "Hör zu, Mann, da gibt's noch was anderes, was du für den alten Prigmon tun könntest.\n\nZungam, mein alter Taugenichts von Vetter, steckt in Zul'Aman fest. Er lebt auch noch - ich habe sein Rauchsignal erst letzte Nacht geseh'n!\n\nIch sollte ihn eigentlich verrott'n lass'n, dafür, dass er mich in dieses ganze Schlamassel verwickelt hat... allerdings schuldet er mir noch eine Stange Geld.\n\nTu, was du kannst, um ihn da rauszuhol'n, das Abkassier'n kannste mir überlass'n!", sourceObjective = "Prigmon möchte, dass Ihr seinen Vetter Zungam in Zul'Aman ausfindig macht und ihm zur Seite steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11166] = { id = 11166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das X markiert Euren Untergang!", description = "Wie konnten diese Narren nur versagen? Ich habe ihnen gesagt, dass sie vorsichtig sein müssen - sogar meine Karte und Verkleidungen habe ich ihnen gegeben, damit sie sich leichter einschleichen können. Ach, was soll's. Das Gute an der Sache ist, dass diese Gelegenheit jetzt Euch und Euren Freunden zuteil wird.\n\nWenn Ihr Euch richtig anstellt, dann seid Ihr auf dem besten Weg, ein Teil meiner Mannschaft zu werden und damit an all dem unermesslichen Ruhm teilzuhaben, der bald mein sein wird. Nicht, dass ich Euch brauchen würde, vergesst das nicht.\n\nEs gibt da noch einige Bereiche auf der Karte, die noch besser erforscht werden müssen, bevor unsere Ausgrabung wirklich beginnen kann...", sourceObjective = "Betretet Zul'Aman und erkundet Halazzis Kammer, Jan'alais Plattform und Akil'zons Plattform. Berichtet Budd bei seinem Lager in den Geisterlanden von den Details dieser Bereiche.", sourceObjectiveStatus = "unverified-source-field" }
quests[11167] = { id = 11167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Seuche", description = "Nicht lange nachdem uns Arthas zu dieser elenden Existenz verurteilt hatte, arbeiteten wir in der Königlichen Apothekervereinigung an der Herstellung unserer eigenen Pest. Eine Pest, die alles Fleisch verschlingen würde, ob lebendiges, totes oder untotes.\n\nNun ist uns die Herstellung dieser Pest geglückt und wir sind hier, um sie persönlich an die Geißel zu liefern.\n\nDie Allianz hat das Schiff mit dem letzten Erregerstamm, der in unseren Labors in Unterstadt gezüchtet wurde, abgefangen. Begebt Euch zum Wrack, das von hier aus gesehen im Südosten liegt, und bergt so viele Behälter, wie Ihr nur könnt.", sourceObjective = "Apotheker Lysander im Hafen der Vergeltung will, dass Ihr 10 unversehrte Behälter aus dem Schiffswrack im Südosten bergt.", progress = "Konntet Ihr die Behälter bergen, {name}?", completion = "Schön, dass Ihr unverletzt zurückgekehrt seid. Die Gefahr, dass man beim Hantieren der Behälter infiziert wird, besteht. Vermutlich hätte ich Euch schon zuvor davor warnen sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11168] = { id = 11168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mischung verstärken", description = "Ich habe das Gefühl, dass die lange Reise auf See die Effektivität unserer Pest beeinträchtigt hat. Was wir brauchen ist ein starkes Gift, um die Wirksamkeit des Erregerstamms zu erhöhen.\n\nDie Krabben in der Nähe dieses Strands sind entfernte Verwandte der viel kleineren braunen Gezeitenkrabbler. Die kleinere tropische Art produziert ein paralytisches Gift, das stark genug ist, um einen Oger außer Gefecht zu setzen.\n\nWas größer ist, ist ja bekanntlich besser! Das Gift der viel größeren Drüsen der hier ansässigen Art sollte stärker sein. Bringt mir ein paar!", sourceObjective = "Bringt Apotheker Lysander im Hafen der Vergeltung im Heulenden Fjord 3 riesige Giftdrüsen von riesigen Gezeitenkrabblern.", progress = "Konntet Ihr die Giftdrüsen beschaffen, nach denen ich suche, {name}?", completion = "Ihr beweist weiterhin Eure Kompetenz, {name}. Hoffentlich wird dieses Gift genügen, um unsere Pest auf den gewünschten Wirkungsgrad zu bringen.\n\nZumindest sollte es dabei helfen, die Empfänger zu schwächen und sie leichter zu infizieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11169] = { id = 11169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe der Grimmtotem", description = "Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, hatte ich noch ein recht seltsames Totem an mich bringen können, welches unsere Feinde gegen uns eingesetzt haben.\n\nAnscheinend verschießt es im Gefecht Blitze aus wilder Energie. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beherbergen eine ganze Reihe aggressiver, scheckiger Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht die Krokilisken in Reichweite des Totems zu bekämpfen.", sourceObjective = "Lehrling Garion bei Tabethas Hof möchte, dass Ihr das erbeutete Totem an 10 scheckigen Staubsuhlerkrokilisken oder Staubsuhlerdolchrachen ausprobiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11170] = { id = 11170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test auf See", description = "Wir haben soeben die Nachricht erhalten, dass Verstärkungstruppen auf dem Weg sind, um den Streitkräften der Allianz beizustehen. Sie konnten keinen besseren Zeitpunkt dafür wählen!\n\nWir benötigen dringend Testobjekte und diese Reservisten der Nordflotte sind ideal dafür geeignet!\n\nNehmt diese Seuchenphiolen an Euch und sprecht mit Kamilla, der Fledermausführerin. Sagt ihr, dass Ihr eine Reitfledermaus benötigt, um einen speziellen Auftrag für uns auszuführen.\n\nWerft die Phiolen auf die Verstärkungsflotte, sobald Ihr Euch über dem Meer befindet. Ich kann es kaum erwarten, zu sehen, was dabei herauskommt!", sourceObjective = "Sprecht mit Fledermausführerin Kamilla, nehmt eine Reitfledermaus und fangt die Verstärkungstruppen der Allianz ab. Werft die Seuchenphiolen auf 16 Reservisten der Nordflotte, sobald Ihr Euch in Reichweite befindet.", completion = "Hmmpff... die Berichte vom Schlachtfeld sind... nicht ermutigend!", sourceObjectiveStatus = "unverified-source-field" }
quests[11171] = { id = 11171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexlord? Pah!", description = "Ausgezeichnet! Meinem großen Auftritt in Zul'Aman steht fast nichts mehr im Weg.\n\nIhr habt gute Arbeit geleistet, {name}. Ich habe mit meiner Mannschaft gesprochen und sie scheint sich langsam mit Euch anfreunden zu können. Ich würde sagen, dass Ihr schon bald ein festes Mitglied der Gruppe sein könntet. Ihr müsst nur noch eine Sache erledigen - beseitigt diesen Hexlord.\n\nEs ist nichts weiter dabei, wirklich. Knöpft Euch diesen Schuft einfach vor, er wird wahrscheinlich sofort kehrt machen und abhauen. Gebrechlichere, ältere Trolle gleichen ihre Schwächen oft mit einem einschüchternden Titel aus, versteht Ihr?", sourceObjective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr Hexlord Malacrass in Zul'Aman tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11172] = { id = 11172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeppelinabsturz", description = "Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Erst vor ein paar Tagen kam hier eine Abgesandte des Dampfdruckkartells wegen dieser Sache vorbei.\n\nSie war auf der Suche nach Informationen über die Fracht des Zeppelins und dessen Piloten Beezil, aber keiner von uns hat den Absturz wirklich beobachtet. Ich bezweifle, dass sie die Aufräumarbeiten am Wrack und die Bergung der Fracht alleine bewältigen kann.\n\nWenn Ihr etwas Zeit habt, solltet Ihr mal bei Beezils Wrack vorbeischauen. Ihr findet es östlich von hier, in der Nähe der Berge.", sourceObjective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", sourceObjectiveStatus = "unverified-source-field" }
quests[11173] = { id = 11173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reagenziendieb", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich ihn einfach zu ignorieren, meistens vergebens. Dieses Mal möchte ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Sobald Ihr mir das Gift bringt, werde ich Morlanns Vorräte auffrischen, noch bevor er irgendetwas merkt.", sourceObjective = "Bringt 6 Phiolen Marschengift zu Lehrling Garion bei Tabethas Hof.", sourceObjectiveStatus = "unverified-source-field" }
quests[11174] = { id = 11174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrosionsschutz", description = "Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, sie unter Kontrolle zu halten, werden sie das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann auf keinen Fall mit leeren Händen zurückkehren, {class}! Ihr müsst mir helfen, diese Schlamme aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um es anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 10 Schlamme auflöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11175] = { id = 11175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Tochter", description = "Sagt mir, ist es wahr? Sind die Forscher, die in die Flüsterschlucht hinabgestiegen sind, verrückt geworden?\n\nMeine Tochter ist die Vorarbeiterin der Forscherliga, die Richtung Norden zum Stählernen Tor gezogen ist. Nach all den schrecklichen Ereignissen, die uns in letzter Zeit zugestoßen sind, habe ich Angst um ihre Sicherheit.\n\nIch bitte Euch, {class} - ich bin zu alt, um mich auf die Reise zu machen. Ihr Name ist Irena. Werdet Ihr Euch dorthin begeben und nachsehen, ob es ihr gut geht?", sourceObjective = "Der alte Zasterstein hat Euch gebeten, seine Tochter, die Vorarbeiterin Irena Zasterstein, zu finden. Sie sollte sich am Stählernen Tor befinden.", completion = "Grrr. Ich hab's gewusst! Er ist viel zu beschützerisch! Das ist so peinlich.\n\nNicht, dass ich nicht darüber froh wäre, Euch zu sehen... Ich freue mich! Wir alle freuen uns. Wir können Eure Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11176] = { id = 11176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "Unsere Arbeit hier draußen fängt eigentlich gerade erst an. Aber jetzt, da wir diese Flugmaschinen aus Westwacht geliefert bekommen haben, sollten wir so richtig zum Arbeiten kommen.\n\nDas Problem ist, dass uns nicht genug qualifizierte Piloten zur Verfügung stehen. Und da sich die Situation im nördlich gelegenen Bruchwald verschlimmert, würde ich die Sache hier gerne schnell unter Dach und Fach bringen und dann wieder gen Heimat aufbrechen.\n\nFalls Ihr noch eine Hand frei haben solltet, dann sprecht mit einem meiner Chefarchäologen. Ihr könnt sie in der Nähe der Flugmaschinen im Norden und Süden der Ausgrabungsstätte finden.", sourceObjective = "Forscherin Irena Zasterstein hat Euch gebeten, mit einem der Chefarchäologen des Stählernen Tores zu sprechen. Diese befinden sich am Stählernen Tor.", completion = "Irena hat Euch hierher geschickt, nicht wahr? Gut, dann haben wir Arbeit für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11177] = { id = 11177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler beim Irrlichtanwesen", description = "Es gibt da einen Burschen, die Einheimischen nennen ihn \"Sumpfauge\" Jarl, der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nDas Irrlichtanwesen befindet sich in der Gegend beim Hexenhügel. Folgt der Straße von Theramore aus in Richtung Nordwesten, Ihr werdet das Anwesen finden, bevor die Straße in Richtung Westen abbiegt.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11178] = { id = 11178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Kriegsherren", description = "Ihr begutachtet die Phiole mit dem pulsierenden Blut und Eure Gedanken schweifen zu dem launischen kleinen Mann außerhalb von Zul'Aman.\n\nIhr könnt es kaum erwarten, Budds Gesicht beim Anblick dieser Phiole zu sehen!", sourceObjective = "Bringt Zul'jins Blut zu Budd bei seinem Lager in den Geisterlanden, direkt außerhalb von Zul'Aman.", sourceObjectiveStatus = "unverified-source-field" }
quests[11179] = { id = 11179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finlay ist darmlos", description = "Jetzt seht Euch mal all diese Armbrustschützen an – und wer muss ihre ganzen Waffen instand halten? Ich, Finlay Pfeilmacher!\n\nDer Hauptmann hat meinem Helfer befohlen, sich für den Umzug nach Fort Wildervaar bereitzumachen, und ich habe nicht die Zeit, um allen Katzendarm für ihre Sehnen zu sammeln!\n\n{class}, seid <ein guter Kamerad/eine gute Kameradin> und beschafft mir ein paar Katzendärme. Die Nebelsäbler, die durch den Fjord streifen, werden dafür ausreichen – doch denkt daran, dass Ihr nur die makellosesten Innereien mitbringt! Mit angerissenen Därmen können wir nichts anfangen.", sourceObjective = "Sammelt 7 Stück makellosen Schattensäblerkatzendarm und kehrt zu Finlay Pfeilmacher zurück. Er befindet sich in Westwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11180] = { id = 11180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sucht den Hexenhügel heim?", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", sourceObjective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr Informationen von 10 auferstandenen Gebeinen oder auferstandenen Geistern sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11181] = { id = 11181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hexenfluch", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, {name}. Es könnte unsere letzte Hoffnung sein.", sourceObjective = "Bringt 9 Zweige Hexenfluch zu Mordant Grimsby beim Irrlichtanwesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11182] = { id = 11182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursachen", description = "Alles in der Natur strebt nach einem Gleichgewicht -ein Gleichgewicht, das nur dann gestört wird, wenn diejenigen, die nicht mit der Natur im Einklang sind, eingreifen.\n\nIhr verschwendet Eure Kraft, wenn Ihr die Welpen und Drachen tötet. Die eigentlichen Missetäter hinter der Ausbreitung dieser magisch brennenden Wälder sind die vor Kurzem erwachten Vrykul und ihr Gebieter Skeld Drachensohn.\n\nWenn Ihr Blut vergießen wollt, dann fangt mit denen an. Ihr Unterschlupf befindet sich im Süden der Glutstätte.", sourceObjective = "Tötet 5 Tierführer der Drachenschinder und Skeld Drachensohn. Geht in die Glutstätte und sucht ein Urtum der Glutstätte auf, falls Ihr das schaffen solltet.", completion = "Schade, dass man ein Raubtier nur mit der Hilfe eines anderen Raubtiers erlegen kann - aber so ist das Gesetz der Natur nun einmal.\n\nVielleicht können die Protodrachen und -welpen jetzt wieder in Frieden leben. Doch angesichts des erneuten Erwachens der Vrykul, bezweifle ich das.", sourceObjectiveStatus = "unverified-source-field" }
quests[11183] = { id = 11183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Hexenhügels", description = "Die Fackel ist fertig. Stellt sie am Ende des Docks auf und seid auf alles gefasst.\n\nIch weiß wirklich nicht, was der Rauch der Fackel bewirken wird... falls überhaupt etwas geschieht. Eigentlich hege ich für gewöhnlich Zweifel an dererlei Hokuspokus, aber wir haben keine andere Wahl. Viel Glück, Ihr und Jarl könnt es brauchen.", sourceObjective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr die Fackel am Ende des Docks aufstellt und alles bezwingt, was daraufhin erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[11184] = { id = 11184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlächterklaue der Gefräßige", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden gebeten, den Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn wurde autorisiert, jeden, der der Bedrohung durch Schlächterklaue ein Ende setzt, großzügig zu entlohnen.", sourceObjective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch anschließend bei Drazzit Tropfhahn in Morastwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[11185] = { id = 11185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief der Apothekerin", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, enthält alarmierende Beweise für das enge Bündnis der Grimmtotem mit den neuen Herren von Lordaeron.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nAndello Porter, der SI:7-Agent bei Tabethas Hof, sollte umgehend von diesem Brief erfahren.", sourceObjective = "Bringt den versiegelten Brief zu Andello Porter auf Tabethas Hof.", sourceObjectiveStatus = "unverified-source-field" }
quests[11186] = { id = 11186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Verrats?", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, deutet auf eine geheime Korrespondenz zwischen Unterstadt und den Anführern der Grimmtotem hin.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nVielleicht kann Euch Nazeer Blutlanze in Brackenwall sagen, was mit dieser Information geschehen soll.", sourceObjective = "Bringt den versiegelten Brief zu Nazeer Blutlanze in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[11187] = { id = 11187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierleutnant Malister", description = "DAS IST UNFASSBAR! Die Protodrachen greifen die Wache an!\n\nBestien wie diese, hätten eigentlich davon abgeschreckt werden sollen, als Ihr Euch um ihr Gelege und ihre Welpen gekümmert habt.\n\nIhr habt Euch doch um sie gekümmert, oder?\n\n{name}, die Situation verlangt direktere Maßnahmen. Sprecht mit meinem Berater Magierleutnant Malister. Er wird Euch das geben, was Ihr benötigt, um diese teuflischen Kreaturen zu erreichen.", sourceObjective = "Hauptmann Adams möchte, dass Ihr mit seinem Berater Magierleutnant Malister sprecht. Er befindet sich in Westwacht.", completion = "<Malister winkt Euch herbei und flüstert Euch zu.>\n\nIch habe befürchtet, dass so etwas passieren könnte. Ich habe versucht, den Hauptmann von seiner Vorgehensweise abzuraten - doch er ist ein Zwerg der Tat, der ein genaues Bild davon hat, wie die Dinge ablaufen sollen.\n\nLasst uns über die Möglichkeiten sprechen, die uns noch offen bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11188] = { id = 11188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Untaten...", description = "Nun da wir diese Protodrachen aus der Glutstätte verärgert haben, könnten sie dazu neigen, ihre Angriffe auf die Wache fortzuführen. Das darf nicht passieren.\n\nIch tue es zwar nur ungern, auf eine Untat eine weitere folgen zu lassen, aber in diesem Fall sieht es so aus, als müssten wir diese Kreaturen vernichten. Eine bedauerliche Vorgehensweise, aber eine, der wir uns nichtsdestotrotz verpflichten müssen.\n\nNehmt meinen Zauberstab. Ich habe zwar versucht, seine Reichweite zu erhöhen, aber austeilen tut er nicht viel. Was er jedoch kann, ist die Aufmerksamkeit der Protodrachen auf sich zu ziehen.", sourceObjective = "Magierleutnant Malister in Westwacht hat Euch damit beauftragt, 3 Protodrachen zu vernichten.", completion = "<Der Magierleutnant seufzt.>\n\nEine unerfreuliche Sache, so viel ist sicher. Tja, was getan ist, ist getan. Wenn wir Glück haben, werden sich die Welpen in der Glutstätte, die einmal zu Drachen heranwachsen werden, nicht mehr an unsere schändlichen Taten erinnern.\n\nUnd wenn wir ein wenig mehr Glück haben, wird sich dieser magische Wald nicht weiter ausbreiten.\n\nHier, {name}. Bitte, nehmt dieses Almosen aus unserer Schatzkammer entgegen... für all Eure Mühen. Es ist das Mindeste, was wir tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11189] = { id = 11189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Mal", description = "Tag auch. Bin ich tot? Ich denke schon - ich schwebe ja über meinem eigenen Körper!\n\nOh, welch unglückliche Wendung des Schicksals. Ich wollte gerade um Irenas Hand anhalten, als die Geißel über uns hereinbrach.\n\nIch weiß, dass sie immer noch am Leben ist... Ich kann sie in meinem Herzen fühlen.\n\n{class}, meint Ihr, dass Ihr mich sicher zu ihr hinbringen könntet? Die Geißel kann meinen Geist noch immer sehen und mir zweifellos schreckliche Dinge antun.\n\nIch möchte einen letzten Blick auf ihr wunderschönes Gesicht werfen. Ihr könnt dann für mich sagen, dass ich sie liebe.", sourceObjective = "Eskortiert den Geist von Entdecker Jaren sicher zu Irena Zasterstein. Sie befindet sich am Stählernen Tor im Heulenden Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[11190] = { id = 11190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht allen passt dieselbe Größe", description = "Na, <Junge/Mädchen> - welches Genie hat denn unsere Kanonen nicht in der Standardgröße gebaut? Jetzt müssen wir spezielle Kanonenkugeln herstellen, um sie aus den Teufelsgeräten zu feuern!\n\nIch wäre Euch wohlgesinnt, solltet Ihr Euch aufmachen und die Kugeln finden, die wir schon verschossen haben. So wie dieser Haufen schießt, werden sie mit Sicherheit überall im Süden und Osten verstreut sein.\n\n<Der Kanonier breitet seine Arme aus, um Euch eine Vorstellung von der Größe der Kanonenkugeln zu geben.>\n\nDas wäre sicherlich schneller, als wenn wir sie neu herstellen würden.", sourceObjective = "Kanonier Ely hat Euch damit beauftragt, 10 Kanonenkugeln der Westwacht einzusammeln und sie zu ihm zurückzubringen. Er befindet sich in Westwacht.", progress = "Unsere Munition hier in der Gegend wird langsam ziemlich knapp, {class}. Unsere Feinde brauchen eins auf die Mütze - ganz besonders Skorn!\n\nHabt Ihr noch mehr Kugeln für uns?", completion = "Oh, seid gesegnet, {name} - seid gesegnet!\n\nStellt sie doch gleich dort ab, wo Ihr steht. Ich werde einen meiner Jungs schon bald losschicken, um sie zu verladen. Dann müssen wir uns keine Sorgen mehr darum machen, dass uns beim Bombardieren von Skorn die Kugeln ausgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11191] = { id = 11191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Leuchtturm", description = "Der alte Leuchtturm draußen im Osten ist schon seit langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, den ganzen Betrieb wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann wesentlich sanfter zu den Docks gelangen. Was kann ich dagegen noch einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", sourceObjective = "Sprecht mit Babs Zischeldrill bei dem Leuchtturm auf der Insel östlich von Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11192] = { id = 11192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drescheröl", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch unelegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Man findet sie genau unterhalb der Docks von Theramore.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", sourceObjective = "Bringt 4 Behälter mit Drescheröl zu Babs Zischeldrill beim Leuchtturm in der Nähe von Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11193] = { id = 11193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimtückische Bewohner der Tiefe", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", sourceObjective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11194] = { id = 11194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das wahr?", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut aufgelacht habt. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran ist?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr ganz sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in der Tidenbucht, welche südwestlich jenseits der Bucht der Düstermarschen liegt.", sourceObjective = "Sprecht mit Nat Pagle bei Nats Angelplatz in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11195] = { id = 11195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel mit der Puppe", description = "Ich bin gerührt, {name}, is' kein Scherz, Mann. Ich kann mich nich' daran erinnern, dass <ein/eine:r> {race} Zungam jemals aus der Patsche geholf'n hätte.\n\nDas hier habe ich einem der Wilden weggenomm'n, als man mich festgebund'n hat. Es sieht zwar nich' nach etwas Großartigem aus, aber wenn jemand den Wert einschätz'n kann, dann ist das mein guter alter Freund Gaunah!\n\nSolltest du hier lebend wieder rauskomm'n, dann statte ihm einen Besuch in Shattrath ab, es lohnt sich.", sourceObjective = "Bringt die zerlumpte Voodoopuppe zu Gaunah in Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[11196] = { id = 11196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsherr der Amani", description = "Die Amani haben ihre Streitmacht wiederaufgebaut und einen neuen Kriegsherrn hervorgebracht, der sie anführt, {name}. Der nennt sich Daakara der Unbesiegbare, aber wir wollen doch mal sehen, ob er seinem Namen gerecht wird.\n\nDu musst erst all seine Handlanger aus dem Weg räumen, bevor du Daakara gegenübertreten kannst. Besieg ihn und bereite den Ambitionen der Zandalari und der Amani ein Ende.", sourceObjective = "Besiegt den neuen Kriegsherrn der Amani, Daakara.", progress = "Dieser neue Kriegsherr muss fallen, bevor die Zandalari hier dauerhaft Fuß fassen können.", completion = "Der Sieg gehört uns, {name}! Die Zandalari fliehen und ohne die Führung ihres Kriegsherrn werden die Amani bald in interne Streitigkeiten verfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11197] = { id = 11197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLD Upper Deck Promo - Ghost Wolf Mount OLD" }
quests[11198] = { id = 11198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt Tethyr!", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", sourceObjective = "Major Mühlens bei den Docks von Theramore möchte, dass Ihr Tethyr bezwingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11199] = { id = 11199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Kundschafter Wisslich", description = "{name}, nun da man sich diese verdammten Proto-Dinger einmal vorgenommen hat, habe ich eine weitere Aufgabe für Euch.\n\nEiner meiner Kundschafter hat mir von verdächtigen Aktivitäten der Verlassenen im Süden berichtet. Es sieht so aus, als würden sie im Vrykuldorf namens Halgrind ihr Unwesen treiben.\n\nIch möchte, dass Ihr die dortigen Ermittlungen persönlich übernehmt. Sprecht mit Kundschafter Wisslich, findet heraus, was er bisher in Erfahrung bringen konnte und macht dort weiter, wo er aufgehört hat.\n\nEr wurde das letzte Mal am Glutspeerturm gleich westlich von Halgrind gesehen.", sourceObjective = "Hauptmann Adams möchte, dass Ihr Euch bei Kundschafter Wisslich am Glutspeerturm meldet.", completion = "Oh, gut, Hilfe - und genau zur rechten Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[11200] = { id = 11200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ore than Coincidence" }
quests[11201] = { id = 11201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Grimtotem Plot" }
quests[11202] = { id = 11202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission 'Ewige Flamme'", description = "Die Verlassen führen nichts Gutes im Schilde und so wie ich das sehe, spielen diese Pestkessel voller Schlamm dabei eine große Rolle.\n\nIch würde vorschlagen, dass wir sie zerstören, bevor man sie für weitere Zwecke verwenden kann. Ich war einmal so frei, ein paar Fackeln aus der Glutstätte schon bereitzustellen. Die Dinger brennen nun schon seit Tagen!\n\nHier, nehmt. Ich kann sie nicht so gut gebrauchen wie Ihr. Sie werden Euch bei der Zerstörung der Kessel von großem Nutzen sein.", sourceObjective = "Kundschafter Wisslich im Glutspeerturm hat vorgeschlagen, dass Ihr mithilfe der Immerbrandfackeln die 4 Pestkessel um Halgrind herum zerstört.", completion = "Fein!\n\nAber was genau war das noch einmal, was Ihr in diesen Kesseln gefunden habt? Wollt Ihr damit sagen, dass die Verlassenen dort unten eine Pest unter den Vrykul verbreiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[11203] = { id = 11203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eek Out Tabetha" }
quests[11204] = { id = 11204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eturn to Krog" }
quests[11205] = { id = 11205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", sourceObjective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11206] = { id = 11206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Walten der Gerechtigkeit", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden. Aber ich habe den Eindruck, dass Euch das vermutlich nicht kümmert. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus \"Zur Süßen Ruh\" bestraft.\n\nGeht und sagt Eurem Vorgesetzten, dass seiner Rache genüge getan wurde.", sourceObjective = "Kehrt zu Krog in Brackenwall zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11207] = { id = 11207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Der Zeppelin hatte Morastwinkels Vorräte für die nächsten sechs Monate geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch auf Dauer ist das keine Lösung.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt, was die Sache ziemlich erschwert. Ohnehin denke ich, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir bei der Bergung helfen?", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11208] = { id = 11208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Drazzit", description = "Drazzit erwartet sicher bald Nachricht von mir, doch solange die Absturzstelle nicht gesichert ist, kann ich hier nicht weg. Würdet Ihr, sofern Ihr etwas Zeit erübrigen könnt, einen Teil der geborgenen Fracht nach Morastwinkel bringen?\n\nFalls Ihr den Weg nicht kennt: die Siedlung liegt südwestlich von hier, hinter den Ruinen der Steinbrecher. Ihr könnt auch die Straße, die von Tabethas Hof wegführt, nehmen. Nachdem Ihr in Morastwinkel angekommen seid, sucht nach einem Typen namens Drazzit Tropfhahn.", sourceObjective = "Bringt die Zeppelinfracht zu Drazzit Tropfhahn in Morastwinkel.", progress = "Ja?", completion = "<Drazzit nimmt die Fracht entgegen.>\n\nIch bin so hungrig, ich könnte glatt einen ganzen Drachen verschlingen! Schön, dass es Moxie endlich gelungen ist, einen Teil der Fracht hierher zu schaffen. Wir waren zuletzt sogar dazu verdammt, mit dem Oger um seine Jagdbeute zu würfeln, ansonsten wären wir verhungert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11209] = { id = 11209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nats Abmachung", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", sourceObjective = "Nat Pagle bei Nats Angelplatz möchte, dass Ihr seinen neuen Köder ausprobiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11210] = { id = 11210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es ist wahr!", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit einem klugen Menschenverstand dergleichen tun.\n\nDas ist also Euer Plan! Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", sourceObjective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11211] = { id = 11211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Morastwinkel", description = "Als diese Goblinfrau... wie war doch gleich ihr Name... Boxie, Foxy... Moxie, genau! Egal, jedenfalls erwähnte sie, als sie auf ihrem Weg zum Zeppelinwrack hier vorbeikam, dass die Siedlung Morastwinkel in Schwierigkeiten wäre.\n\nAnscheinend hatte der abgestürzte Zeppelin wohl Vorräte für die Siedlung geladen. Folgt einfach der Straße südlich von hier, vorbei an den Ruinen der Steinbrecher. Kurz danach solltet Ihr Morastwinkel erreicht haben.\n\nSprecht dort unten mit Drazzit Tropfhahn und seht, ob er nicht Eure Hilfe gebrauchen kann.", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Es war gut, dass Tabetha Euch hierher geschickt hat. Solange der Zeppelin noch nicht geborgen ist, muss ich sie um einige Nahrungsmittel bitten. Leider ist sie selbst gerade knapp an Vorräten. Oh, falls Ihr nach einer Herausforderung sucht: ich habe erst kürzlich ein Kopfgeld auf einen besonders gefährlichen Raptor ausgesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11212] = { id = 11212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Hof", description = "Tief im Herzen des Sumpfs lebt eine alte Frau namens Tabetha. Wir wussten noch nie wirklich viel über sie, außer dass sie älter ist, als sie scheint. Sie hat uns hier von Zeit zu Zeit geholfen und auch den Frieden zwischen der Horde und unseren Kräften schon oft bewahrt.\n\nNormalerweise hörten wir regelmäßig von ihr, aber seit Kurzem ist es still geworden.\n\nKönntet Ihr einmal bei ihr vorbeischauen, falls Ihr Zeit habt? Folgt einfach der Straße jenseits der Nordwacht weiter Richtung Süden und in den Morast. Ihr könnt ihren Hof von der Straße aus sehen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "Gut, dass man Euch von Theramore hierher entsandt hat. Der von Eurem Freund gehegte Verdacht entspricht der Wahrheit. Wir haben ein paar neue Nachbarn... und dabei handelt sich nicht um die Sorte, der man gerne ein Stück Kuchen bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11213] = { id = 11213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht nach Tabetha", description = "Eine Menschenfrau namens Tabetha lebt auf einem kleinen Hof, fast inmitten der Marschen. Normalerweise würde ich mich nicht mit einem Menschen abgeben, aber ihre Hilfe hat sich schon so manches Mal als nützlich erwiesen.\n\nLeider habe ich seit geraumer Zeit nichts mehr von ihr gehört und ich würde mir wünschen, dass jemand zu ihrem Hof reist und nach dem Rechten sieht.\n\nWenn Ihr der Straße aus dem Dorf in Richtung Süden und anschließend ins Innere des Sumpfs folgt, werdet Ihr auf ihren Hof im Herzen des Morasts stoßen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "Welch Glück, dass Nazeer Euch hierher entsandt hat. Wir haben ein paar neue Nachbarn und seit sie ihr Lager hier aufgeschlagen haben, waren sie nichts als Störenfriede.", sourceObjectiveStatus = "unverified-source-field" }
quests[11214] = { id = 11214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission nach Morastwinkel", description = "Das Dampfdruckkartell hat vor Kurzem im südlichen Teil der Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Würdet Ihr für uns dorthin reisen?", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[11215] = { id = 11215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Morastwinkel", description = "Für den neuen Außenposten des Dampfdruckkartells im südlichen Teil der Marschen sieht es momentan nicht so gut aus. Der Zeppelin mit den Vorräten für Morastwinkel ist abgestürzt und nun fehlt es an Werkzeugen, Nahrung und medizinischen Versorgungsgütern.\n\nFolgt der Straße nach Süden in die Marschen. Bevor Ihr Morastwinkel erreicht, führt Euch die Straße zunächst noch an Tabethas Hof und den Ruinen der Steinbrecher vorbei. Bitte helft den Einwohnern von Morastwinkel, so gut Ihr könnt.", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Jede Hilfe ist willkommen! Wir richten uns hier gerade ein und versuchen, das Beste aus unserer Situation hier zu machen, bis die Vorräte des Zeppelins eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11216] = { id = 11216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzmagier Alturus", description = "Mein Mentor hat mich hierher geschickt, um nach Unterstützung zu suchen, aber unglücklicherweise darf ich mich nicht außerhalb des Unteren Viertels aufhalten. Die Leute, die dieses Etablissement besuchen, sind leider alles andere als hilfreich.\n\nIhr scheint anders zu sein, begebt Euch wohl gerne auf Abenteuer. Wenn Ihr uns bei unserem Unterfangen unterstützen wollt, dann sprecht mit Erzmagier Alturus außerhalb von Karazhan, Medivhs alter Behausung.\n\nIch werde versuchen, mir in der Zwischenzeit Zutritt zum Rest der Stadt zu verschaffen. Man munkelt, dass sich ein ehemaliger Kollege von uns hier aufhält.", sourceObjective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan im Gebirgspass der Totenwinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11217] = { id = 11217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwindet den Drachen", description = "Nachdem der Zeppelin mitsamt unseren Vorräten abgestürzt ist, gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun, was wir können, aber inmitten all dieser Insekten, umgeben von Feinden, bleiben Verletzungen nicht aus. Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch unser Pflanzenvorrat geht ebenfalls zur Neige.\n\nMan nennt sie Drachenwinde und sie wächst im Drachendüster und im Drachensumpf östlich der Siedlung. Die Pflanze besteht aus gewundenen Stängeln und wenn man sie ansieht, scheint sie zu pulsieren.", sourceObjective = "Gizzix Rußgurgel in Morastwinkel möchte, dass Ihr ihm 8 Drachenwinden bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11218] = { id = 11218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung! Sprengstoff!", description = "{name}, der Hauptmann hat mich mit einer Mission beauftragt - und ich hätte gerne Eure Hilfe.\n\nEine Truppe meiner Kameraden bei der Forscherliga wurde verrückt, als sie in der Flüsterschlucht im Norden etwas ausgrub. Sie greifen einen jeden an, der versucht, dort hineinzugelangen.\n\nDer Hauptmann ist nur wegen dem Erz für die Wache beunruhigt. Zu unserem Glück habe ich genau das Richtige für unseren Zweck.\n\nGeht dorthin, jagt das Erz in die Luft und bringt es gemeinsam mit allen Edelsteinen, die Ihr finden könnt, zurück. Diesen Laden zu schmeißen ist nicht gerade billig, müsst Ihr wissen!\n\nMuss Euch jedoch warnen - das Erz ist seltsam!", sourceObjective = "Verwendet Stahlrings idiotensicheres Dynamit, um 6 Erzfragmente aus der Flüsterschlucht und 18 Edelsteine aus der Flüsterschlucht zu beschaffen. Bringt die Gegenstände anschließend zu Pionier Stahlring in Westwacht zurück.", progress = "Diesen Ort aufzubauen scheint eine endlose Aufgabe zu sein. Ich hoffe nur, dass Ihr bekommen könnt, was wir benötigen, um weiterzumachen.", completion = "Ihr habt von dem Erz ein seltsames Gefühl bekommen? Vielleicht werden wir das Zeug dann doch nicht verwenden.\n\nDiese Edelsteine sind wirklich hübsch! Ich frage mich, was ich für die bekommen kann? Es gibt natürlich immer Reparaturen zu erledigen und neue Dinge herzustellen.\n\nDoch, ich finde, dass unsere Zusammenarbeit profitabel war. Nehmt dies... es ist das mindeste, was ich machen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[11219] = { id = 11219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht das Feuer!", description = "Die Kinder der Horde brauchen Eure Hilfe, {name}. Der kopflose Reiter, einst ein Paladin der Menschen und jetzt ein wahnsinniger Unhold, hat unser Dorf in Brand gesetzt! Ihr müsst diese Feuer löschen!\n\nSchnappt Euch einen Eimer Wasser und löscht die Flammen damit. Ihr könnt den Eimer auch an einen Verbündeten, der näher bei den Feuern steht, weiterreichen. Löscht alle Feuer und haltet den kopflosen Reiter auf!", sourceObjective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11220] = { id = 11220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kopflose Reiter", description = "Solange der Kopf des kopflosen Reiters nicht vernichtet wird, wird sein verheerendes Wüten kein Ende nehmen.\n\nDer Reiter haust tief im Unglückseligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Geht dorthin und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nDies wird den Unhold hervorrufen. Vernichtet den Kopf des Reiters und er wird uns nie wieder plagen.", sourceObjective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", sourceObjectiveStatus = "unverified-source-field" }
quests[11221] = { id = 11221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichte vom Schlachtfeld", description = "Unsere Mission in Nordend ist es, Arthas zu zerstören. Die Allianz ist hierbei doch nur ein Hindernis, das wir vernichten werden, wo auch immer wir es finden.\n\nWir konnten ihre östlichste Flotte zerstören, doch die Überlebenden haben sich am Verlassenen Strand im Süden verbarrikadiert.\n\nUnsere Streitkräfte hätten ihre provisorischen Verteidigungsanlagen schon vor langer Zeit überrennen sollen – wir haben ihren Überlebenswillen jedoch unterschätzt. Sucht nach der Dunklen Waldläuferin Lyana und Todespirscher Razael, meine Offiziere auf dem Schlachtfeld, und lasst Euch von ihnen über die Situation Bericht erstatten.", sourceObjective = "Sprecht mit der Dunklen Waldläuferin Lyana und Todespirscher Razael. Sie befinden sich auf dem Schlachtfeld in der Blutklamm südlich vom Hafen der Vergeltung. Kehrt zu Hochexekutor Anselm zurück, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Kanonen halten uns auf? Ich werd' denen zeigen, was Kanonen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11222] = { id = 11222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis des Verrats", description = "Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen diejenigen, die ihren Plan ausgeführt haben, die Defias, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.\n\nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit König Varian Wrynn in Burg Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11223] = { id = 11223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Jaina", description = "Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer eine treue Freundin und loyale Verbündete gewesen.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11224] = { id = 11224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickt die Packmulis packen", description = "Mir sind Gerüchte zu Ohren gekommen, nach denen in der Flüsterschlucht im Norden schlimme Dinge passieren. Ein Großteil der Forscherliga ging dorthin - und man sagt, dass das, was sie dort entdeckten, sie in den Wahnsinn trieb.\n\nDas ändert jedoch nichts daran, dass sie die meisten unserer Mulis und den überwiegenden Teil unserer Ausrüstung mitnahmen. Aber die Mulis werde ich nicht verlieren!\n\nFalls Ihr Euch dort herumtreiben solltet und Euch zufällig ein paar Mulis über den Weg laufen, dann müsst Ihr Euch ihnen nur nähern und sie mit erhobener Hand bedrohen. Das wird sie so sehr erschrecken, dass sie bestimmt wieder nach Hause kommen werden.", sourceObjective = "Forscherin Abigail möchte, dass Ihr Euch in die Nähe von 10 verlassenen Packmulis begebt, um jedes Mal Eure Hand zu /heben. Kehrt zu ihr zurück sobald Ihr damit fertig seid. Sie befindet sich in der Westwacht.", completion = "Ich stehe in Eurer Schuld, {class}. Nachdem wir den Großteil unserer Mulis und Ausrüstung wiederbeschafft haben, können wir zumindest darauf hoffen, bald wieder zahlreicher zu sein.\n\nBitte, nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[11225] = { id = 11225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill" }
quests[11226] = { id = 11226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reittier: Spektraltiger" }
quests[11227] = { id = 11227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie Krähen fressen", description = "Der Hochexekutor möchte, dass ich mit meinen Hunden die gegnerischen Späher aufspüre. Aber ich kann Euch das gleich sagen, dass diese Seuchenhunde nirgendwo hingehen, bevor sie nicht richtig gefüttert wurden.\n\nWenn es unserem Militär nicht in den Sinn kommt, dass diese Biester wählerisch genug sind, um den Müll nicht zu fressen, der mir gegeben wurde, dann können sie auch nicht erwarten, dass sie irgendwelchen Nutzen auf dem Schlachtfeld haben werden.\n\nIhr scheint etwas Zeit zu haben. Wieso nehmt Ihr nicht einen der Hunde und geht mit ihm auf Krähenjagd im Westen? Für uns ist ihr Fleisch nicht sehr bekömmlich, doch meine Jungs stehen drauf!", sourceObjective = "Pontius, der Hüter des Zwingers im Hafen der Vergeltung, möchte, dass Ihr mithilfe des Seuchenhundkäfigs einen hungrigen Seuchenhund herbeiruft und diesen dann mit dem Krähenfleisch der Fjordkrähen füttert. Letztere befinden sich westlich des Hafens der Vergeltung.", completion = "Hast du ein paar Krähen gejagt, Junge? Guter Junge, guter Junge!\n\nAh, diese Hunde erinnern mich an die Zeiten, als ich Reinrassige in Tirisfal aufzog... das waren gute Zeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[11228] = { id = 11228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Hölle aus Eis...", description = "Auf Fordragon wird noch etwas zukommen, wenn er denkt, dass die paar Deckschrubber, die er zum Schutz dieses Hafens geschickt hat, noch viel länger durchhalten werden.\n\n<Macalroy begutachtet Eure Ausrüstung und hebt eine Braue.>\n\nEuch könnte es jedoch ein wenig besser ergehen.\n\nWie wichtig es ist, diesen Hafen zu halten, kann nicht genug betont werden - und seitdem diese Monster über unsere Köpfe hinwegfliegen, hat sich die Situation noch verschlechtert.\n\nMeldet Euch bei Vizeadmiral Keller im Nordwesten, nicht weit von hier. Sagt ihm, dass Ihr gekommen seid, um ein paar Hintern zu versohlen und Kaugummi zu kauen - Ihr jedoch keinen Kaugummi mehr habt.", sourceObjective = "Sprecht mit Vizeadmiral Keller im Hafen von Valgarde.", completion = "Der {race} spricht die Wahrheit. Wir können es uns nicht leisten, diesen Hafen zu verlieren. Er ist einer von zwei sicheren Häfen in dieser Eishölle, die der Allianz gehören - der andere liegt ein paar Hundert Meilen westlich von hier, an der Küste der Boreanischen Tundra.", sourceObjectiveStatus = "unverified-source-field" }
quests[11229] = { id = 11229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windläuferflotte", description = "Östlich des Verlassenen Strands sind die Schiffe 'Windläufer', die 'Vergeltung ihrer Majestät' und die 'Ewige Vergessenheit' stationiert. Schickt dem Flottenkommandant Kapitän Harker den Auftrag, dass die Kanonen der Allianz zerstört werden müssen.\n\nSprecht mit unserer Fledermausführerin Kamilla und fragt nach einer Möglichkeit, um zum Standort der Flotte hindurchzukommen. Beeilt Euch, {name}. Jede Minute, die wir gegen die Allianz kämpfen, ist eine Minute, die wir gegen Arthas kämpfen könnten.", sourceObjective = "Sprecht mit Fledermausführerin Kamilla im Hafen der Vergeltung und fragt nach einer Möglichkeit, zur Windläufer hindurchzukommen. Meldet Euch dann bei Kapitän Harker an Bord des Schiffs.", completion = "Ich hoffe, dass Ihr bereit seid, zu kämpfen, {name}. Die Flotte ihrer Majestät braucht Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11230] = { id = 11230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterhalt!", description = "Das hätte ein Kinderspiel sein sollen. Ihre Streitkräfte sind hungrig, verletzt und schlecht ausgerüstet. Doch irgendwie sind wir geradewegs in ihre Falle gelaufen.\n\nZwecks Deckung näherten wir uns dem Riff vom Süden her, worauf wir dann sofort von der Allianz - diesen Hunden - geentert wurden.\n\nLeider muss ich sagen, dass Ihr uns zuerst dabei helfen müsst, unsere Schiffe zurückzubekommen, bevor unsere Kanonen auf irgendetwas schießen können.", sourceObjective = "Kapitän Harker an Bord der Windläufer möchte, dass Ihr 15 Marinesoldaten der Nordflotte tötet.", completion = "Diese Bastarde zurechtzustutzen, war saubere Arbeit. Meine Männer werden sich um den Rest kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11231] = { id = 11231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Schlüsseln und Käfigen", description = "Dem Hauptmann mag es egal sein, aber das wenige was wir wissen ist, dass die Vrykul im nördlich gelegenen Gjalerbron abscheuliche Riten durchführen, die Teil einer Art Erweckungsritual sind.\n\nSie bedienen sich lebendiger Opfer für ihre unheiligen Rituale!\n\n{class}, Ihr müsst dem ein Ende bereiten! Es kommt nicht darauf an, wer oder was in diesen Käfigen ist - egal was, es muss befreit werden. Ich wette, dass die Vrykul die Schlüssel bei sich tragen.\n\nBeim Licht, das letzte was wir gebrauchen können ist, dass noch mehr dieser seltsamen Vrykul umherlaufen; oder sogar schlimmer: dass sie etwas erwecken, das noch boshafter ist.", sourceObjective = "Vater Levariol möchte, dass Ihr genug Schlüssel für einen Gjalerbronkäfig sammelt, um 10 Gefangene von Gjalerbron zu befreien. Kehrt zu ihm zurück, sobald Ihr damit fertig seid. Er befindet sich in Westwacht.", completion = "Gesegnet sollt Ihr sein, mein Kind! Mit Eurer Hilfe scheint das Licht selbst an den dunkelsten Orten.\n\nBitte, nehmt dies. Ein gerechter Lohn für Eure guten Taten. So werde ich mich um das Heil derer kümmern, die Ihr befreit habt - oder zumindest um diejenigen der Zurückgekehrten, die dem Licht wahrhaftig angehören und auf der Seite der Allianz sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11232] = { id = 11232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lenkt unseren Blick", description = "Wir sollten uns den Weg zurück zu unseren Kanonen freikämpfen können. Unglücklicherweise sind die Sichtverhältnisse alles andere als wünschenswert, weswegen Ihr unsere Ziele vom Boden aus markieren müsst.\n\nNehmt diese Rauchsignale mit Euch, geht zur Stellung der Allianz am Verlassenen Strand westlich von hier und markiert mit ihnen die Kanonen, die sich entlang der Nordwand befinden.\n\nSagt Lyana Bescheid, sobald der Weg für die Bodentruppen frei ist. Wir können hier drüben auf uns selbst aufpassen.", sourceObjective = "Markiert mit den Rauchsignalen die Stellen entlang der Nordwand am Verlassenen Strand, an denen sich die Kanonen der Allianz befinden. Meldet Euch bei der Dunklen Waldläuferin Lyana in der Blutklamm, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Ausgezeichnet. Ich werde unseren Bodentruppen signalisieren, dass sie sich in Bewegung setzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11233] = { id = 11233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Todesstoß landen", description = "Ihr habt Euren Wert auf dem Schlachtfeld bewiesen, {name}. Womöglich habt Ihr das Blatt zu unseren Gunsten gewendet.\n\nNun habe ich einen wichtigen Auftrag für Euch. Ich bin mir nicht sicher, wie lange die von uns entdeckte Schwachstelle vorhanden sein wird. Wir müssen uns das Überraschungsmoment zu Nutze machen.\n\nIch möchte, dass Ihr die Verwirrung, die unser Angriff ausgelöst hat, nutzt und Euch hinter die feindlichen Linien begebt, um ihre Anführer zu töten. Diese sind wie folgt nach Rang geordnet: Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric. Viel Glück, {class}.", sourceObjective = "Die Dunkle Waldläuferin Lyana südlich des Hafens der Vergeltung möchte, dass Ihr Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric tötet. Ihr findet sie am Verlassenen Strand.", completion = "Dies ist Ausdruck des unumstrittenen Sieges unserer Streitmacht. Anselm wird sehr erfreut sein, wenn er davon erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11234] = { id = 11234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Anselm", description = "Dann lasst uns doch mal den alten Anselm benachrichtigen. Der Sieg kam später als erwartet - doch besser spät als nie. Sagt ihm, dass unsere Streitkräfte ein paar Stunden benötigen werden, um der Nachhut hier den Rest zu geben.\n\nHoch lebe die Bansheekönigin!", sourceObjective = "Erstattet Hochexekutor Anselm Bericht. Er befindet sich im Hafen der Vergeltung im Heulenden Fjord.", completion = "Wurde auch langsam Zeit. Die Allianz ist uns jetzt schon eine ganze Weile lang ein Dorn im Auge.\n\nWir haben jedoch keine Zeit zum Feiern. Richtet Euren Blick nach Westen - es sieht aus, als hätten wir Besuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11235] = { id = 11235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Gjalerbron fertigwerden", description = "Und nun haben wir ein anderes Problem. Diejenigen meiner Späher, die mit dem Leben davon gekommen sind, haben mir berichtet, dass die Vrykul in ihrer Hauptfestung gen Norden nichts Gutes im Schilde führen.\n\nSie nennen den Ort Gjalerbron - obwohl man das 'Gj' wie ein 'Sch' ausspricht. Seltsame Kreaturen sind das.\n\nAber das ist nicht wichtig. Was wichtig ist, ist, dass Ihr Euch dorthin begebt und das Leben so vieler dieser Kreaturen auslöscht, wie Ihr nur könnt. Findet gleichzeitig heraus, was sie dort treiben.\n\nIch weiß, dass ich mich auf Euch verlassen kann, {name}.", sourceObjective = "Hauptmann Adams möchte, dass Ihr 15 Krieger von Gjalerbron, 8 Runenmagier von Gjalerbron und 8 Schlafwächter von Gjalerbron tötet. Kehrt danach zu ihm zurück. Ihr findet ihn in Westwacht.", completion = "Gute Arbeit, {name}. Ein Glück, dass wir sie los sind!\n\nAber was Ihr über diesen Ort zu berichten habt, macht mir noch immer Sorgen. Ich denke, dass unsere Eindämmungsaktion noch nicht ganz beendet ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[11236] = { id = 11236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrogroßfürst Mezhen", description = "Die Geißel ist in Gjalerbron und sie haben Nekromanten bei sich! Sie versuchen sicherlich, die Vrykul zu Arthas' Gefolgsleuten zu machen.\n\nIch will, dass der Anführer der Nekrolords eliminiert wird!\n\nTut alles, was Ihr könnt, {name}. Aber sorgt dafür, dass Nekrogroßfürst Mezhen und das, was er versucht zu bewerkstelligen, aus der Welt geschafft wird.\n\nEine Allianz zwischen den Vrykul und der Geißel werde ich nicht dulden!\n\nGeht zur Plattform in der hinteren rechten Ecke von Gjalerbron, dort werdet Ihr Mezhen finden.", sourceObjective = "Tötet Nekrogroßfürst Mezhen. Kehrt dann zu Hauptmann Adams zurück. Ihr findet ihn in Westwacht.", completion = "<Der Hauptmann seufzt erleichtert auf.>\n\nTja, das sollte es uns ein wenig einfacher machen.\n\n{name}, Ihr habt immer wieder bewiesen, dass Ihr für Westwacht und die Allianz insgesamt von unschätzbarem Wert seid. Sucht Euch etwas aus der Schatzkammer aus! Es ist das mindeste, was wir tun können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11237] = { id = 11237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne von Gjalerbron", description = "In diesen Plänen wird ein unmittelbar bevorstehender Angriff auf Westwacht bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm Glacion, der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden.\n\nMagierleutnant Malister könnte in dieser Sache sicherlich behilflich sein. Überbringt ihm die Pläne. Ihr findet ihn in der Feste gen Süden.", sourceObjective = "Übergebt die Angriffspläne von Gjalerbron an Magierleutnant Malister. Er befindet sich in Westwacht.", progress = "Was?! Pläne für einen Angriff auf die Wache?\n\nEIN FROSTWYRM?!!!", completion = "{name}, wir dürfen das nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11238] = { id = 11238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Frostwyrm und sein Meister", description = "Das hier zu mir zu bringen, war die richtige Entscheidung, {name}. Ihr müsst zum nördlich gelegenen Gjalerbron gehen und den Wyrm und seinen Meister, Wyrmrufer Elend, niederstrecken.\n\nNoch während wir hier reden könnte der Frostwyrm schon unterwegs sein.\n\nWenn ich die Pläne jedoch richtig verstehe, dann wird Glacion zurückgerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst. Ihr müsst das Wesen besiegen, sobald es landet!\n\nUnd {name}: Bitte bringt mir das Horn. Wir würden es nicht gerne sehen, wenn es wieder in falsche Hände geraten sollte.", sourceObjective = "Erschlagt Wyrmrufer Elend und benutzt das Wyrmruferhorn, um Glacion herbeizurufen und ihn niederzustrecken. Kehrt anschließend gemeinsam mit dem Horn zu Magierleutnant Malister zurück. Er befindet sich in Westwacht.", progress = "Ist der Angriff abgewendet? Wurden der Frostwyrm und sein Meister vernichtet?\n\nHabt Ihr das Horn zurückgebracht?", completion = "Wahnsinn, das Horn ist kalt!\n\nIhr habt Westwacht wieder einmal vor ihrem sicheren Untergang bewahrt. Welch ungewöhnlicher Mann Ihr seid, {name}. Wenn es nur mehr wie Euch geben würde.\n\nTja, das verlangt allerdings nach einer Belohnung. Was würdet Ihr bevorzugen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11239] = { id = 11239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Lichts", description = "Euer Dienst ist beispielhaft gewesen, {name}. Doch es gibt etwas, das mir Sorgen bereitet: die Geißel.\n\nDas Licht kann ihre Anwesenheit nicht dulden und genauso wenig sollen wir es tun. Ich hoffe, dass es nicht zu viel verlangt ist, wenn ich Euch zurück ins nördlich gelegene Gjalerbron schicken würde, damit Ihr die Geißel in diesem abscheulichen Unterschlupf vernichtet! Seht zu, dass Ihr auch in den Hallen des Erwachens unter Gjalerbron nachseht.\n\nReinigung ist der Weg zur Erlösung, mein Kind. Macht uns stolz!", sourceObjective = "Erschlagt 10 ewige Beobachter, 4 furchterregende Schrecken und 2 eitrige Kreaturen. Informiert danach Vater Levariol von Eurem Erfolg. Er befindet sich in Westwacht.", completion = "<Der Priester spricht einen kaum hörbaren Segen für Euch aus.>\n\nSeid gesegnet, {name}. Ihr habt meine Gebete erhört. Steht mit Stolz und erhobenem Kinn im Lichte. Wisset, dass Eure Taten höchst heilig waren!\n\nIch bin mir sicher, dass Euch die Truhen der Kirche etwas Brauchbares bieten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11240] = { id = 11240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Verwirrten", description = "Also, ich sag es nicht gerne, mein Freund, aber während Ihr fort wart, fing der Hauptmann an, ein stärkeres Interesse an diesem Ort zu hegen.\n\nSieht so aus, als wollte er meinen alten Boss bei der Forscherliga dort drin tot sehen. Ich schätze mal, dass wir uns für eine Offensive rüsten, um den Rest von ihnen zu beseitigen. Der Hauptmann will gewissermaßen, dass sie einen Kopf kürzer gemacht werden.\n\nWollt Ihr mir einen Gefallen tun? Geht zurück zur Flüsterschlucht und bereitet Squeeg Götzenjäger ein Ende. Meiner Erinnerung zufolge könnte er sich in der Höhle in der nordwestlichen Ecke befinden.", sourceObjective = "Erschlagt Squeeg Götzenjäger und meldet Euch dann bei Pionier Stahlring in Westwacht.", completion = "<Der Pionier murrt, als wünschte er sich, dass Ihr es nicht geschafft hättet.>\n\nDer Hauptmann wird erfreut darüber sein, dass Ihr Erfolg hattet.\n\nNun ja, Ihr habt so gut bei der Flüsterschluchtsache mitgemacht, wieso sucht Ihr Euch nicht hiervon etwas aus?", sourceObjectiveStatus = "unverified-source-field" }
quests[11241] = { id = 11241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenspur", description = "Danke, dass Ihr mir aus diesem Schlamassel geholfen habt, {name}. Ich habe mich nicht danach gesehnt, zu sehen, was diese Allianzmistkerle für mich auf Lager hatten.\n\nLasst uns von hier verschwinden und schauen wir mal, ob wir es ihnen irgendwie heimzahlen können. Ist das ein Lagerfeuer dort drüben?", sourceObjective = "Eskortiert Apotheker Hanes vom Verlassenen Strand. Meldet Euch bei Apotheker Lysander, sobald Ihr diese Aufgabe abgeschlossen habt. Er befindet sich im Hafen der Vergeltung im Heulenden Fjord.", completion = "Apotheker Hanes ist am Leben? Ihr habt die Vorräte der Allianz verbrannt? Das hat ihm garantiert Riesenspaß gemacht.\n\nAuf jeden Fall steht die königliche Apothekervereinigung in Eurer Schuld, {name}. Unser Dank für Euch kommt aus den Tiefen unserer schwarzen Herzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11242] = { id = 11242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei!", description = "Zorn hielt mich gefangen, {name}, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", sourceObjective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11243] = { id = 11243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falls Valgarde fällt...", description = "Falls Valgarde fällt, wird unser Hauptversorgungsweg nach Nordend zum Stillstand kommen. Von da an wäre es nur eine Frage der Zeit, bis wir alle Diener des Lichkönigs sind. Nun, ich weiß nicht, wie es um Euch steht, aber ich habe eine Frau und drei Kinder in Elwynn - soll mich der Teufel holen, wenn ich ohne einen Kampf unterginge.\n\nDie Situation hier ist kritisch. Wir können jede Unterstützung gebrauchen, die Ihr aufbringen könnt. Begebt Euch zum Eingangstor und helft den Wachen, die Stadt gegen die Eindringlinge zu verteidigen!", sourceObjective = "Vizeadmiral Keller möchte, dass Ihr 12 Eindringlinge der Drachenschinder oder Worge der Drachenschinder tötet. Er befindet sich im Hafen von Valgarde im Heulenden Fjord.", completion = "Ihr habt unseren Verteidigern die nötige Unterstützung gegeben, {name}. Dank Euch ist die Moral höher denn je. Ich denke, dass sie den Rest des Ansturms alleine bewältigen können. Ich habe großes mit Euch vor...", sourceObjectiveStatus = "unverified-source-field" }
quests[11244] = { id = 11244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Retter retten", description = "Wir waren hier seit einem Monat, als diese missgestalteten Riesen aus dem Nichts auftauchten. Für einen Angriff waren wir schlecht vorbereitet und so mussten wir für unsere Selbstgefälligkeit bitter bezahlen. Ein komplettes Archäologenteam war verschwunden und einige Einwohner wurden entführt und zu den Ruinen gebracht. Seitdem sind wir in der Defensive.\n\nZu allem Übel wurden die Späher, die wir zur Rettung unserer Leute aussandten, von den Vrykul mit Harpunen beschossen und im Wald direkt nördlich von Valgarde zum Sterben liegen gelassen. Räumt diese Harpunen aus dem Weg und befreit unsere Späher!", sourceObjective = "Vizeadmiral Keller möchte, dass Ihr 8 Späher von Valgarde rettet, die mit Harpunen beschossen und zum Sterben liegen gelassen wurden. Er befindet sich im Hafen von Valgarde im Heulenden Fjord.", completion = "Was die Vrykul unseren Spähern angetan haben, war ein grausamer Akt der Barbarei. Es war zur Abschreckung gedacht, um unseren Willen zu schwächen... und uns in die Flucht zu schlagen.\n\nEs hat nicht funktioniert.\n\nWir werden diesen Monstern zeigen, was es bedeutet, gegen die Allianz Krieg zu führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11245] = { id = 11245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme des sicheren Untergangs", description = "<Gnädiger Herr/Gnädige Frau>, wenn wir durch Skorn ziehen, müssen wir die Türme zerstören!\n\nWenn Ihr sie Euch anseht, dann werdet Ihr feststellen, dass sich viele Zauberer auf den Türmen befinden. Sich zu nah an sie heranzuwagen, würde für uns den sicheren Tod bedeuten!\n\nWir verfügen jedoch über die Möglichkeit, Kanonensalven aus Westwacht anzufordern. Um das zu tun, müssen wir nahe genug herankommen und ein Leuchtsignal auf die Stelle schießen, wo sich die Magier befinden.\n\nKommt nur nicht zu nah ran!", sourceObjective = "Der Unteroffizier der Westwacht meint, dass es sinnvoll wäre, wenn man mit dem Leuchtsignal des Unteroffiziers die Türme in Skorn markiert, damit sie anschließend unter Kanonenbeschuss genommen werden können.", completion = "Ausgezeichnetes Zielen, gnädiger Herr! Ich darf nicht vergessen, den Kanonieren in der Wache eine Runde auszugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11246] = { id = 11246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausam, aber notwendig", description = "Wir haben Berichte erhalten, nach denen die Vrykul von den Toten auferstehen können - ähnlich der Geißel, doch eine andere Art des Untodes.\n\nLasst uns kein Risiko eingehen.\n\nHier, nehmt meine Machete. Wir werden durch diesen Ort ziehen und Ihr werdet die Überreste der von uns erschlagenen Vrykul zerstückeln müssen. Ich würde es tun, wenn ich keinen empfindlichen Magen hätte.\n\n<Der Unteroffizier lächelt selbstgefällig.>\n\nIch habe den ganzen Morgen damit verbracht, sie zu schärfen - sie sollte also für die Aufgabe geeignet sein.", sourceObjective = "Der Unteroffizier der Westwacht möchte, dass Ihr nach Skorn geht und mit der Machete des Unteroffiziers 20 Vrykul des Winterskornstammes zerstückelt.", completion = "Nun ja, mein Herr – ich muss sagen, dass Ihr mit besonderem Eifer an diese spezielle Sache herangegangen seid.\n\n<Der Unteroffizier blickt Euch misstrauisch an.>\n\nNaja, ich werde meine Machete jetzt wieder zurücknehmen, wenn es Euch recht ist. Sie sieht stumpf aus und wir wollen doch nicht, dass Ihr aus Versehen ausrutscht und mich genauso zerstückelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11247] = { id = 11247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenne, Skorn - brenne!", description = "Hauptmann Adams gab mir strikte Anweisungen, sicherzustellen, dass die Infrastruktur dieses Ortes starken Schaden nimmt.\n\nDa Ihr jedoch hier draußen das Kommando habt, liegt es in Eurem Ermessen, <Sire/Mylady>.\n\nDürfte ich vorschlagen, dass wir beide Langhäuser und die Kaserne, die sich im niedriger gelegenen Teil Skorns befinden, niederbrennen? Dazu müssen wir nur in jedes Gebäude eindringen und diese Fackel hier werfen.", sourceObjective = "Der Unteroffizier der Westwacht hat Befehle erhalten, nach denen Ihr mit der Fackel des Unteroffiziers in Skorn die beiden Langhäuser im Nordosten und -westen sowie die Kaserne in Brand stecken sollt.", completion = "Sehr gut, Sire. Das wäre ohne Eure Hilfe nicht zustande gekommen.\n\nIch bin mir sicher, dass sich der Hauptmann über meinen Bericht freuen wird, sobald wir hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11248] = { id = 11248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Skorns Zorn", description = "{name}, ich muss Euch nun darum bitten, eine Operation durchzuführen, die so gefahrvoll und tödlich ist, dass nur Ihr sie bewältigen könnt.\n\nAn unserer östlichen Grenze befindet sich die Vrykulfestung Skorn. Meine Späher berichten mir, dass diese 'Riesen' kurz davor sind, uns anzugreifen. Meine Streitkräfte sind jedoch über den ganzen Fjord verstreut, weswegen ich nicht über genügend Männer verfüge, um den Ort gewaltsam in Besitz zu nehmen.\n\nIhr werdet stattdessen gerissen sein müssen. Ich habe schon einen Unteroffizier, der über Details in Kenntnis gesetzt ist, vorgeschickt. Zeigt dieses Befehlsinsigne in Skorn vor und er wird sich Euch zeigen und Eure Befehle befolgen.", sourceObjective = "Hauptmann Adams möchte, dass Ihr das Befehlsinsigne der Westwacht in Skorn benutzt und anschließend mit dem Unteroffizier der Westwacht sprecht.\n\nBereitgestellter Gegenstand:", completion = "Sehr angenehm, Euch kennen zu lernen, Sire! Ich freue mich auf unsere Zusammenarbeit.\n\nWo wir gerade davon reden: Wir haben jede Menge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11249] = { id = 11249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert seinen Aufstieg!", description = "Diese riesige Schriftrolle ist aus Drachenhaut gefertigt. Ihr entrollt die mehr als zehn Meter lange Schriftrolle und seht, dass die Bilder auf ihrer schuppigen Oberfläche ein rätselhaftes Vrykulritual darstellen.\n\nEin Than der Vrykul, umgeben von engelhaften Wesen, steigt in den Himmel auf. Eine rätselhafte finstere Figur zeichnet sich vom Hintergrund des Bildes ab.\n\nIhr habt eine ungute Vorahnung, dass der Than von Skorn im Begriff ist, genau dies zu tun. Ihr müsst das verhindern! Vor der Hütte des Thans, auf Skorns höchstem Punkt, steht ein großer Scheiterhaufen.", sourceObjective = "Präsentiert die Vrykulrolle des Aufstiegs in der Nähe des Scheiterhaufens vor der Hütte des Thans, um ihn herauszurufen und ihn niederzustrecken. Ihr seid Euch sicher, dass Vater Levariol an dem Ritual und damit auch an der Schriftrolle Interesse finden wird. Er befindet sich in Westwacht.", progress = "Ja? Wie kann ich Euch behilflich sein, mein Kind?", completion = "Ja, mein Sohn, dies könnte Unheil bedeuten. Ihr habt offenbar richtig gehandelt.\n\nDanke, dass Ihr mir diese Schriftrolle gebracht habt. Ich kann es kaum erwarten, herauszufinden, was sie zu bedeuten hat. Würde ich es wagen, eine Vermutung anzustellen, dann würde ich behaupten dass die Vrykul einen Weg haben, um den Tod zu überwinden. Oder zumindest diejenigen, die dessen würdig sind.\n\nIndem Ihr den Than der Winterskorn besiegt habt, habt Ihr bewiesen, dass er unwürdig war. Nur das Licht weiß, was aus ihm geworden wäre und welch Schrecken er über uns gebracht hätte, hättet Ihr ihn nicht erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11250] = { id = 11250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch lebe der Eroberer von Skorn!", description = "Wir - oder eher Ihr - haben alles getan, zu dessen Erfüllung wir hier her gekommen sind, <Sire/Mylady>. Ich muss sagen, dass es mir eine Freude war, von solch <einem jungen Mann/einer jungen Frau> Befehle zu erhalten.\n\nDer Hauptmann will höchstwahrscheinlich von Eurem Erfolg in Kenntnis gesetzt werden. Solltet Ihr jedoch aus irgendeinem Grund hier bleiben wollen, dann stehe ich Euch zur Verfügung.", sourceObjective = "Bringt das Befehlsinsigne der Westwacht zu Hauptmann Adams zurück. Ihr findet ihn in Westwacht.", progress = "Ich schließe mal aus Eurer Anwesenheit, dass es Skorn nicht mehr gibt. Lieg' ich da richtig?", completion = "Das sind unglaublich gute Neuigkeiten! Ich wusste, dass Ihr es schaffen würdet, {name}!\n\nWenigstens einer, der hier Resultate liefern kann!\n\nTja, das verlangt nach einer Belohnung. Nur zu, sucht Euch etwas aus - für Euch steht die Schatzkammer offen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11251] = { id = 11251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Abschnitt", description = "Der Preis war hoch, aber wir konnten die Untersuchung der Ausgrabungsstätte beenden.\n\nKeine guten Neuigkeiten - fast jeder wurde erschlagen oder gefangen genommen. Es werden nur ein paar Wächterveteranen vermisst.\n\nWir Späher haben alles getan, was wir hier tun können. Ihr müsst dort weitermachen, wo wir aufgehört haben.\n\nVom Hügel im Nordosten aus dringen Geräusche eines Gefechts herüber. Seht einmal nach, {class}. Wir können nur darauf hoffen, dass es ein paar Überlebende gibt und dass sie Informationen haben, die wir gegen diesen Feind verwenden können.", sourceObjective = "Kundschafterin Valory möchte, dass Ihr den Geräuschen nachgeht, die vom nordöstlichen Teil von Wyrmskol herstammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11252] = { id = 11252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Utgarde!", description = "Zugehört, <Junge/Mädchen>. Ich habe meinen Teil dieser Kreaturen erledigt – und übrigens Euren Teil gleich mit. Was Ihr wissen müsst, ist Folgendes...\n\nDie Vrykul sind furchtlose Kämpfer. Scheint so, als sehnten sie sich danach, im Kampf zu sterben. Ihre Zahl und Wildheit bedeutet für uns den Untergang, um es einfach auszudrücken.\n\nEs gibt jedoch einen, den sie hoch schätzen. Man nennt ihn Ingvar. Ich weiß nicht, wieso sie um seine Gunst werben, aber wenn Ihr ihn tötet, wird das ihr Selbstvertrauen erschüttern.\n\nVielleicht werden wir dann eine Chance haben...", sourceObjective = "Verteidiger Mordun hat Euch mit der Exekution von Ingvar dem Brandschatzer, der tief in Utgarde wohnt, beauftragt.\n\nAnschließend sollt Ihr dessen Kopf zu Vizeadmiral Keller bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11253] = { id = 11253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind ausschnüffeln", description = "Nun, da der Bengel einen vollen Magen hat, wird er vielleicht eher dazu geneigt sein, zu kooperieren. Hier ist seine Leine. Ihr müsst ihn dann nur noch aus seinem Käfig holen, sobald Ihr bereit seid.\n\nIch weiß zwar nicht, welchen Fund sich Anselm von Euch verspricht, aber sucht nach Hinweisen, wo auch immer der Hund Euch hinführen mag.", sourceObjective = "Benutzt die Seuchenhundleine in der Nähe der Seuchenhundkäfige im Hafen der Vergeltung und sucht dort nach Hinweisen, wo der Seuchenhundfährtenleser Euch hinführt.\n\nBereitgestellter Gegenstand:", completion = "Die schuppige Schriftrolle ist mit schlicht gezeichneten Bildern bedeckt. Ihr habt das Gefühl, dass dies genau das ist, woran der Hüter des Zwingers gedacht hat, als er Euch darum bat, nach Hinweisen zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11254] = { id = 11254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karte aus Drachenhaut", description = "Nach genauerer Untersuchung scheint es sich bei der Schriftrolle um eine Karte des Fjords zu handeln, die mit vielen Bildern versehen ist. Die Lage verschiedener Dörfer wird mithilfe von Markierungen dargestellt, die wie Stammessymbole aussehen.\n\nDer Standort des Hafens der Vergeltung wird mit einem unverhältnismäßig großen Totenschädel markiert.\n\nFür Hochexekutor Anselm wird diese Karte höchstwahrscheinlich von militärischem Wert sein.", sourceObjective = "Bringt die Karte aus Drachenhaut zu Hochexekutor Anselm im Hafen der Vergeltung.", progress = "Ihr habt etwas, das Ihr mir zeigen wollt, {class}?", completion = "<Der Hochexekutor betrachtet aufmerksam die Karte und lässt ab und an den Blick schweifen, um im Fjord nach Landmarken zu suchen.>\n\nDa drüben befindet sich der östliche Küstenstrich. Die Dörfer der Drachenschinder und Winterskorn befinden sich hier und hier... und das hier oder diejenigen, die zum Töten freigegeben sind, sind wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[11255] = { id = 11255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene in Wyrmskol", description = "Diese Schlacht ist noch lange nicht vorbei, {name}. Wenn unsere Leute, die sich in dem Dorf befinden, noch immer am Leben sind, dann muss jemand dort hingehen und sie befreien.\n\n<Vizeadmiral Keller nickt Euch zu.>\n\nGeht nach Wyrmskol im Norden und seht Euch nach unseren Leuten um, sobald Ihr dort seid. Sollten sie irgendwo eingesperrt sein, dann müsst Ihr einen Weg finden, sie zu befreien.\n\nVielleicht haben sie etwas mehr Kunde über das, was wir hier wirklich bekämpfen.", sourceObjective = "Vizeadmiral Keller im Hafen von Valgarde im Heulenden Fjord möchte, dass Ihr 3 Gefangene aus Valgarde befreit.", completion = "Die Soldaten, die Ihr befreit habt, konnten uns einiges berichten. Diese Monster nennen sich 'Vrykul'. Der Stamm, der sich in Wyrmskol niedergelassen hat, wird von einem Mystiker namens Yanis angeführt, ein Untergebener von Ingvar dem Brandschatzer - auch ein Vrykul.", sourceObjectiveStatus = "unverified-source-field" }
quests[11256] = { id = 11256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorn muss fallen!", description = "{name}, gen Süden befindet sich die Vrykulfestung Skorn. Die seltsamen Riesen, die dort wohnen, sind vor Kurzem erwacht und haben damit begonnen, uns anzugreifen, wo auch immer es ihnen möglich ist.\n\nMeine Späher berichten mir, dass sie kurz davor sind uns hier anzugreifen. Wir sind jedoch nicht stark genug, um solch eine Streitmacht abzuwehren. Stattdessen werden wir uns aufmachen und gen Norden, in weniger gefährliche Lande, ziehen.\n\nIch bitte Euch, dass Ihr Euch etwas Schlaues einfallen lasst, um uns etwas Zeit zu verschaffen. Einen Mutigen, der über Näheres in Kenntnis gesetzt ist, habe ich schon vorgeschickt. Wenn Ihr dieses Emblem in Skorn vorzeigt, wird er sich zeigen und Euch so gut wie möglich zur Seite stehen.", sourceObjective = "Häuptling Aschtotem möchte, dass Ihr das Emblem der Winterhufe in Skorn benutzt und dann mit dem Helden der Winterhufe sprecht.\n\nBereitgestellter Gegenstand:", completion = "Es wird interessant sein, an Eurer Seite zu kämpfen und etwas über Euer Volk zu lernen, {class}.\n\nWollen wir fortfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[11257] = { id = 11257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausam, aber notwendig", description = "Unsere Ältesten erzählen uns, dass die Vrykul womöglich von den Toten auferstehen können - ähnlich den wandelnden Toten, die Ihr Geißel nennt, doch eine andere Art des Untodes.\n\nWir sollten kein Risiko eingehen.\n\nHier, nehmt meine Machete. Wir werden durch diesen Ort ziehen und Ihr zerstückelt die Überreste der von uns erschlagenen Vrykul.\n\nIch habe den ganzen Morgen damit verbracht, sie zu schärfen - sie sollte also selbst den dicksten Knochen spalten.", sourceObjective = "Der Held der Winterhufe möchte, dass Ihr mit der Machete des Kriegerhelden 20 Vrykul des Winterskornstammes in Skorn zerstückelt.", completion = "Habt Ihr das schon einmal gemacht? Ihr scheint im Umgang mit der Machete geübt zu sein.\n\n<Der Held sieht Euch misstrauisch an.>\n\nIch werde sie Euch jetzt wieder wegnehmen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11258] = { id = 11258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenne, Skorn - brenne!", description = "Häuptling Aschtotem hat mir befohlen, viele Gebäude hier zu zerstören.\n\nIhr habt aber die Verantwortung, also ist es auch Eure Aufgabe, {name}.\n\nIch schlage vor, wir brennen die zwei Langhäuser und die Kaserne ab, die im tieferen Bereich von Skorn stehen. Alles, was wir zu tun haben, ist in jedes Gebäude hineinzugehen und es mit dieser Fackel in Brand zu stecken.", sourceObjective = "Der Held der Winterhufe schlägt vor, dass Ihr mit der Fackel des Helden in Skorn die zwei Langhäuser im Nordosten und -westen sowie die Kaserne in Brand setzt.", completion = "<Der Held nickt Euch zu, von Eurem guten Umgang mit der Fackel überzeugt>\n\nLasst diese Vrykul die Hitze dieses Landes spüren. Lasst sie die Furcht kennenlernen, die sie anderen aufzwingen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11259] = { id = 11259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme des sicheren Untergangs", description = "Wenn wir durch Skorn ziehen, müssen wir die Türme zerstören.\n\nWenn Ihr sie Euch genau anseht, dann werdet Ihr feststellen, dass sich viele Zauberer auf den Türmen befinden. Sich zu nah heranzuwagen bedeutet den sicheren Tod.\n\nWir können jedoch Windreiterunterstützung aus dem Lager der Winterhufe anfordern. Um das zu tun, müssen wir nahe genug herankommen und ein Leuchtsignal auf die Stelle schießen, wo sich die Magier befinden.\n\nKommt nur nicht zu nah ran.", sourceObjective = "Der Held der Winterhufe meint, dass es sinnvoll wäre, wenn man mit dem Leuchtsignal des Kriegerhelden die Türme in Skorn für Luftangriffe markiert.", completion = "Ihr habt einen starken Arm, {name}.\n\nSieht so aus, als würden sich die Windreiter endlich einmal nützlich erweisen anstatt den ganzen Tag nur rumzustehen und zu trinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11260] = { id = 11260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert seinen Aufstieg!", description = "Diese riesige Schriftrolle ist aus Drachenhaut gefertigt. Ihr entrollt die mehr als zehn Meter lange Schriftrolle und seht, dass die Bilder auf ihrer schuppigen Oberfläche ein rätselhaftes Vrykulritual darstellen.\n\nEin Than der Vrykul, umgeben von engelhaften Wesen, steigt in den Himmel auf. Eine rätselhafte finstere Figur zeichnet sich vom Hintergrund des Bildes ab.\n\nIhr habt eine ungute Vorahnung, dass der Than von Skorn im Begriff ist, genau dies zu tun. Ihr müsst das verhindern! Vor der Hütte des Thans, auf Skorns höchstem Punkt, steht ein großer Scheiterhaufen.", sourceObjective = "Präsentiert die Vrykulrolle des Aufstiegs in der Nähe des Scheiterhaufens vor der Hütte des Thans, um ihn herauszurufen und ihn niederzustrecken. Ihr seid Euch sicher, dass Großmutter Ankha an dem Ritual und damit auch an der Schriftrolle Interesse finden wird. Sie befindet sich im Lager der Winterhufe.", progress = "Ja? Wie kann ich Euch behilflich sein, Kind?", completion = "Ja, dies könnte Unheil bedeuten. Ihr habt offenbar richtig gehandelt.\n\nDanke, dass Ihr mir diese Schriftrolle gebracht habt. Ich werde herausfinden, was sie zu bedeuten hat. Würde ich es wagen, eine Vermutung anzustellen, dann würde ich behaupten dass die Vrykul einen Weg haben, um den Tod zu überwinden. Oder zumindest diejenigen, die dessen würdig sind.\n\nIndem Ihr den Than der Winterskorn besiegt habt, habt Ihr bewiesen, dass er unwürdig war. Nur das Licht weiß, was aus ihm geworden wäre und welch Schrecken er über uns gebracht hätte, hättet Ihr ihn nicht erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11261] = { id = 11261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bezwinger von Skorn!", description = "Ihr habt alles getan, wofür wir hierher ausgesandt wurden, {class}. Ich muss zugeben, dass Ihr gut kämpft. Eure Leute sind nicht so merkwürdig, wie ich es zu Anfang dachte.\n\nHäuptling Aschtotem will sicherlich von Eurem Erfolg erfahren, aber solltet Ihr Euch entscheiden aus irgendeinem Grund hier zu bleiben, werde ich weiter an Eurer Seite kämpfen.", sourceObjective = "Bringt das Zeichen der Winterhufe zu Häuptling Aschtotem im Lager der Winterhufe zurück.", progress = "Welche Neuigkeiten aus Skorn bringt Ihr, {name}?", completion = "Das sind in der Tat gute Neuigkeiten! Ihr habt uns etwas mehr Raum zum Atmen verschafft, nun können wir unsere Abreise weiter vorbereiten.\n\nBitte, nehmt etwas davon als Zeichen unserer Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11262] = { id = 11262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingvar muss sterben!", description = "Von unserer gesamten Aufklärungstruppe bin nur ich übrig geblieben.\n\nDiese Vrykul sind erbarmungslose Kämpfer. Angesichts ihrer Zahl und brutalen Taktiken ist es unsere einzige Hoffnung, ihren Anführer zu erschlagen. Beten wir dafür, dass sie das ins Chaos stürzen wird.\n\nIngvar ist sein Name. Bringt mir seinen Kopf!", sourceObjective = "Die Dunkle Waldläuferin Marrah möchte, dass Ihr Ingvar den Brandschatzer in Burg Utgarde tötet.", progress = "Das ist sozusagen nur die Spitze des Eisbergs.", completion = "Ausgezeichnete Arbeit, {name}. Nun da sie keinen Anführer mehr haben, sollte unser Kampf gegen die Vrykul von größerem Erfolg gekrönt sein.\n\nDienste wie diese dürfen nicht unbelohnt bleiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11263] = { id = 11263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Gjalerbron fertigwerden", description = "Meine Fernläufer, die überlebten und zurückkehren konnten, haben mir berichtet, dass die Vrykul in ihrer Hauptfestung im Westen erwacht sind.\n\nEs ist ein verbotener Ort, der als Gjalerbron bekannt ist. Die Langläufer sagen, dass die Vrykul dort seltsame Rituale durchführen.\n\nWir können nicht gestatten, dass das so weitergeht.\n\nWärt Ihr bereit, uns weiter zu unterstützen? Werdet Ihr die Vrykul am Gjalerbron töten, bevor sie ihr Vorhaben beenden und uns hier angreifen?", sourceObjective = "Häuptling Aschtotem hat Euch gebeten, 15 Krieger von Gjalerbron, 8 Runenmagier von Gjalerbron und 8 Schlafwächter von Gjalerbron zu töten. Kehrt im Anschluss zu ihm im Lager der Winterhufe zurück.", completion = "Ihr habt meinen Dank, {name}. Ich weiß, dass Ihr weder mir noch meinem Volk verpflichtet seid.\n\nWas Ihr über diesen Ort sagt, besorgt mich noch immer und ich spüre, dass unser Feldzug noch nicht beendet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11264] = { id = 11264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrogroßfürst Mezhen", description = "Die Toten sind am Gjalerbron und sie haben Nekromanten bei sich?\n\nWir müssen den Anführer dieser Nekrolords beseitigen.\n\nWie auch immer Ihr es fertig bringt, {name}, aber stellt sicher, dass Nekrogroßfürst Mezhen und sein Vorhaben ausgelöscht werden.\n\nWir können es uns nicht leisten, dass die Vrykul Erfolge verbuchen, was auch immer sie mit diesen Untoten anstellen!\n\nGeht zur Plattform in der hinteren rechten Ecke von Gjalerbron, dort werdet Ihr Mezhen finden.", sourceObjective = "Tötet Nekrogroßfürst Mezhen. Kehrt danach zu Häuptling Aschtotem im Lager der Winterhuf zurück.", completion = "<Häuptling Aschtotem atmet erleichtert durch.>\n\nDas sollte den Druck etwas mildern.\n\n{name}, wieder und wieder habt Ihr Euren Wert für das Lager der Winterhufe bewiesen. Bitte, wählt etwas von unseren Gaben. Ich bestehe darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[11265] = { id = 11265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Schlüsseln und Käfigen", description = "Das Wenige, was wir wissen, ist, dass die Vrykul im westlich gelegenen Gjalerbron abscheuliche Riten durchführen, die Teil einer Art Erweckungsrituals sind.\n\nSie bedienen sich lebendiger Opfer für ihre Rituale.\n\n{name}, Ihr müsst dem ein Ende bereiten! Es kommt nicht darauf an, wer oder was in diesen Käfigen ist - egal was, es muss befreit werden. Ich wette, dass die Vrykul die Schlüssel bei sich tragen.\n\nDie Vrykul stellen eine Gefahr für uns dar, und das Letzte, was wir gebrauchen können, sind noch mehr dieser seltsamen Kreaturen - oder schlimmer: dass sie Etwas erwecken, das noch böser ist...", sourceObjective = "Großmutter Ankha möchte, dass Ihr genug Schlüssel für einen Gjalerbronkäfig sammelt, um 10 Gefangene von Gjalerbron zu befreien. Kehrt zu ihr zurück, sobald Ihr damit fertig seid. Sie befindet sich im Lager der Winterhufe.", completion = "Mir fällt ein großer Stein vom Herzen, zu hören, dass Ihr erfolgreich wart. Und es bereitet mir Freude zu wissen, dass einige der Befreiten Taunka sind.\n\nBitte, nehmt dies als Gegenleistung für Eure Taten. Ich werde mich um die Wunden der Befreiten kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11266] = { id = 11266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne von Gjalerbron", description = "In diesen Plänen wird ein unmittelbar bevorstehender Angriff auf das Lager der Winterhufe bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm Glacion, der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden.\n\nCelea Frostmähne könnte in dieser Sache sicherlich behilflich sein. Überbringt ihr die Pläne. Ihr findet sie im Lager im Osten.", sourceObjective = "Übergebt die Angriffspläne von Gjalerbron an Celea Frostmähne. Sie befindet sich im Lager der Winterhufe.", progress = "Was?! Pläne für einen Angriff auf unser Lager?\n\nEIN ANGRIFF AUS DER LUFT?! EIN GROSSER WYRM?!!!", completion = "{name}, wir dürfen das nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11267] = { id = 11267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Frostwyrm und sein Meister", description = "Das hier zu mir zu bringen, war die richtige Entscheidung – Euer Instinkt hat Euch gut beraten. Meine Windreiter würden jedoch mit einem Drachen nicht fertigwerden. Ihr müsst zum westlich gelegenen Gjalerbron gehen und den Wyrm und seinen Meister, Wyrmrufer Elend, niederstrecken.\n\nDer Frostwyrm könnte sich schon auf den Weg gemacht haben!\n\nWenn ich die Pläne jedoch richtig verstehe, dann wird Glacion zurückgerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst. Vernichtet die Kreatur, nachdem sie gelandet ist!\n\nUnd {name}: Bitte bringt mir das Horn. Wir würden es nicht gerne sehen, wenn es wieder in falsche Hände geraten sollte.", sourceObjective = "Erschlagt Wyrmrufer Elend und benutzt das Wyrmruferhorn, um Glacion herbeizurufen und ihn niederzustrecken. Kehrt anschließend gemeinsam mit dem Horn zu Celea Frostmähne zurück. Sie befindet sich im Lager der Winterhufe.", progress = "Ist der Angriff abgewehrt? Wurden der Frostwyrm und sein Meister vernichtet?\n\nHabt Ihr das Horn zurückgebracht?", completion = "Dieses Horn ist so kalt wie das Land... vielleicht sogar kälter!\n\nIhr habt das Lager der Winterhufe vor seinem sicheren Untergang bewahrt - was jedoch nicht heißen soll, dass wir hier noch viel länger bleiben werden. Was für ein eigenartiger Mann Ihr seid, {name}. Vielleicht ist Euer Volk von der anderen Seite des Ozeans im Grunde genommen doch nicht so böse.\n\nDas verlangt nach einer Belohnung. Was würdet Ihr vorziehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11268] = { id = 11268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wandelnden Toten", description = "Ihr wart uns eine riesengroße Hilfe, {name} - es gibt jedoch Etwas, das mir Sorgen bereitet: die sogenannte Geißel.\n\nDie Geister der Erde und Luft, des Wassers und des Feuers im Inneren der Welt würden zwar ihre Anwesenheit nicht dulden, scheinen jedoch nichts dagegen zu unternehmen. Wir werden dafür sorgen, dass man sich um sie kümmert!\n\nVielleicht ist es zu viel verlangt, aber ich hätte es gerne, dass Ihr zurück gen Westen nach Gjalerbron geht und die unnatürlichen Kreaturen der Geißel in diesem abscheulichen Nest vernichtet. Seht zu, dass Ihr auch in den Hallen des Erwachens unter Gjalerbron nachseht!", sourceObjective = "Tötet 10 ewige Beobachter, 4 furchterregende Schrecken und 2 eitrige Kreaturen. Bringt anschließend Nachricht Eures Erfolgs zu Großmutter Ankha im Lager der Winterhufe.", completion = "<Die Großmutter nickt zustimmend angesichts Eurer Taten.>\n\nIch danke Euch, {name}, Ihr habt das Richtige getan und uns damit ein wenig mehr Zeit verschafft, um unseren Abmarsch vorzubereiten. Wir werden schon bald gen Norden ziehen.\n\nIch bin zu alt - wenn es soweit ist und wir gehen, werde ich nicht alles mit mir tragen können. Hättet Ihr hiervon gerne etwas?", sourceObjectiveStatus = "unverified-source-field" }
quests[11269] = { id = 11269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daunen in letzter Minute", description = "Die Vorhut der Truppen der Allianz wird in ein paar Tagen eintreffen. Die Soldaten werden ihre Winterausrüstung erwarten und ich hab' noch nicht alle Umhänge angefertigt, die sie benötigen.\n\nFür das Futter der Umhänge verwende ich die Daunen von gefleckten Hippogryphen, doch mein Vorrat wird nicht ausreichen!\n\nIhr müsst mir helfen, {name}. Hauptmann Adams wird sich mir vorknüpfen, wenn die Umhänge nicht rechtzeitig fertig sind! Bringt mir alle Daunen, die Ihr dort draußen finden könnt. Sie werden von mausernden Hippogryphen, die in der Wildnis um das Fort herum anzutreffen sind, fallengelassen.", sourceObjective = "Gil Grisert möchte, dass Ihr ihm 10 Büschel Daunen eines gefleckten Hippogryphen bringt.", progress = "Habt Ihr mir ein paar Daunen gebracht? Ich könnte sie wirklich gut gebrauchen...", completion = "Da bin ich aber erleichtert! Dies sollte genügen, um die bestellten Umhänge noch rechtzeitig herzustellen. Bevor die Truppen ankommen, werde ich natürlich keinen Schlaf finden, doch das ist noch immer um einiges besser, als Hauptmann Adams' Zorn ertragen zu müssen.\n\nIch kenne die Geschichten, die man über ihn erzählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11270] = { id = 11270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg ist die Hölle", description = "Wir beseitigen langsam die Überbleibsel von Sturmwinds Nordflotte, die an dieser Küste vor Anker lag. Die Leichen im Westen sind ein Zeichen dafür, wie brutal die Konfrontation gewesen ist.\n\nEs berührt zwar meinen feinen Sinn für Ästhetik nicht im Geringsten, stellt jedoch eine Gefahr für unser aller Leben dar.\n\nIm Reich des Lichkönigs sind die Toten eine Waffe, die jederzeit gegen uns verwendet werden kann. Nehmt diese Fackel - Ihr werdet dafür sorgen, dass das nicht geschieht.", sourceObjective = "Hochexekutor Anselm im Hafen der Vergeltung möchte, dass Ihr mithilfe der brennenden Fackel 10 der Leichen, die westlich des Orts herumliegen, verbrennt.", completion = "Ich bin froh, dass Ihr Befehle befolgen könnt. Wenn man mir ein Kupferstück für jeden arroganten Narren in glänzender Rüstung gäbe, der hierher kommt und denkt, dass er tun und lassen kann, wie ihm beliebt... tja, dann hätte ich schon ein paar Goldstücke beisammen.\n\nNun, da Ihr einen gewissen Grad an Disziplin bewiesen habt, hätte ich ein paar Aufgaben anzubieten, die für jemanden wie Euch besser geeignet wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[11271] = { id = 11271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hastige Vorbereitungen", description = "Die Daunen des gefleckten Hippogryphen werden von meinem Volk hoch geschätzt und werden bei uns für alles verwendet - von der Pfeilmacherei, bis hin zu zeremoniellen Gewändern. Wir bereiten uns darauf vor, diesen Posten zu verlassen, also ist das meine letzte Chance in dieser Saison, sie zu sammeln.\n\nMit Eurer Hilfe werde ich genug zusammenbekommen, um jedem die nötige Ausrüstung für den Marsch durch die Hügel bieten zu können. Die Bedingungen verschlechtern sich sehr schnell dort oben und jederzeit könnte ein Sturm ohne Vorwarnung aufziehen.\n\nDie Daunen liegen rings um den Posten herum auf dem Boden.", sourceObjective = "Ahota Weißfrost im Lager der Winterhufe möchte, dass Ihr ihm 10 Büschel Daunen eines gefleckten Hippogryphen bringt.", progress = "Habt Ihr schon ein paar Daunen gesammelt?", completion = "Dank Eures Beitrags werden wir gut auf die Reise vorbereitet sein. Ich habe nicht viel, das ich Euch für Eure Hilfe anbieten könnte, aber ich werde Euch etwas aus meiner übrigen Kampfausrüstung aussuchen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11272] = { id = 11272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rechnung begleichen", description = "Glaubt dieser Elfenprinz etwa, dass er in meine Stadt kommen, meine Königin beleidigen, meine Leute töten und mit all dem davonkommen kann? Glaubt er, dass wir untätig zusehen werden, wenn Utgardes Horden sich auf einen Angriff vorbereiten?\n\nNicht in einer Million Jahre.\n\nIhr werdet direkt nach Utgarde gehen und ihn töten. Ich will, dass Arthas von unserer Ankunft erfährt und weiß, dass wir es ernst meinen.\n\nMeldet Euch bei der Dunklen Waldläuferin Marrah in der Burg Utgarde, wenn Ihr die Tat vollbracht habt, und sie wird sich um eventuelle Folgen kümmern.", sourceObjective = "Hochexekutor Anselm möchte, dass Ihr Prinz Keleseth in Burg Utgarde tötet.", completion = "Keleseth ist aus dem Weg geräumt? Großartig!\n\nDas wird unsere Aufgabe hier einfacher machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11273] = { id = 11273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Menschenliga", description = "Wir waren kurz davor, einen sensationellen archäologischen Fund zu machen, als wir von diesen Monstern angegriffen wurden! Leider war ich der Einzige, der es zurück nach Valgarde schaffte. Nun weiß ich nicht, ob meine Mannschaft tot oder am Leben ist, aber die Artefakte, die wir damals ausgruben, müssen gefunden werden!\n\nFalls Ihr nach Wyrmskol gehen solltet, würdet Ihr dann nach meiner Mannschaft Ausschau halten? Wenn es noch Hoffnung gibt, dass die Informationen geborgen werden können, müssen wir versuchen, sie zurückzubekommen!\n\nSucht zuerst nach Pulroy. Ihn habe ich als letzten gesehen, bevor ich flüchtete.", sourceObjective = "Sucht Wyrmskol nach Pulroy ab.", completion = "Ihr habt Pulroy gefunden - jedoch ein wenig zu spät wie es aussieht.\n\nWährend Ihr den Leichnam genauer betrachtet, fällt Euch ein Tagebuch auf, das fest von Pulroys totenstarrer Hand umklammert wird. Ihr seht Euch das Buch genauer an und stolpert über Etwas, das wie das Gekritzel eines sterbenden Zwergs aussieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11274] = { id = 11274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zedd ist wahrscheinlich tot", description = "An den Finder dieses Tagebuchs:\n\nDiese blutrünstigen Scheusale haben sich in den Ruinen von Wyrmskol eingenistet. Was genau sie wollen und wieso sie hier sind, ist ein Rätsel. Auf jeden Fall sind die Artefakte nicht sicher, solange sich diese Menschenbestien hier herumtreiben.\n\nZedd und ich haben etwas entdeckt, als wir uns versteckt haben: eine Glyphe, mit der man die Schrifttafeln entziffern kann! Unglücklicherweise wurden Zedd und ich letzte Nacht voneinander getrennt. Er hatte die Glyphe. Glorenfeld und Daegarn hatten die Schrifttafeln bei sich. Wo sie sind, weiß ich nicht...\n\nFindet Zedd.\n\n-Pulroy", sourceObjective = "Sucht Wyrmskol nach Zedd ab.", completion = "Ihr habt Zedd gefunden. Ihr seid zwar kein Doktor, aber die Prognose für Zedd würde sicherlich negativ ausfallen.\n\nEs sieht so aus, als hätten sie versucht, ihn an die Worge zu verfüttern. Scheußlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11275] = { id = 11275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn schnitzen", description = "Mein Volk jagt schon seit Generationen die Riesenyeti in diesen Hügeln und dieses Jahr werde ich zum ersten Mal daran teilnehmen. Es wird wahrscheinlich die letzte Jagd sein, bevor wir den Posten für immer verlassen.\n\nUm mich auf die Jagd vorzubereiten, muss ich ein lautes Blashorn aus den Geweihen der Frosthornböcke herstellen, die durch die verschneite Gegend in der Nähe unseres Lagers streifen. Die Ältesten meinen, dass der Ton des Horns dem Paarungsruf der weiblichen Yetis ähnelt, aber ich hab' da so meine Zweifel.\n\nBringt mir die besten Hörner der Frosthornböcke, die Ihr finden könnt, {name}, und ich werde mir eines davon aussuchen.", sourceObjective = "Nokoma Schneeseher im Lager der Winterhufe möchte, dass Ihr ihr 6 unbeschädigte Widderhörner bringt.", progress = "Habt Ihr brauchbare Hörner finden können?", completion = "All diese Hörner sind großartig, {name}. Lasst sie mich einmal näher betrachten, damit ich mir dasjenige aussuchen kann, welches ich auf der Jagd benutzen werde.\n\nDen Rest gebe ich dann den Handwerkern, damit sie daraus etwas schnitzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11276] = { id = 11276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und da waren es Zwei...", description = "Ihr untersucht Zedd, doch von der Glyphe fehlt jede Spur. Nachdem Ihr überall in der Gegend nachgesucht habt, entdeckt Ihr ein paar auf den Boden geschriebene Zeichen:\n\n\"Glor und Dae in den Katakomben. Haben Glyphe und Tafeln.\"\n\nVielleicht solltet Ihr Euch in die Katakomben im Norden begeben und nach Glorenfeld und Daegarn suchen. Die Brücke über die Worgengrube wird Euch direkt zum Tunnel und zum Eingang der Katakomben führen.", sourceObjective = "Sucht in den Katakomben von Utgarde nach Glorenfeld.", completion = "Wurde verdammt noch mal Zeit! Pulroy und Zedd sind tot.\n\nUnd Daegarn...\n\n<Glorenfeld schüttelt den Kopf.>\n\nEr wurde vom Anführer der Drachenschinder gefangen genommen und Tief ins Innere der Katakomben verschleppt. Ich konnte mitanhören, wie dieser zu groß geratene Bastard etwas über ein Opfer an den \"Schreckenskönig\" sagte.\n\nDaegarn hat die Glyphe in seinem fettigen Bart versteckt.\n\nWie bitte? Zwerge verstecken immer Dinge in ihrem Bart!", sourceObjectiveStatus = "unverified-source-field" }
quests[11277] = { id = 11277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefen des Anrüchigen", description = "Sie halten Daegarn in 'nem Käfig im großen Kampfring gleich hier in der Nähe gefangen. Soviel ich mitbekommen habe, lassen die Drachenschinder ihre Gefangen gegen ihre stärksten Gladiatoren kämpfen. Die Verlierer werden danach ins untere Geschoss geworfen, um dort von Nekromanten der Geißel in Ghule verwandelt zu werden! Grauenhaft ist das!\n\nAber eins nach dem anderen! Die Tafeln liegen überall im Kerker verstreut. Lasst uns die erstmal einsammeln, bevor Ihr versucht, den Helden zu spielen.", sourceObjective = "Glorenfeld in den Katakomben von Utgarde möchte, dass Ihr 10 Wyrmskoltafeln einsammelt.", progress = "Überprüft jede Nische und Ritze!", completion = "Gut gemacht, mein Freund. Da wir nun die Tafeln in Händen halten, können wir versuchen Daegarns Leben zu retten und die Glyphe zurückzubekommen, damit wir endlich das Geheimnis dieser uralten Relikte lüften können!\n\nIch behalte erst einmal die Tafeln und Ihr befreit Daegarn.", sourceObjectiveStatus = "unverified-source-field" }
quests[11278] = { id = 11278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Valgarde", description = "Was für 'ne Schande, dass wir zwei unserer besten Zwerge bei der Ausgrabung der Relikte verloren haben. Sie gaben ihr Leben hin, um diese Kunde sicher zu verwahren.\n\n<Glorenfeld wickelt die Glyphe und Tafeln in einen Lumpen Stoff ein.>\n\nBringt sie nach Valgarde zurück. McSorf wird wissen, was mit diesem Fund zu tun ist.\n\nWas mich angeht? Ich werde alleine schon zurechtkommen - bin schließlich in einem Stück bis hierhergekommen!", sourceObjective = "Bringt Glorenfelds Päckchen zu Beltrand McSorf im Hafen von Valgarde.", progress = "Ihr seid zurück!", completion = "Diese Tafeln zu sortieren, wird einige Zeit dauern. Alles, was ich bei einer ersten Untersuchung herausfinden konnte, ist, dass das, was auch immer einmal hier gewesen ist, ein Vorfahre der Menschen war. Diese Vrykuldinger haben sie wahrscheinlich bis auf den letzten umgebracht. Wie immer dem auch sei, wir werden mehr wissen, sobald ich diese Relikte geordnet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11279] = { id = 11279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Eier und Welpen", description = "Diese neue Seuche, an der wir gerade arbeiten, ist formidabel. Ich denke, wir sollten ihre Tests ausweiten.\n\nWie wäre es damit, sie an den Proto-Welpen auszuprobieren?!\n\nStellt Euch nur die Möglichkeiten vor. Wir könnten nicht nur Humanoide, sondern alle Kreaturen anstecken!\n\nHier, ich habe mir einen Seuchenkanister für den richtigen Zeitpunkt aufbewahrt - und Ihr scheint mir die richtige Person zu sein.\n\nBesprüht damit die Eier in der Glutstätte im Nordwesten und fangt anschließend ein paar Exemplare der ausgeschlüpften verseuchten Proto-Welpen ein.", sourceObjective = "Seuchenbringer Tillinghast möchte, dass Ihr 10 Exemplare verseuchter Protowelpen einsammelt und sie anschließend bei ihm abliefert. Er befindet sich in Neu-Agamand.", progress = "Wie soll ich ohne diese Proben herausfinden, ob dieser letzte Stamm unseres Erregers auf alle möglichen Kreaturen angewandt werden kann?", completion = "Was?! Nein, das kann nicht stimmen.\n\nVERDAMMT!\n\nDiese Version der Seuche scheint die Protowelpen bis auf den grünen Leuchteffekt nicht wirklich zu beeinflussen!\n\nMein Traum davon, alles, was wir berühren, mit der Seuche anzustecken, scheint sich in Luft aufgelöst zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11280] = { id = 11280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconis Gastritis", description = "Wartet, da kommt mir eine Idee! Was wäre, wenn die Welpen nur deswegen nicht gestorben sind, weil sie auf die Schale der Eier gesprüht wurde?\n\n{name}, wir müssen die Seuche irgendwie in sie hineinbekommen!\n\nIch weiß! Ich habe hier ein wenig verseuchtes Fleisch. Nehmt es, geht zur Glutstätte und bringt sie dazu, es zu fressen!\n\nHalt, wir denken hier nicht groß genug. Bringen wir einen der Protodrachen, die hoch am Himmel fliegen, dazu, herunterzukommen und es zu essen.\n\nGenau!\n\nBleibt in der Nähe des Fleischs und betrachtet das Geschehen. Ja, es könnte Euch angreifen - aber das ist nun mal der Preis des Fortschritts.", sourceObjective = "Seuchenbringer Tillinghast in Neu-Agamand möchte, dass Ihr mit Tillinghasts verseuchtem Fleisch einen Protodrachen anlockt und verfolgt, wie er auf das gefressene Zeug reagiert.", completion = "NEEEEIIIIIIIN!\n\n<Der Seuchenbringer fängt an zu weinen.>\n\nAlle meine Hoffnungen... alle meine Träume - zerstört!\n\nGeht, {name}. Geht und überlasst mich meinem Trübsal. Ich bin ein Nichts.\n\nHier, Ihr könnt ebenso gut all mein Hab und Gut an Euch nehmen. Wenn der Rest der Apotheker von meinem Versagen erfährt, dann bin ich sowieso erledigt und werde es nicht mehr brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11281] = { id = 11281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ruf der Natur nachahmen", description = "Die grobe Form des Horns ist nun fertig, doch bevor ich die traditionellen Muster in die Oberfläche kerbe, möchte ich sichergehen, dass es auch funktioniert. Ahota hat mir gesagt, dass er seine Hörner immer am Fuße des gefrorenen Wasserfalls nordöstlich des Lagers testet. Er hat mir auch gesagt, dass unsere Jäger die Akustik des gefrorenen Wassers schon seit Generationen zu diesem Zweck verwenden. Ich kann es kaum erwarten, noch mehr darüber zu erfahren!\n\nWerdet Ihr mir dabei helfen, das Horn zu testen? Wenn ich alles richtig gemacht habe, dann werdet Ihr sogar einen Yeti anlocken – also macht Euch darauf gefasst! Bringt das Horn zurück, sobald Ihr es getestet habt.", sourceObjective = "Testet das geschnitzte Horn und kehrt anschließend mit den Ergebnissen zu Nokoma Schneeseher im Lager der Winterhufe zurück.", completion = "<Nokoma hört sich Euren Bericht über den Test an.>\n\nDa bin ich erleichtert, dass das Horn so gut funktioniert hat... vielleicht etwas zu gut, wenn das, was Ihr sagt, stimmt. Seid Ihr Euch sicher, dass das Biest gesprochen hat? Wenn das wahr sein sollte, dann bin ich mir nicht sicher, ob ich mit auf die Jagd gehen kann. Ich werde mit Häuptling Aschtotem darüber sprechen müssen.\n\nKann sein, dass dieses Horn am Ende nur dekorativen Zwecken dienen wird - was seinen Wert jedoch nicht mindert. Vielen Dank für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11282] = { id = 11282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Angst", description = "Wenn du so viele Kämpfe gemacht hast wie Gorth, dann weißt du, dass man den Bösewichten sehr viel Angst machen muss, wenn man sie gut verhauen will!\n\nDiese Vrykul aber keine Angst. Du machst einen nieder, aber sofort kommt ein anderer... und der brüllt dann lauter und hat eine größere Waffe als der davor.\n\nDas Einzige, wovor Vrykul Angst haben, ist, wenn wir den größten und bösesten Vrykul von allen töten.\n\nGeh und murks so lange Winterskorn auf der anderen Seite der Blockade, bis Vrykulhelden auftauchen! Du machst sie dann alle tot und bohrst Flagge der Königin in sie hinein. Die müssen lernen, Angst zu haben!", sourceObjective = "Gorth möchte, dass Ihr Ulf den Aderlasser, Oric den Elenden und Gunnar Thorvardsson tötet und das Banner der Verlassenen durch ihre Körper rammt. Erschlagt solange Vrykul auf der anderen Seite der Blockade der Verlassenen, bis die Drei auftauchen.", completion = "Du hast dort drüben ein paar gute Murkser gemacht. Ich habe gesehen, wie Vrykul fallen und mit Sylvanas Flagge gestochen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11283] = { id = 11283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahl der Toten in Quälheim", description = "Vrykul kommen aus dem Ort da im Westen - hört gar nicht mehr auf und kein Ende in Sicht!\n\nGorth hat da eine Idee. Du gehst HINEIN in die Stadt und murkst Winterskorn. DANN werden sie nicht mehr rüberkommen!", sourceObjective = "Unteroffizier Gorth möchte, dass Ihr nach Quälheim geht und 16 Vrykul des Winterskornstammes tötet.", completion = "Du musst viel Übung im Murksen haben. Du bist fast so gut wie Gorth!", sourceObjectiveStatus = "unverified-source-field" }
quests[11284] = { id = 11284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Yeti von nebenan", description = "Wenn die Schildwachen mir schon nicht helfen können, würdet Ihr? Ich bin der Vorarbeiter der Mine hinter der Brücke dort. Meine Männer schürfen Erz für die Waffen, die unsere Expeditionstruppe brauchen wird, um einen Pfad durch die Grizzlyhügel zu schlagen.\n\nEin riesiger Yeti ist in die Mine eingedrungen und blockiert den Tunnel, den wir brauchen, um weiter zu arbeiten! Wir haben versucht, ihn durch Schreie zu verscheuchen und aus seinem Unterschlupf zu vertreiben, aber nichts hat geholfen.\n\nVielleicht könntet Ihr ihn wecken, mit einer Portion Fleisch von den Frosthornböcken aus den schneebedeckten Gegenden um die Stadt herum? Bitte... Wir sind verzweifelt!", sourceObjective = "Vorarbeiter Colbey bei Fort Wildervar möchte, dass Ihr Schmetterhorn besiegt.", completion = "Ihr habt es geschafft? Beim Licht, Ihr seid ein wandelndes Wunder! Ich hatte mich schon mit dem Gedanken abgefunden, Hauptmann Adams persönlich erklären zu müssen, warum die Waffen seiner Männer nicht rechtzeitig fertig geworden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11285] = { id = 11285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quälheim muss brennen!", description = "Die Winterskorn töten vielleicht nicht genug. Vielleicht verbrennen wir einfach auch ihre Häuser! Eh... und ihre Brücken. Wir sollten sichergehen und die ganze Stadt mit Feuer kaputt machen!\n\nDu nimmst diese Fackel. Geh nach Quälheim, im Westen, und verbrenn ALLES! Wird ihnen eine Lehre sein.", sourceObjective = "Unteroffizier Gorth will, dass Ihr nach Quälheim geht und Gorths Fackel benutzt, um 1 Behausung der Winterskorn, 1 Wachturm der Winterskorn, 1 Brücke der Winterskorn und 1 Kaserne der Winterskorn in Brand zu stecken.", completion = "Ich schätze, du hast alles mit Feuer kaputt gemacht. Ich seh' ein paar Stellen, die nicht brennen... aber für Gorth ist das nah genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[11286] = { id = 11286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Artefakte des Stählernen Tores", description = "Ich bin aus einem anderen Grund hier in dieser Gegend - ein alter Freund hat mich in meinen Träumen gerufen. Es bringt jedoch mein Blut zum Kochen, mit ansehen zu müssen, wie diese kleinen Dinger mit ihren Maschinen ein großes Loch in den Boden graben.\n\nSo wie ich das sehe, graben diese sogenannten Zwerge Artefakte aus - Artefakte, die wichtige Zeugnisse unserer Vergangenheit sein könnten.\n\nIch möchte, dass Ihr dort hinunter geht und diese Dinger zu mir bringt. Lasst Euch von keinem dieser Zwerge aufhalten.", sourceObjective = "Weiser Nebelläufer möchte, dass Ihr 10 Artefakte vom Stählernen Tor aufsammelt. Kehrt zu ihm zurück, sobald Ihr alle habt. Er befindet sich am Stählernen Tor.", progress = "Wie viele Artefakte habt Ihr an diesem Stählernen Tor finden und aufsammeln können?", completion = "<Der Weise knurrt als Zeichen seiner Anerkennung für das, was Ihr auf sein Geheiß unternommen habt.>\n\nVielleicht werde ich mir schon bald die Zeit nehmen können, um diese Artefakte zu untersuchen und herauszufinden, welche Bedeutung sie für uns haben.\n\nEs gibt jedoch wichtigere Angelegenheiten, um die wir uns jetzt kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11287] = { id = 11287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Weisen Nebelläufer", description = "<Verehrter/Verehrte:c> {class}, ich mache mir zunehmend Sorgen um meinen Sohn Weiser Nebelläufer - er ist nun schon so lange fort. Das Land ist grausam und tödlich.\n\nEr sprach von einer immer wiederkehrenden Vision und brach dann mit einer kleinen Gruppe Fernläufer in Richtung Westen auf, um ihrem Ursprung nachzugehen. Er erwähnte einen Namen - 'Stählernes Tor', glaube ich, war es.\n\nWerdet Ihr nach ihm suchen? Ich möchte sichergehen, dass ihm auch nichts Schlimmes zugestoßen ist.", sourceObjective = "Großmutter Ankha hat Euch gebeten nachzusehen, in welcher Verfassung sich der Weise Nebelläufer befindet. Sie glaubt, dass er sich am oder in der Nähe des Stählernen Tores befindet.", completion = "Meine Mutter soll sich keine Gedanken um meine Sicherheit machen. Ich danke Euch jedoch dafür, dass Ihr gekommen seid, Fremder.\n\nDa Ihr nun schon einmal da seid - könntet Ihr mir vielleicht bei ein paar Angelegenheiten helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11288] = { id = 11288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das strahlende Licht", description = "<Ares liegt im Sterben. Er versucht zu sprechen und keucht.>\n\nIch bin ein Abgesandter des Argentumkreuzzugs und wurde mit einer heiligen Aufgabe beauftragt.\n\nUnsere Streitkräfte in den Pestländern wurden dezimiert. Mit dem Licht der Morgendämmerung, läuterten sie das Artefakt, machten es wieder rein. Die Erlösung... so viele gaben ihr Leben für sie.\n\nDoch es gibt immer noch Hoffnung... noch ist Zeit.\n\nDas Artefakt wurde in die Grube der Gefallenen geschleudert - tief unter uns, von den grausamen Toten bewacht.\n\n<Ares' Körper erglüht in einem blendenden Licht.>\n\nDas - Licht - wird - Euch - beschützen.", sourceObjective = "Ares der Schwurgebundene in den Katakomben von Utgarde möchte, dass Ihr das geheiligte Artefakt bergt.\n\nDiese Aufgabe ist zeitlich begrenzt.", progress = "<Ares ist bewusstlos.>", completion = "Ihr fühlt Euch dazu verpflichtet, das heilige Schwert neben Ares zu legen.\n\nNachdem Ihr dies getan habt, werdet Ihr noch einmal vom Licht geblendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11289] = { id = 11289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Ehre geleitet", description = "<Ares lächelt.>\n\nEhre dem Licht. Ihr habt es geschafft!\n\n<Ares hustet.>\n\nNehmt das Artefakt und bringt es nach Valgarde zurück. Lord Irulon Wahrklinge erwartet dessen Rückkehr.\n\nKämpft mit Ehre. Immer - Ehre.\n\n<Ares stirbt.>", sourceObjective = "Bringt das geheiligte Artefakt zu Lord Irulon Wahrklinge zurück. Er befindet sich in Valgarde.", progress = "Beim Licht!", completion = "Viele Männer und Frauen mussten ihr Leben lassen, um dieses Schwert zu bergen. Ach, ich fürchte, dass der tapfere Ares nicht der Letzte sein wird.\n\nDoch aus Euren Taten spricht das Licht. Dieses heilige Schwert wird Lord Tirion Fordring höchstpersönlich tragen. Selbst jetzt arbeitet sich der Argentumkreuzzug zur Eiskrone vor. Lord Fordring hat geschworen, dass er die Mauern dieser verfluchten Stätte mit seinen eigenen Händen niederreißen wird! Und mit dem Schwert könnte er sich sogar gegen den Lichkönig behaupten.\n\nLord Fordring bleibt unsere größte Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11290] = { id = 11290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtpläne der Drachenschinder", description = "Wir konnten zwar nur sehr wenig über Ingvars Aufenthaltsort erfahren, doch was wir wissen, ist, dass Yanis in einer Höhle in der Nähe der Worggrube in Wyrmskol wohnt.\n\nInformationen, die wir von den geretteten Soldaten erhalten haben, deuten darauf hin, dass Yanis die Schlachtpläne der Drachenschinder bewacht.\n\nIch möchte, dass Ihr zurück nach Wyrmskol geht und diese Schlachtpläne beschafft.", sourceObjective = "Vizeadmiral Keller im Hafen von Valgarde im Heulenden Fjord möchte, dass Ihr ihm die Schlachtpläne der Drachenschinder bringt.", progress = "Habt Ihr die Schlachtpläne der Drachenschinder bei Euch?", completion = "<Vizeadmiral Keller überfliegt kurz die Pläne.>\n\nHervorragend! So wie es aussieht, gibt es noch viel mehr Vrykuldörfer im Fjord. Ein anderer Vrykulstamm bereitet sich auf einen Angriff auf Westwacht vor. Verdammt! Soweit ich es beurteilen kann, ist es vielleicht schon zu spät. Wir haben seit Tagen keine Nachricht mehr aus Westwacht erhalten. So oder so - wir müssen Westwacht warnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11291] = { id = 11291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Westwacht!", description = "<Vizeadmiral Keller rollt die Schlachtpläne aus.>\n\nWir wissen nun genug, um Valgarde weiterhin zu schützen. Ihr müsst diese Schlachtpläne nach Westwacht bringen. Westwacht befindet sich oben auf den Klippen im Westen des Fjords. Sprecht mit der Flugmeisterassistentin Emilune Winterwind. Sie wird Euch auf einen Greifen in Richtung Westwacht setzen.\n\nFindet Hauptmann Adams, sobald Ihr angekommen seid. Er hat dort das Sagen. Adams wird wissen, was mit diesen Plänen anzufangen ist.", sourceObjective = "Bringt die Schlachtpläne der Drachenschinder zu Hauptmann Adams. Er befindet sich in Westwacht im Heulenden Fjord.", progress = "Valgarde wurde nicht vernichtet? Welch Überraschung.\n\nMuss an unserer Hilfe gelegen haben. Keller hat damit sicherlich nichts zu tun.", completion = "<Hauptmann Adams nimmt Euch die Pläne ab.>\n\nIch freue mich, dass Ihr Euch dazu entschlossen habt, hierher zu kommen. Meine Berater und ich werden diese Pläne eine Zeitlang untersuchen. In der Zwischenzeit können wir jede Hilfe gebrauchen, die wir kriegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11292] = { id = 11292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Schwachen Jagd machen", description = "Es freut mich, Euch kennenzulernen. Ich komme von den Grizzlyhügeln, um mit Euresgleichen Geschäfte zu machen. Mein Volk unterhält dort einen großen Außenposten. Ihr wärt gut damit beraten, ihn zu besuchen, falls Ihr nach Norden ziehen solltet.\n\nIch habe in den Wäldern und Schneegebieten in der Gegend Fallen aufgestellt. Mit dem Fleisch und Fell der Kreaturen, die in die Falle gehen, werde ich genug haben, um mit dem Stadtvolk Handel betreiben zu können.\n\nSolltet Ihr gewillt sein, mir dabei zu helfen die gefangene Beute zu sammeln, könnte ich Euch einen Teil meines Gewinns anbieten. Seid jedoch gewarnt: Dort draußen seid Ihr nicht das einzige Raubtier.", sourceObjective = "Fallensteller Jethan in Fort Wildervar möchte, dass Ihr ihm aus 8 Fallen gefangene Beute bringt.", progress = "Ich hoffe, Ihr seid nicht mit leeren Händen zurückgekommen. Ich dachte, wir hätten ein Abkommen.", completion = "<Fallensteller Jethan begutachtet die Kreaturen, die Ihr ihm gebracht habt.>\n\nGut gemacht. Einige davon werden einen besseren Preis erzielen als andere - aber ich sollte genug haben, um mit den Ansässigen handeln zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Gerstenbräus!", description = "Lasst alle wissen, dass die Gerstenbräus auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält! Ich werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder für 4 Minuten borge. Verwendet die Zügel, um ihn anzutreiben, aber achtet drauf, ihn nicht zu sehr zu erschöpfen.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", completion = "Gut gemacht! Die Ankündigung wird unser Geschäft bestimmt ins Rollen bringen.\n\nWir hatten Euch ja auch eine Belohnung versprochen, hier ist sie. Die Gerstenbräus halten ihr Wort.\n\nOh, wenn Ihr die gute Kunde von den Gerstenbräus noch einmal verbreiten wollt, könnt Ihr gerne an einem anderen Tag wieder kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Donnerbräus!", description = "Wir müssen die Leute wissen lassen, dass die Donnerbräus ihre Bitte nach gutem Gebräu erhört haben. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält!\n\nWir werden Euch das Ganze etwas erleichtern, indem wir Euch einen Rennwidder 4 Minuten lang borgen.\n\nAchtet darauf, nicht zu schnell zu reiten, denn Ihr werdet keine Apfelkisten in Eisenschmiede finden und wir können es nicht riskieren, den Marktschreiern der Gerstenbräus behilflich zu sein.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", completion = "Gute Arbeit! Das wird es diesen arroganten Gerstenbräus aber zeigen.\n\nNa dann, wir haben Euch eine Belohnung versprochen und hier ist sie. Wir Donnerbräus belohnen Euch mit Preisen, die Gerstenbräus belohnen Euch mit faulen Sprüchen und falschen Versprechen.\n\nIhr habt Euch weise entschieden.\n\nWenn Ihr auch weiterhin den richtigen Weg einschlagen wollt, dann kommt an einem anderen Tag noch einmal vorbei und verbreitet die Kunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11295] = { id = 11295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Offensive beginnt", description = "Niemand scheint sehr viel über die Vrykul zu wissen. Unsere Aufzeichnungen deuten darauf hin, dass sich seit Jahrhunderten nichts mehr in ihren Landen geregt hat. Dennoch sind sie ausgerechnet jetzt, wo wir gegen Arthas ins Feld ziehen, hier.\n\nDie Karte, die Ihr geborgen habt, verdeutlicht, dass wir sie besiegen müssen, wenn wir unsere Truppen tiefer ins Landesinnere von Nordend bewegen wollen.\n\nEiner meiner besten Unteroffiziere, eine Monstrosität namens Gorth, wacht über die Blockade in der Nähe des Aufzugs. Unterstützt ihn dabei, einen Präventivschlag gegen Quälheim vorzunehmen. Wenn die Vrykul einen Angriff starten, dann wird er von dort aus geführt.", sourceObjective = "Sprecht mit Unteroffizier Gorth bei der Blockade in der Nähe des Aufzugs westlich vom Hafen der Vergeltung im Heulenden Fjord.", completion = "Du kommst, um zu helfen? Gut... gut...\n\nGorth wurde schon müde vom ständigen Vrykulmurksen. Hilfe ist gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[11296] = { id = 11296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangen im Bruchwald", description = "Irgendetwas - höchstwahrscheinlich waren es die wandelnden Toten der Geißel - hat die Kreaturen in dieser Gegend in Unruhe versetzt.\n\nAls wir den Weisen hierher eskortierten, verloren wir den Großteil unseres Jagdtrupps an die Bruchwitwen, die im Norden des Bruchwaldes vorkommen.\n\nIch muss hier bleiben und die wenigen, die von uns übrig geblieben sind, beschützen - doch Ihr... Ihr könntet nachsehen, ob meine Fernläufer noch immer am Leben sind. Sie sind in Bruchwitwenkokons eingeschlossen.\n\nWürdet Ihr das tun, <Fremder/Fremde>?", sourceObjective = "Fernläufer Himmelswolke möchte, dass Ihr 7 seiner Fernläufer der Winterhufe befreit. Meldet Euch wieder bei ihm, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich am Stählernen Tor.", completion = "Das war eine sehr mutige Tat, {class}. Ich wusste nicht, dass jemand Eures Volkes zu solch einem selbstlosen Akt fähig ist.\n\nDas nächste Mal werde ich die Warnungen meiner Ältesten beherzigen und einen großen Bogen um den Bruchwald machen. Ich rate Euch, dasselbe zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11297] = { id = 11297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Eindringlingen Ausschau halten", description = "Selbst die Erde kann die Flut des Todes nicht eindämmen, die über sie hinwegschwappt. Leichen wandeln umher und verbreiten Fäulnis mit alarmierender Geschwindigkeit.\n\nEine kleine Expedition hat sich auf den Weg die westlichen Klippen hoch gemacht und in der Nähe der Flüsterschlucht ihr Lager aufgeschlagen. Doch seht für Euch selbst, {name}. Versucht herauszufinden, aus welchem Grund sie dort sind, und haltet sie davon ab, ihre Gifte in unser Land zu bringen. Reist vom Posten aus gen Südwesten in Richtung der Klippen, die den westlichen Strand säumen. Ihr Lager wird sich westlich des Ausgrabungsortes am Stählernen Tor befinden.", sourceObjective = "Sprecht mit Apotheker Malthus im Apothekerlager.", completion = "Ah, ja, das zurückgezogene Bisonvolk des Nordens. Ich habe gesehen, wie sie herumschleichen - im Glauben, man würde sie nicht sehen. Ich nehme einmal an sie bilden sich ein, dass dieses Land ihnen gehört? Nun, das ist nur eine der vielen Veränderungen, die sich in Kürze ergeben werden.\n\nIch habe zwar nicht damit gerechnet, Gesellschaft zu bekommen, aber wenn Ihr schon einmal im Auftrag des Narren hier seid, könnt Ihr Euch genauso gut nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11298] = { id = 11298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist in dem Gebräu?", description = "Im Südosten gibt es einen Landstrich namens Flüsterschlucht. In ihr wimmelt es nur so von verrückt gewordenen Forscherligisten! Sie griffen unsere Karawane an, als wir durch diese Gegend zogen, und außerdem attackieren sie ununterbrochen unsere Jagdtrupps.\n\nIch muss wissen, was der Grund dieses Wahnsinns ist! Ich vermute einmal, dass was auch immer sie aus diesen Fässchen, die überall in der Schlucht verstreut herumliegen, trinken, zu ihrem Wahnsinn beiträgt. Ich möchte, dass Ihr die Fässchen dieser Zwerge stehlt, während sie mit Schürfen beschäftigt sind.", sourceObjective = "Apotheker Malthus im Apothekerlager möchte, dass Ihr ihm 5 zwergische Fässchen bringt.", progress = "Habt Ihr nun die Fässchen bei Euch oder nicht?", completion = "<Der Apotheker schenkt sich einen Krug voll des Gebräus ein.>\n\nTja, zum Wohl!", sourceObjectiveStatus = "unverified-source-field" }
quests[11299] = { id = 11299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Richturteils", description = "Ihr habt vielleicht schon den Raum, in dem Daegarn gefangen gehalten wird, gesehen, als Ihr dabei wart, die Tafeln zu sammeln. Er befindet sich am Ende dieses Korridors und dann ein paar Stufen hinunter. Daegarn befindet sich in dem Raum am Ende dieser Treppen - fest hinter Gittern verschlossen!\n\nBegebt Euch dorthin und findet ihn. Vielleicht könnt Ihr wenigstens die Glyphe von ihm bekommen.", sourceObjective = "Findet Daegarn. Sucht im Ring des Richturteils im Inneren der Katakomben von Utgarde.", completion = "Jep - Ihr habt mich gefunden. Jippi-jei!\n\nUnd nein, ich hab' die Glyphe nicht. Mein Bart war das Erste, was diese Biester durchsucht haben! Oluf hat sie jetzt - er ist der Häuptling der Gladiatoren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11300] = { id = 11300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigende Niederlage im Ring", description = "Oluf wird erst dann rauskommen, wenn Ihr die anderen Gladiatoren besiegt habt. Das ist so gut wie unsere einzige Möglichkeit, an diese Glyphe heranzukommen. Schnappt Euch Eure beste Klopp-Ausrüstung und dann ab mit Euch in den Ring des Richturteils und los geht's. Geht zu Glorenfeld drüben am Eingang zu den Katakomben und gebt ihm die Glyphe, falls Ihr sie zurückbekommen könnt.\n\nIch? Macht Euch um mich keine Sorgen! Wir sind kurz davor, das fehlende Bindeglied zu entdecken, das die Herkunft der Menschheit klären wird.", sourceObjective = "Besiegt die Gladiatoren im Ring des Richturteils und stellt Euch Oluf dem Gewalttätigen. Besiegt Oluf und nehmt ihm die uralte Glyphe ab.\n\nBringt die uralte Glyphe zu Glorenfeld am Eingang zu den Katakomben von Utgarde.", progress = "Daegarn? Die Glyphe?", completion = "Faszinierende Geschichte! Da gibt es tatsächlich etwas, das über die Dinger richtet? Wozu?! Zu welchem Zweck?\n\nNun, vergesst diesen Unsinn. Das soll irgendwer anderes herausfinden. Wir haben Glyphe und Tafeln wieder - und die ganze Tortur hat nur zwei Todesopfer gefordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11301] = { id = 11301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehirne! Wir wollen Gehirne!", description = "Hat Euch Malthus mit seiner Faselei über Bierkrüge und verrückte Zwerge schon in seinen Bann gezogen?\n\nIch will ja nicht in Frage stellen, dass Zwerge verrückt sind, aber ich denke, dass es zu nichts führt, ihr Bier zu stehlen.\n\nWas wir brauchen ist Köpfchen - beziehungsweise etwas aus dem Köpfchen. Und zwar viel davon. Wir werden diesem Rätsel im Nu auf den Grund gehen und vielleicht sogar eine neue Zutat für unsere Seuche finden.\n\nNehmt diese Säge, geht nach Südosten zum Flüsterschlund und tötet ein paar Zwerge. Mithilfe der Säge könnt Ihr die Gehirne sammeln. Bringt sie dann hierher.", sourceObjective = "Apotheker Grick im Apothekerlager möchte, dass Ihr ihm 12 verwirrte Forscherhirne bringt.", progress = "Konntet Ihr die Gehirne bekommen? Falls nicht, dann will ich meine Säge zurückhaben. Und versucht bloß nicht, mit der Säge abzuhauen.", completion = "Oh, diese Gehirne sind schön! Sogar wunderschön! Genau das, was ich brauche.\n\nDanke für Eure Hilfe, {name}. Nun werde ich Malthus mal die Wahrheit zeigen, die er durch seine rosarote Brille nicht sehen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11302] = { id = 11302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheimnisvollen Frostnymphen", description = "Als wir das erste Mal nach geeigneten Stellen für das Fort suchten, begegneten wir auf zwei der Lichtungen hier im Norden feindlich gesinnten Kreaturen. Doch als wir über die schneebedeckte Lichtung, die direkt südlich der Stadt liegt, liefen, wurden wir von den dortigen Dryaden nur mit Interesse beäugt, jedoch nicht angegriffen.\n\nWir waren müde und vom Wetter mitgenommen. Sie hätten mit Leichtigkeit mehrere von unseren Männern töten können, taten es jedoch nicht.\n\nVielleicht könnten sie ganz unerwartet zu unseren Verbündeten werden, wenn wir uns ihnen nur nähern würden. Seid Ihr dazu bereit, zur Gefrorenen Lichtung zu reisen und mit ihnen Kontakt aufzunehmen?", sourceObjective = "Sprecht mit Lurielle auf der Gefrorenen Lichtung.", completion = "<Ihr stellt Euch vor und Lurielle lauscht Euren Worten.>\n\nWie gut, Euch endlich kennenzulernen, {name}. Wir haben lange darauf gehofft, dass Ihr und die anderen Neuankömmlinge Repräsentanten schicken würdet. Wir wagen uns nicht sehr oft aus unseren Lichtungen heraus, zumal dieses Land derzeit einige Veränderungen erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11303] = { id = 11303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hinterhalt", description = "Die Vrykul in Quälheim sind endgültig platt gemacht, daran ich keinen Zweifel. Doch ihr Anführer noch immer in der Stadt und will nicht aufgeben.\n\nGorth schickt Lydell und seine Helfer, um guten Hinterhalt im Nordwesten zu machen. Du redest mit Lydell und findest heraus, wie man Vrykulhäuptling herauslockt. Dann tötest du ihn - machst ihn richtig platt.", sourceObjective = "Geht zu Lydells Hinterhalt und sprecht mit Lydell.", completion = "Wir sind alle dabei gewesen, nur der Ehrengast blieb Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[11304] = { id = 11304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu-Agamand", description = "Ich befürchte, dass die Ausrüstung hier im Hafen der Vergeltung nicht wirklich die beste ist. Dabei soll das hier ein militärischer Außenposten sein.\n\nIhr müsst eine Probe dieses Erregerstammes für mich zum obersten Seuchenfürsten Harris in Neu-Agamand bringen - folgt der Straße außerhalb von Quälheim nach Süden und dann nach Westen. Dort haben sie bessere Ausrüstung - er wird wissen, was zu tun ist.\n\nIhr müsst Euch beeilen, {name}. Unsere Feinde sind stärker und zahlreicher als wir. Wir müssen eine wirksame Waffe gegen sie entwickeln!", sourceObjective = "Bringt Lysanders Erregerstamm zum obersten Seuchenfürsten Harris. Er befindet sich in Neu-Agamand im Westen des Heulenden Fjords", progress = "Ja, {name}?", completion = "Dieser Erregerstamm ist alles andere als nutzlos, mein Freund! Die Narren im Hafen der Vergeltung! Die Antworten lagen die ganze Zeit direkt vor ihrer Nase!", sourceObjectiveStatus = "unverified-source-field" }
quests[11305] = { id = 11305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine maßgeschneiderte Formel", description = "Wir haben das Vrykuldorf Halgrind nun schon seit Wochen mit dem Zeugs besprüht, aber die Dreckskerle wollen einfach nicht tot umfallen.\n\nSeien wir doch mal ehrlich, {name}, inzwischen wurde fast alles unserer Seuche ausgesetzt: Menschen, Zwerge, Hunde, selbst das Vieh... Während unsere Erregerstämme sich an ihren Wirt anpassen, wird die Mischung noch weiter verunreinigt. Was wir brauchen, ist ein Erreger, der speziell an die Körper der Vrykul angepasst ist.\n\nDer Anführer Halgrinds flüchtete aus der Stadt, nachdem wir sie einnahmen - er befindet sich westlich von hier. Der Fakt, dass er ein Patriarch des Drachenschinderklans ist, macht sein Blut ideal für unsere Zwecke.", sourceObjective = "Geht zu Thorvalds Lager, erschlagt Thorvald, nehmt das Blut des Patriarchen der Drachenschinder an Euch und bringt es zum obersten Seuchenfürsten Harris in Neu-Agamand.", progress = "Konntet Ihr die nötige Probe beschaffen, {name}?", completion = "Das wird reichen. Zeit für ein wenig echte Apothekerarbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11306] = { id = 11306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufkochen und umrühren", description = "Ihr habt bis jetzt gute Arbeit geleistet, {name}. Ich würde Euch gerne ein paar meiner Techniken zeigen - sie sind weiter fortgeschritten und werden Euch ein besseres Verständnis von der Seuche vermitteln.\n\nNehmt diese leere Flasche und füllt sie mit dem Blut aus dem Kessel zu meiner Linken. Nehmt dann die Seuchenproben zu meiner Rechten und gebt so viel zum Blut hinzu, bis Ihr eine ausgewogene Mischung erhaltet.", sourceObjective = "Füllt die leere Apothekerflasche im Kessel mit Vrykulblut auf und vermischt ihren Inhalt so lange mit Harris' Seuchenproben, die sich in der Nähe befinden, bis Ihr eine ausgewogene Mixtur erhaltet.\n\nSprecht wieder mit dem obersten Seuchenfürsten Harris, sobald Ihr die Aufgabe erledigt habt.", progress = "Wie geht es Eurem Experiment, {name}? Lasst es mich wissen, falls Ihr Fragen bezüglich des wissenschaftlichen Aspekts hinter dem Ganzen haben solltet!", completion = "Ausgezeichnet! Ihr seid ein begabter Schüler, {name}.\n\nNun zum spaßigen Teil: die Anwendung!", sourceObjectiveStatus = "unverified-source-field" }
quests[11307] = { id = 11307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldversuch", description = "Da wir nun über einen an vrykulsche Wirte angepassten Seuchenerreger verfügen, müssten wir ihn eigentlich an unseren Exemplaren in Halgrind austesten. Wenn alles nach Plan verläuft, sollten sie augenblicklich zerfallen, da die Seuche ihre Eingeweide zersetzt!\n\nHalgrind befindet sich nördlich von hier. Unsere Seuchenbringer verbreiten dort gerade den alten Erreger - sollte nicht zu übersehen sein.", sourceObjective = "Geht nach Halgrind und wendet das Seuchenspray auf 10 Verseuchte Vrykul der Drachenschinder an. Kehrt anschließend zum obersten Seuchenfürsten Harris zurück und erstattet ihm über die Ergebnisse Bericht.", completion = "Die Seuche ließ unsere Subjekte nicht zerfallen? Seid Ihr Euch sicher, {name}??!\n\nEs muss einen externen Faktor geben, den wir nicht berücksichtigen... vielleicht ist es die niedrige Temperatur, die in diesem Klima herrscht? Vielleicht... eine Mutation unseres Erregers!", sourceObjectiveStatus = "unverified-source-field" }
quests[11308] = { id = 11308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit aufzuräumen", description = "Da ich nun einmal ein praktisch veranlagter Mann bin, erkläre ich hiermit unsere Forschung an diesem Ort für erfolgreich. Schließlich lässt sich noch jede Armee aufhalten, wenn man nur unter ihren eigenen Reihen Zwietracht sät?\n\nIch werde dafür sorgen, dass man im Hafen der Vergeltung bald genug Nachrichten unserer Errungenschaften erhalten wird. Aber zuerst müsst Ihr Euch um die Säuberung unserer Teststätte kümmern.\n\nFragt \"Eisensäge\" Jenny, ob sie eine Monstrosität nach Euren Wünschen anfertigen kann - eine mit explosionsartiger Kraft, wenn Ihr versteht, was ich meine.", sourceObjective = "Sprecht mit \"Eisensäge\" Jenny in Neu-Agamand.", completion = "Was wollt Ihr? Könnt Ihr nicht sehen, dass ich gerade beschäftigt bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[11309] = { id = 11309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Teile", description = "So, Harris will also, dass der Ort demoliert wird, hä? Ja, ich kann aushelfen.\n\nIhr werdet mir jedoch ein paar Teile besorgen müssen. Ich kann es mir nicht leisten, meine kostbarsten Komponenten für etwas zu verwenden, das in die Luft gejagt werden soll.\n\nAls Allererstes brauche ich Schaufelhauerbänder... viel besser als die der Menschen.\n\nAußerdem brauche ich noch ein Pfund Fleisch. Ein Kerl namens Anton verkauft billiges Fleisch. Er ist entlang der Straße gen Westen anzutreffen.", sourceObjective = "\"Eisensäge\" Jenny in Neu-Agamand möchte, dass Ihr 6 Schaufelhauerbänder und 1 Pfund frisches Fleisch besorgt.", progress = "Habt Ihr die Komponenten schon?", completion = "Ausgezeichnet! Ja, ja, das wird völlig ausreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11310] = { id = 11310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung: Ein wenig Montage benötigt", description = "Nun gut, hier, bitte schön! Unser Freund wird etwas... instabil sein - also schlage ich vor, dass Ihr ihn erst zusammenbaut, wenn Ihr in Halgrind seid.\n\nTreibt, wenn Ihr dort seid, mithilfe der Monstrosität so viele Vrykul wie nur möglich zusammen, bevor die Selbstzerstörung ausgelöst wird.\n\nKommt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt mir, was auch immer übrig geblieben ist. Körperteile kann ich immer gut gebrauchen!", sourceObjective = "Benutzt den Monstrositätenbausatz in Halgrind und tötet mithilfe der hirnlosen Monstrosität 20 verseuchte Vrykul. Kehrt nach Neu-Agamand zu \"Eisensäge\" Jenny zurück, sobald Ihr fertig seid.", completion = "Großartige Arbeit, {name}. Ihr würdet nicht zufällig nach etwas... langfristigem suchen, oder? In dieser Gegend gibt es viel zu tun, ich könnte definitiv Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11311] = { id = 11311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elemente bekämpfen", description = "Wenn Ihr hier überleben wollt, so wie wir es bisher getan haben, müsst Ihr den Herausforderungen der Natur direkt ins Auge blicken. In Anbetracht der starken Zunahme der Elementare in dieser Gegend würde Unachtsamkeit gegenüber den Elementen Euer Leben fordern.\n\nWir müssen die Zahl der Elementare ein letztes Mal reduzieren, bevor wir diesen Ort verlassen können. Seid Ihr willens, uns zu helfen, während wir uns um die Vorbereitungen kümmern?\n\nIhr müsst sämtliche Eissplitterelementare oder heulende Zyklone töten, die Euch in den verschneiten Hügeln rings um den Außenposten herum begegnen.", sourceObjective = "Windzähmer Kagan im Lager der Winterhufe möchte, dass Ihr 8 Bergelementare tötet. Zu töten sind entweder heulende Zyklone oder Eissplitterelementare.", completion = "Der Einfluss der Elementargeister ist geschwunden, doch sie werden ihn wiedererlangen. Wir haben uns die nötige Zeit verschafft, um unsere Aufgabe hier zu Ende zu bringen und Abschied zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11312] = { id = 11312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefrorene Lichtung", description = "Seit Generationen erzählt mein Volk sich Geschichten über Frostnymphen, die sich auf verborgenen Lichtungen in der Wildnis tummeln. Als Kind war ich entgegen des Rates meiner Eltern auf der Suche nach ihnen und wäre zum Schluss beinahe erfroren.\n\nHeutzutage muss man jedoch nicht mehr die Wälder durchkämmen, um sie zu finden. Sie haben sich aus mir unerklärlichen Gründen dazu entschlossen, ans Licht zu treten, und ich denke nicht, dass diese Veränderung ignoriert werden kann. Begebt Euch auf die riskante Reise zur Gefrorenen Lichtung gen Südosten und sucht nach den Nymphen - doch seid gewarnt: Euer Weg führt Euch durch die Siechende Lichtung.", sourceObjective = "Sprecht mit Lurielle in der Gefrorenen Lichtung.", completion = "<Ihr stellt Euch vor und Lurielle lauscht Euren Worten.>\n\nWie gut, Euch kennenzulernen, {class}. Meine Schwestern haben oft beobachtet, wie die Taunka in den Wäldern nach uns suchen, doch unsere Königin hat uns jeglichen Kontakt mit Fremdlingen verboten. Ihr könnt uns nur sehen, weil das Land in Aufruhr ist und viele meiner Schwestern in Gefahr sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11313] = { id = 11313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister des Eises", description = "Einst waren die Eiselementare, die unsere Lichtung umgeben, unsere Gefährten, doch dann wurde das Land von einem Sturm unberechenbarer, zerstörerischer Macht erfasst, der sie zu unseren Feinden machte!\n\nUnd dieses Gräuel ist nur eines von vielen, die meine Schwestern und ich bis jetzt ertragen mussten. Wir haben uns Euch gezeigt und hoffen nun, dass Ihr den Verfall, von dem unsere Lichtungen beschlichen und unsere Schwestern vergiftet wurden, abwenden könnt!\n\nWir haben die Kerne der Eiselementare gesammelt und sicher verwahrt, damit wir sie eines Tages vielleicht wieder zurückrufen können. Werdet Ihr helfen?", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr ihr 15 eisige Kerne bringt.", progress = "Habt Ihr die Kerne gefunden?", completion = "<Lurielle nimmt schweigend die Kerne entgegen.>\n\nIch danke Euch, {name}.\n\n\n\nIch verspreche, meine Freunde, dass ich alles in meiner Macht Stehende tun werde, um Euch zurückzurufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11314] = { id = 11314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefallenen Schwestern", description = "Gen Südwesten befand sich einst eine Lichtung, die dieser hier sehr ähnlich sah. Geheimnisvolle Kräfte und fremde Magie formen das Land neu. Das Eis der Lichtung ist aufgetaut und die Schwestern, die dort wohnen, wurden von der plötzlichen Veränderung in den Wahnsinn getrieben.\n\nWir wollten Kontakt mit ihnen aufnehmen, doch sie griffen uns an. Ich befürchte, dass viele von ihnen nicht mehr zu retten sind, allerdings kann ich die Hoffnung nicht aufgeben.\n\nNehmt meinen Anhänger, reist zur südwestlich gelegenen Lebendigen Lichtung und versucht, mit seiner Hilfe meine Schwestern zu befreien.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr ihren Anhänger auf 7 Eisnymphen verwendet.", completion = "Es besteht also Hoffnung für meine Schwestern?\n\n<Lurielle wendet ihren Blick von Euch ab und richtet ihn dann auf den Boden.>\n\nIch fühle mich schuldig, nicht früher an den Anhänger gedacht zu haben. Wir hätten vielleicht noch mehr Schwestern retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11315] = { id = 11315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Ranken", description = "Die Schwestern, die auf der Lebendigen Lichtung gen Südwesten leben, hegten einst wunderschöne Beete mit scharlachrotem Efeu, doch dieselbe Kraft, die sie in den Wahnsinn trieb, verwandelte auch ihren geliebten Efeu.\n\nDie Ranken greifen nun nach den Füßen jedes Unbesonnenen oder schlingen sich um jeden, der sich der Lichtung nähert. Bevor wir sie wieder kultivieren können, müssen die Ranken gezähmt und entwurzelt werden.\n\nBeseitigt so viele Exemplare des Efeus wie Ihr nur könnt. Die Sache ist schon außer Kontrolle geraten.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr 8 Exemplare des scharlachroten Efeus tötet.", completion = "Vielen Dank für Eure Hilfe, {name}. Die Lebendige Lichtung war einst ein wunderschöner Ort, und wenn wir zurückkehren, werden wir es wieder zu dem machen, was es einmal war.", sourceObjectiveStatus = "unverified-source-field" }
quests[11316] = { id = 11316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflechte der Siechenden Lichtung", description = "Die Lichtung im Westen wurde in einen grässlichen Ort verwandelt, der nun Siechende Lichtung genannt wird. Zwischen den Bäumen, Steinen und ihrem Teich hausen nun schreckliche Biester.\n\nMir ist es ein Rätsel, wo diese Kreaturen herkamen oder welche ungeheuren Kräfte sie zum Leben erweckten, doch man muss sich um sie kümmern!\n\nLieße man ihnen die Lichtung, dann fürchte ich, dass ihr Gift sie ein für alle Mal verderben wird. Säubert die Lichtung von den Kreaturen, die unsere Schwestern töteten.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr 10 Dornrankenkriecher tötet.", completion = "Gut gemacht, {name}. Hätten wir Verbündete wie Euch gehabt, als sich die ersten Veränderungen im Land regten, dann hätten wir vielleicht einiges, das uns verloren ging, erhalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11317] = { id = 11317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Läuterung", description = "Der Grund, wieso wir dem Bruchwald trotzen konnten, hat seinen Ursprung in den sorgenschweren Träumen von Ulfang dem Worg. Er ist mein Freund und ruft um Hilfe. Ihr müsst zu ihm gehen.\n\nJedoch habt Ihr nicht die Möglichkeit, mit ihm zu reden oder unter den anderen Worgs zu wandeln. Ich kenne einen Weg.\n\nZuerst müsst Ihr Euch von Eurem inneren Aufruhr befreien.\n\nAuf der Spitze des Frostklingengipfels, nordöstlich vom Lager der Winterhufe, gibt es einen Schrein, zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.\n\nMeditiert dort und kehrt zu mir zurück.", sourceObjective = "Weiser Nebelläufer am Stählernen Tor hat Euch geraten, Euren inneren Aufruhr durch Meditation am Frostklingenschrein zu besänftigen.", completion = "Ich kann die Veränderung in Euch bereits spüren.\n\nSeid Ihr bereit für den nächsten Schritt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Ihr wollt also die Rennwidder testen? Nun, ich hoffe, Ihr seid auf Geschwindigkeit gefasst. Bevor ich Euch auf die Welt loslasse, müsst Ihr mir erst einmal beweisen, dass Ihr mit diesen feinen Tieren auch wirklich umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Rennzügel und lasse Euch auf einem Widder reiten. Zeigt mir, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten. Sprecht mit meinem Lehrling, Pol Bernruh, falls Ihr Anweisungen für den Umgang mit den Widdern benötigt.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", progress = "Kommt Ihr mit dem Tempowechsel zurecht?", completion = "Nicht schlecht! Es dauert meist ein wenig, bis man seinen Widder zu kontrollieren versteht. Hat man den Dreh erstmal raus, würde man sich wünschen, dass jeder Widder ein Rennwidder wäre.\n\nWie bitte? \"Wo ist meine Belohnung?\". Ha, ha, ha... Ihr dürft mit dem schnellsten Widder am Rennen teilnehmen! Ihr wollt noch mehr? Na, wie wäre es damit...\n\nAls Belohnung dürft Ihr anderen hier auf dem Braufest aushelfen. Es gibt jede Menge zu tun... und Belohnungen für eifrige, junge Widderrennmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[11319] = { id = 11319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samen der schwarzbeseelten Bewahrer", description = "Der Ort im Nordwesten, den man nun Siechende Lichtung nennt, war einst das Zuhause etlicher Bewahrer der Lichtung. Gemeinsam mit den Schwestern kümmerten sie sich um deren Pflege.\n\nDie Lichtung veränderte sich und die Schwestern starben, doch irgendwie konnten die Bewahrer überleben. Nun säen sie giftige Sporen im Land und sorgen auf diese Weise dafür, dass das gesunde Grün verwelkt.\n\nIch werde Euch einen der Kerne von den Eiselementaren geben. Sobald Ihr einen Sporen zerstört habt, sollt Ihr ihn mithilfe des Eiskristalls einfrieren und ihn auf diese Weise davon abhalten, sich zu regenerieren.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass ihr 8 Sporen einfriert.", completion = "Der Eiskristall hat Euch gut gedient? Das werde ich mir merken müssen. Einmal die Arbeit der Bewahrer zu zerstören, wird sie jedoch nicht aufhalten, da bin ich mir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[11320] = { id = 11320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Quest Description", sourceObjective = "Log Descritpion", sourceObjectiveStatus = "unverified-source-field" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagte da jemand \"Souvenir\"?", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11322] = { id = 11322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Läuterung", description = "Seit einiger Zeit habe ich Alpträume, die sich um den Worg Ulfang drehen. Er hat um Hilfe gerufen. Ihr müsst zu ihm gehen.\n\nJedoch habt Ihr nicht die Möglichkeit, mit ihm zu reden oder unter den anderen Worgs zu wandeln, aber ich kenne einen Weg.\n\nDoch zuerst müsst Ihr Euch durch Meditation von Eurem inneren Aufruhr befreien, Euch läutern.\n\nAuf der Spitze des Frostklingengipfels weit im Nordosten befindet sich ein Schrein, zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.\n\nMeditiert dort, befreit Euch und kehrt zu mir zurück.", sourceObjective = "Behüterin Mondblatt am Stählernen Tor hat Euch geraten, Euren inneren Aufruhr durch Meditation am Frostklingenschrein zu besänftigen.", completion = "Ich kann die Veränderung in Euch bereits spüren.\n\nSeid Ihr bereit für den nächsten Schritt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11323] = { id = 11323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Worgpelz", description = "Aus meinen Träumen weiß ich, dass Ulfang sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds aufhält.\n\nEr ist in großer Gefahr.\n\nIch habe eine magische Verkleidung erschaffen, die Euch wie ein Worg aussehen lassen wird, während Ihr im Bruchwald seid. Die Verkleidung ist schwach und hängt von der merkwürdigen Magie dieses Geisterwaldes ab. Sie wird zwar nur die Worgs überzeugen, es sollte Euch jedoch ermöglichen, nah zu Ulfang zu gelangen.\n\nBitte, {class}, findet ihn und helft ihm.", sourceObjective = "Der Weise Nebelläufer hat Euch gebeten, Ulfang im Bruchwald zu suchen und ihm zu helfen.\n\nKehrt zum Weisen Nebelläufer zurück, um einen Ersatz zu erhalten, solltet Ihr die Worgverkleidung verlieren.\n\nBereitgestellter Gegenstand:", completion = "Du siehst anders aus und riechst auch anders... Du bist nicht aus meinem Rudel. Erzähl mir deine Geschichte. Ich habe mehr als genug Zeit, solange ich hier gefangen bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11324] = { id = 11324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alphaworg", description = "Wenn du die Augen von Klauenwürger gegessen hast, sollte es dir möglich sein, Garwal zu sehen und ihm seine Kehle herauszureißen!\n\n{race}, such nach Garwal im westlichen Bruchwald und töte ihn. Geh zu Nebelläufer, sobald du ihn getötet hast, und sag ihm, dass ich wieder der Alphaworg bin!", sourceObjective = "Ulfang hat Euch gebeten, Garwal zu erschlagen. Kehrt danach zum Weisen Nebelläufer am Stählernen Tor zurück und bringt die Worgverkleidung mit.", progress = "{name}, Ihr seid zurück. Was gibt es Neues von Ulfang?", completion = "Garwal war überhaupt kein Worg! Ich kenne diese Kreaturen... sie werden Worgen genannt.\n\nDoch Ulfang meinte, dass es aus den Grizzlyhügeln kam und gen Süden ging? Seltsam. Hier gibt es gar keine Worgen.\n\nIch danke Euch, dass Ihr Ulfang geholfen habt, seinen wahren Platz in seinem Rudel zurückzuerhalten. Nun werden wir beide friedlich schlafen können.\n\nBitte, Ihr müsst das als Zeichen des Dankes akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11325] = { id = 11325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Worgpelz", description = "Aus meinen Träumen weiß ich, dass Ulfang sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds befindet.\n\nEr ist in großer Gefahr.\n\nIch habe eine magische Verkleidung erschaffen, die Euch wie ein Worg aussehen lassen wird, während Ihr im Bruchwald seid. Die Verkleidung ist schwach und hängt von der merkwürdigen Magie dieses Geisterwaldes ab. Sie wird zwar nur die Worgs überzeugen, doch es sollte Euch ermöglichen, nah zu Ulfang zu gelangen.\n\nBitte, {class}, findet ihn und helft ihm.", sourceObjective = "Behüterin Mondblatt hat Euch gebeten, Ulfang im Bruchwald zu suchen und ihm zu helfen.\n\nKehrt zu Behüterin Mondblatt zurück, um einen Ersatz zu erhalten, solltet Ihr die Worgverkleidung verlieren.\n\nBereitgestellter Gegenstand:", completion = "Du siehst anders aus und riechst auch anders... Du bist nicht aus meinem Rudel. Erzähl mir deine Geschichte. Ich habe mehr als genug Zeit, solange ich hier gefangen bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11326] = { id = 11326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alphaworg", description = "Wenn du die Augen von Klauenwürger gegessen hast, sollte es dir möglich sein, Garwal zu sehen und ihm seine Kehle herauszerreißen!\n\n{race}, such nach Garwal im westlichen Bruchwald und töte ihn. Geh zu Mondblatt, sobald du ihn getötet hast, und sagt ihr, dass ich wieder der Alphaworg bin!", sourceObjective = "Ulfang hat Euch gebeten, Garwal zu erschlagen. Kehrt danach zu Behüterin Mondblatt am Stählernen Tor zurück und bringt die Worgverkleidung mit.", progress = "{name}, Ihr seid zurück. Was gibt es Neues von Ulfang?", completion = "Garwal war überhaupt kein Worg! Das Ding, in das er sich verwandelt, hört sich schon viel eher wie ein Worgen an!\n\nDoch Ulfang meinte, dass es aus den Grizzlyhügeln kam und gen Süden ging? Seltsam. Hier gibt es gar keine Worgen.\n\nIch danke Euch, dass Ihr Ulfang geholfen habt, seinen wahren Platz in seinem Rudel zurückzuerhalten. Nun werden wir beide friedlich schlafen können.\n\nBitte, Ihr müsst das als Zeichen des Dankes akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11327] = { id = 11327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission 'Paket beschaffen'", description = "Tja, verdammt, wir brauchen ein wenig von dem Seuchenzeugs.\n\nIch weiß!\n\nWährend Ihr die Bottiche zerstört habt, konnte ich sehen, wie einer der Apotheker aus Neu-Agamand von den Vrykul nach Halgrind verschleppt wurde. Armer Hund.\n\n{name}, ich könnte wetten, dass der Apotheker das Gut bei sich trägt. Meint Ihr, dass Ihr nach Halgrind gehen und dieses Paket besorgen könntet?", sourceObjective = "Kundschafter Wisslich möchte, dass Ihr nach Halgrind geht und das Paket des Apothekariums beschafft. Kehrt zu ihm zurück, sobald Ihr das getan habt. Er befindet sich am Glutspeerturm.", progress = "Dieser Ort könnte einem Alptraum entstammen. Vrykul oder nicht - niemand hat es verdient, ein Opfer der königlichen Apothekervereinigung zu sein.\n\nIch bin froh hier drüben in Sicherheit zu sein. Habt Ihr das Paket schon gefunden?", completion = "Heiliger... was zum Teufel?! Seht Euch dieses Zeugs an!\n\nWir müssen es so schnell wie möglich zurück zur Wache bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11328] = { id = 11328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission 'Kunde über die Verlassenen'", description = "Gut, nun ich denke, dass Ihr das Zeugs zu Peppy Falschdüse in der Wache bringen solltet. Sie ist so was wie ein Alchemistenamateur - aber der einzige den wir haben.\n\nEins noch zu Peppy: Sie trinkt für ihr Leben gerne. Ihr werdet sie also höchstwahrscheinlich in der Taverne finden - die 'Atmosphäre aufsaugen'.\n\nIch bin mir sicher, dass sie wissen wird, was zu tun ist.", sourceObjective = "Kundschafter Wisslich möchte, dass Ihr das Paket des Apothekariums zu Peppy Falschdüse bringt. Sie befindet sich in der Taverne in Westwacht.", progress = "J-aa, w's wilsd du... hicks?", completion = "Hoppla... das'is was anderes!\n\nNun guud, las misch maal das Scheugs seh'n. Isch liebe es mit Alchemie herumsuufuschn!\n\nInteressaant, interessant... hier, ich denge, isch weiß, was wir mach'n müssn. Ein weenich davon, vermischd mit genauu der rischdischn Menge hiervoon.\n\nWeisd du, isch denke, ein wenig von dem Fusel wäre auch nich schleschd ...hicks!", sourceObjectiveStatus = "unverified-source-field" }
quests[11329] = { id = 11329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich werde alles versuchen!", description = "In meinem ganzen Leben will ich nie wieder ein Fass mit gesalzenem Fisch sehen! Jeden Tag fülle ich hier Fässer und es sind noch so viele zu füllen!\n\nIch wünschte, ich hätte nicht alle Köder aufgebraucht, die ich von Nat Pagle gekauft habe. Haben wie von Zauberhand funktioniert. Jetzt habe ich Glück, wenn ich einen Fisch pro Stunde fangen kann!\n\nIch habe gehört, Nordbarben wären gute Köderfische, aber wer wäre verrückt genug, um in einen eiskalten See zu tauchen und die Wasserpflanzen nach ihnen zu durchwühlen? Ich nicht... aber vielleicht, nur vielleicht, kann ich Euch ja überreden...", sourceObjective = "Christopher Sloan bei Fort Wildervar möchte, dass Ihr ihm 5 Nordbarben bringt.", progress = "Ihr seht aus, als wärt Ihr noch in einem Stück. Etwas von den Ködern bekommen?", completion = "Naja, die sind mit Sicherheit hässlich genug, aber ich schätze, mir ist es egal, ob es tatsächlich funktioniert. Ich werd' froh sein, sobald die Expedition hier durchgezogen ist und ich einfach nur noch für mein Abendessen angeln muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11330] = { id = 11330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dasch wird auf jeden Fall... funzen!", description = "Voilà, schofortwirkender Seuschenimpfstoff!\n\nAber ich werde dasch hundertpro nicht an mir selbscht austeschten – und ich weisch, dass du nicht mein Verschuchskaninchen spielen wilscht!\n\nO'isch hab'... isch hab' eine Idee!\n\nDa ischt ein Vrykul, der wird von unsch im Keller der Burg gefangen gehalten. Wiescho nimmscht du nicht einfach diesen Mix – hab ihn schelbst gemischt! – und gehscht da runter und gibscht's dem Ries'n zu trinken... hicks?!", sourceObjective = "Peppi Falschdüse in Westwacht schlägt vor, dass Ihr dem gefangenen Vrykul der Drachenschinder Peppis Spezialmix verabreicht, um zu sehen, welche Wirkung er hat.", completion = "Hä? Echt ätzend! V'dammt, ich hab' die Schache verschlimmert - oder vielmehr hab' ich ihre Scheuche für schie perfektioniert... hicks!\n\n<Peppi verzieht ihr Gesicht und nimmt einen kräftigen Schluck von dem übel riechenden Gebräu, das sie schon die ganze Zeit trinkt.>\n\nNun, isch hatte gehofft, dass'esch nicht so weit kommen wird, aber s'sieht so ausch, als hätten wir keine andere Wahl... hicks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11331] = { id = 11331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Du sagst's ihm... hicks!", description = "So sieht's ausch: Ich werde es dem Hauptmann nicht sagen. Ich bin nur ein Amateur in Sachen Alchemie - das ischt nicht mein Aufgabengebiet und ich hab' gerade Pause!\n\nAuscherdem ist er ein mortzmäßiger Griesgram... und du kennscht ihn besser wie ich!\n\nAlscho geh' zu ihm in die Burg und sag's ihm. Bin mir schicher, dass er die Sache nüchtern betrachten wird... hicks.\n\n<Peppi wendet sich wieder dem Trinken zu.>", sourceObjective = "Peppi Falschdüse hat Euch dazu gebracht, Hauptmann Adams die schlechten Nachrichten über die Seuche der Verlassenen zu überbringen. Ihr findet ihn in Westwacht.", completion = "Ja, {name}, was denn schon wieder?\n\nWAS?!! Eine Seuche der Verlassenen, die ihre Opfer im Nu zerfrisst?\n\nIhr habt meinen Vrykul in Schleim verwandelt?\n\n\n\nNun gut, ich weiß, was wir tun müssen - oder besser gesagt, was IHR tun müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11332] = { id = 11332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Verseucht mal das hier!", description = "Die Königliche Apothekervereinigung denkt also, sie könnte eine perfekte, neue Seuche erschaffen und uns alle auf der Stelle in Schleim verwandeln?!\n\nNicht so lange ich hier kommandiere!\n\nGeht hinaus auf den Hof und sprecht mit Greer Erzhammer. Er hält einen Greifen und ein paar Bomben für Euch bereit. Ich möchte, dass Ihr die Seuchenkessel bei Neu-Agamand in Stücke sprengt!", sourceObjective = "Hauptmann Adams hat Euch befohlen, 5 Bomben auf die Seuchenkessel bei Neu-Agamand abzuwerfen. Kehrt erst zu ihm zurück, sobald Ihr die Aufgabe erledigt habt. Er befindet sich in Westwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11333] = { id = 11333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in die Welt der Geister", description = "Es mag zwar sein, dass die Forscherliga mithilfe ihrer archäologischen Funde dies und jenes über die Vergangenheit herausfinden und der Vizeadmiral mit purer Gewalt Antworten auf gegenwärtige Fragen erhalten kann, doch die Wahrheit an sich liegt in den Geistern.\n\nMit den richtigen Reagenzien kann ich in die Welt der Geister blicken; denn dies ist der Ort, an dem sich Vergangenheit, Gegenwart und Zukunft von Nordend befinden.\n\nWenn Ihr mehr darüber erfahren wollt, werde ich meinen Reagenzienbeutel benötigen. Er kam mir auf einem Schiff abhanden, das nun auf dem Grund der Dolchbucht gen Osten liegt.", sourceObjective = "Thoralius der Weise in Valgarde möchte, dass Ihr seinen Reagenzienbeutel findet.", progress = "Habt Ihr meinen Reagenzienbeutel gefunden?", completion = "Sieht ein bisschen mitgenommen aus, erfüllt jedoch seinen Zweck.\n\n<Thoralius greift in den Beutel und zieht ein paar seltsam aussehende Wurzeln heraus.>\n\nMan lege sie ins Feuer und inhaliere!\n\n<Thoralius atmet tief ein. Sein Körper fängt an zu zittern.>\n\nWa... Was... Es kann nicht sein... Ich kann es nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er schießt, er trifft!", description = "Schießt auf ein vorgegebenes Ziel.", sourceObjective = "Rinling möchte, dass Ihr auf ein vorgegebenes Ziel schießt und ihm anschließend das Luftgewehr wieder bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Der Kampf gegen die Horde kennt keine Grenzen, {name}. Sogar in der Scherbenwelt gibt es beständig Streitigkeiten über Gebietsansprüche und alter Hass wird von Neuem entfacht. Krieg ist allgegenwärtig!\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz, genau wie in Azeroth, obsiegen wird.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch" }
quests[11343] = { id = 11343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Echo von Ymiron", description = "Die Geisterwelt ist unter den Einfluss des Lichkönigs geraten. Furcht erregende Kreaturen, aus Alpträumen geformt, wachen nun über das Reich der Elemente. Ich spüre, dass diese Val'kyr ein schreckliches Geheimnis wahren.\n\nIch bin zu alt und schwach, um eine weitere Reise zu überstehen. Ihr müsst an meiner statt gehen, {name}.\n\nNehmt dieses Räuchergefäß, geht nach Wyrmskol und begebt Euch mit seiner Hilfe ins Geisterreich. Geht nach Nordosten! Dort befindet sich der Ort. Meidet die Val'kyr um jeden Preis, damit Ihr nicht ihr Schicksal teilen müsst und auf ewig in ihrer Welt gefangen seid.", sourceObjective = "Thoralius der Weise möchte, dass Ihr die Geisterwelt betretet und Wyrmskol nach Informationen über die Geheimnisse von Wyrmskol durchsucht.", completion = "Ich verstehe nicht. Die Kreaturen, die Ihr gesehen habt, sahen genauso aus, wie die Vrykul, die Valgarde angreifen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11344] = { id = 11344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Qualen von Niffelvar", description = "Alles, was wir über die Vrykul wissen, deutet darauf hin, dass sie erst vor Kurzem in Nordend auftauchten. Wie kann es dann sein, dass wir Visionen von Vrykul sehen, die 15.000 Jahre zurückreichen? Hätten die Vrykul zuvor schon in Nordend existiert, wüssten wir mit Sicherheit davon.\n\nSetzt Eure Reise fort und begebt Euch nach Niffelvar. Der Weg, den Ihr nehmen müsst, führt Euch nach Nordosten, durch Wyrmskol hindurch und den Pfad hoch in Richtung Damm. Auf der anderen Seite des Dammes, auf den Klippen, befindet sich schließlich Niffelvar.\n\nMacht von dem Räuchergefäß Gebrauch, sobald Ihr dort angekommen seid, und sucht in der Gegend nach Hinweisen.", sourceObjective = "Thoralius der Weise möchte, dass Ihr die Geisterwelt betretet und Niffelvar nach Informationen über die Geheimnisse von Niffelvar durchsucht.", completion = "Menschenkinder, die von Vrykul in die Welt gesetzt wurden? Und Ymiron gab Befehl, alle menschlichen Nachkommen zu töten?\n\n<Thoralius verstummt für einen Moment.>\n\nSo sehr ich es leugnen möchte, was mir so deutlich vor Augen geführt wurde: ich kann es nicht. Es gibt kein ausgestorbenes \"fehlendes Bindeglied\", das die Herkunft der Menschen klären würde. Die Vrykul sind das fehlende Bindeglied - sie sind die Vorfahren der Menschheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise für Kugeln", description = "Schießt auf ein vorgegebenes Ziel.", sourceObjective = "Rinling möchte, dass Ihr auf ein vorgegebenes Ziel schießt und ihm anschließend das Luftgewehr wieder bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11346] = { id = 11346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der Runen", description = "Das Plateau der Riesen, das weite steinige Gebiet im Südosten, wurde von Eisenzwergen regelrecht überflutet. Späher haben von Zwergen berichtet, die Steinriesen aus dem Boden locken, um dann Runen in ihre Haut zu meißeln.\n\nWas sie dazu treibt ist mir unerklärlich, aber ich vermute, dass sie irgendwie versuchen, aus den Riesen Waffen zu machen. Die Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch, {name}.", sourceObjective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr ihm das Buch der Runen bringt.", progress = "Habt Ihr das Buch bei Euch?", completion = "<Ausgrabungsleiter Belvar blättert durch das Buch der Runen.>\n\nHmm... hier steht so viel geschrieben. Ich werde eine Weile brauchen, um mich eingehend damit zu befassen - und wenn wir diese Runen verstehen wollen, dann werden wir versuchen müssen, unsere eigenen herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11347] = { id = 11347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schafft Platz", description = "Wir haben eine Unmenge von Paketen, die zum Gasthaus in Kharanos geliefert werden müssen. Das Ganze muss schnell gehen, deshalb überlasse ich Euch meinen Rennwidder. Ich wäre schon sehr dankbar, wenn Ihr eines der Pakete abliefert. Ihr habt 5 Minuten, versucht also, so viele Pakete wie möglich zuzustellen. Ich werde Euch mit einer entsprechenden Belohnung erwarten.", sourceObjective = "Bringt das Paket mindestens einmal nach Kharanos. Stellt mehrere Pakete zu, um eine größere Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11348] = { id = 11348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rune des Befehls", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", sourceObjective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr die Rune des Befehls austestet und Binder Murdis besiegt.", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nUnser Wissen darüber, wie sie Runen handhaben, hat sich stark vergrößert. Womöglich werden wir bei der nächsten Begegnung mit den Zwergen daraus einen Vorteil ziehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11349] = { id = 11349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen meistern", description = "Ich habe eine Reihe von Hacken, Hämmern und Meißeln bei mir, die jedoch nicht dazu geeignet sind, die Runen in den Stein zu hauen. Die Werkzeuge der Eisenzwerge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das über bloße Wörter hinausgeht. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nIch meine zu wissen, wie es funktioniert, doch ohne diese Werkzeuge, bin ich mir nicht sicher, ob es klappen wird. Sucht in der Nähe der Eisenzwergzelte auf dem Plateau der Riesen nach Sets, die so aussehen wie meins hier, und bringt sie mir.", sourceObjective = "Bringt Ausgrabungsleiter Belvar in Fort Wildervar ein Set mit Eisenrunenwerkzeugen.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "<Belvar nimmt die Werkzeuge vorsichtig in die Hand.>\n\nIch werde sie einmal ausprobieren. Wenn wir die Motive der Eisenzwerge ergründen und sie besiegen wollen, dann muss ich mir über die Wirkung der Runen im Klaren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11350] = { id = 11350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der Runen", description = "Ich wurde von Häuptling Aschtotem zum Plateau der Riesen geschickt, einem breiten, felsigen Plateau im Südosten, auf der anderen Seite der Gefrorenen Lichtung.\n\nDie Gegend wurde von den Eisenzwergen erobert, die allem Anschein nach die Riesen umwandeln, die aus dem Boden brechen.\n\nDie Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch. Es ist unsere einzige Möglichkeit, wie wir hinter ihre Pläne kommen können.", sourceObjective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr ihm das Buch der Runen bringt.", progress = "Habt Ihr das Buch bei Euch?", completion = "<Der Fernläufer blättert durch das Buch der Runen.>\n\nIch bin zwar kein Geschichtskundiger, jedoch mit der Sprache der Eisenzwerge vertraut. Ich denke, dass die Runen, die sie in die Haut der Riesen ritzen, ihrer Sprache entstammen - nur gibt es da ein paar Unterschiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[11351] = { id = 11351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen meistern", description = "Ich denke, dass ich herausgefunden habe, was die Eisenzwerge dort machen: Ihre Werkzeuge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das mehr ist als nur bloße Wörter. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nWenn ich ein Set mit solchen Werkzeugen hätte, könnte ich die Runen dieses Buchs nachmachen. Ich konnte zwar einen dieser Kästen in den Zelten auf dem Plateau der Riesen finden, doch er war leer. Haltet nach ähnlichen Kästen Ausschau, sucht nach einem Set dieser Werkzeuge und bringt es mir.", sourceObjective = "Bringt Fernläufer Pembe im Lager der Winterhufe ein Set mit Eisenrunenwerkzeugen.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "<Pembe sieht sich die Werkzeuge genauer an.>\n\nSie sind zerbrechlicher als ich dachte. Gebt mir einen Augenblick, damit ich sie ausprobieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11352] = { id = 11352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rune des Befehls", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", sourceObjective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr die Rune des Befehls ausprobiert und Binder Murdis besiegt.", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nMein Volk wird den Eisenzwergen auf seinem Zug gen Norden sicherlich noch einmal begegnen. Doch das nächste Mal werden wir bereit sein und ihre Pläne durchkreuzen, bevor sie richtig loslegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11353] = { id = 11353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flagge: Auf zur Arbeit" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Nazans Reitgerte", description = "Der heutige Käufer interessiert sich für ein Stück, das sich momentan noch im Besitz des Reittiers von Illidans Herold befindet. Ich spreche natürlich von Vazruden dem Herold und seinem Drachenreittier Nazan.\n\nWenn Euch der Finderlohn angemessen erscheint, solltet Ihr Euch zum Bollwerk der Höllenfeuerzitadelle aufmachen und mir die Reitgerte des Drachen beschaffen.\n\nMeine Quellen versicherten mir, dass sich die Reitgerte im Besitz des Drachen höchstpersönlich befindet. Anscheinend verbot dieser seinem Herren die Benutzung der Gerte.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Nazans Reitgerte zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Reitgerte, bitte!", completion = "Wieder ein zufriedener Kunde. Der Gegenstand scheint in gutem Zustand zu sein, hervorragend. Ihr werdet entsprechend entlohnt werden.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11355] = { id = 11355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Riesen", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Was genau ihr endgültiges Reiseziel ist, weiß ich nicht.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung.\n\nDeaktiviert mithilfe dieser Hacke die Runen auf den Leichen der Riesen und kehrt mit Euren Funden zu mir zurück.", sourceObjective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr mithilfe der runensuchenden Hacke die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", completion = "<Forscher Aderan lauscht Euren Worten, als Ihr von Euren Funden berichtet.>\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Hier wird also nachdrücklich befohlen, in diese Richtung zu ziehen, doch die Runen sind mehr als nur Antrieb. Irgendetwas zieht sie an, nur was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostümierte Waisenmatrone", description = "Während der Schlotternächte werden von den Waisenhäusern der Menschen Ausflüge für die Waisenkinder organisiert. Die Kinder sollen Allianzdörfer auf dem Land besuchen. Die armen Kleinen würden so gerne einen wahren Helden wie Euch sehen!\n\nWarum stattet Ihr ihnen keinen Besuch ab? Ihr findet die Waisenkinder in Goldhain im Wald von Elwynn, in Kharanos in Dun Morogh und bei der Azurwacht auf der Azurmythosinsel. Sprecht mit der Aufsicht der Kinder, einer kostümierten Waisenmatrone, sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer kostümierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", completion = "Ihr seid hier, um die Kinder zu besuchen! Wie wundervoll! In ihrem kurzen Leben ist ihnen so viel Kummer widerfahren. Es ist gut, dass sie einen wahren Helden wie Euch sehen. Es hellt ihr Gemüt wirklich auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maskierte Waisenmatrone", description = "Während der Schlotternächte werden mit ein paar Waisenkindern Ausflüge zu verschiedenen Dörfern der Horde unternommen. Die Waisenmatronen dachten, dass es vielleicht gut für die Kinder wäre, wenn sie wahren Helden einmal bei der Arbeit zusehen könnten.\n\nWarum besucht Ihr sie nicht? <Ein mutiger/Eine mutige:c> {class} wie Ihr könnte ihre Gemüter mit Geschichten von Heldentaten aufhellen! Geht nach Klingenhügel in Durotar, Brill in Tirisfal oder zum Falkenplatz im Immersangwald. Sprecht mit der maskierten Waisenmatrone und sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer maskierten Waisenmatrone in Klingenhügel, Brill oder beim Falkenplatz.", completion = "Die Kinder lieben es, wenn sie Helden bei ihrer Arbeit zusehen können. Ich hoffe, dass ein jedes dieser Kinder einmal ein starkes Mitglied der Horde sein und letztendlich in einer glorreichen Schlacht sterben wird!\n\nAh, der Gedanke an ein solch ehrbares Schicksal rührt mich zu Tränen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11358] = { id = 11358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leitstein", description = "Wenn wir ausfindig machen könnten, was die Riesen nach Nordwesten zieht, könnten wir sie vielleicht aufhalten, bevor sie ihr Ziel erreichen.\n\nIch konnte zwar viele der Runenprobestücke, die Ihr mir gebracht habt, entziffern, doch diejenigen, die ich nicht kenne, beunruhigen mich am meisten. Als ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt dieses Probestück, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", sourceObjective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr das Probestück einer Rune mit der zerbrochenen Schrifttafel vergleicht.", completion = "<Aderan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.>\n\nNatürlich! Dieser Megalith muss der Schlüssel zu den Plänen der Eisenzwerge sein. Wir müssen ihn zerstören, bevor sie ihren Plan in die Tat umsetzen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11359] = { id = 11359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megalith zertrümmern", description = "Mit Megalith schuf Binder Murdis den Mächtigsten unter den mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Nachdem die Expeditionskorps eingetroffen sind, werden unsere Soldaten die restlichen Riesen isolieren und besiegen können und auf diese Weise ihre eisenzwergischen Meister aus ihren Lagern vertreiben.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", sourceObjective = "Bezwingt Megalith und kehrt anschließend zu Forscher Aderan in Fort Wildervar zurück.", completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort, der diesen Namen trägt, ist mir zwar unbekannt, doch es klingt wie ein Wort titanischen Ursprungs. Was haben die Eisenzwerge mit solch einem Ding vor? Wir sollten die Sache im Auge behalten, {name}, denn wir müssen das Ding finden, bevor die Eisenzwerge ihren Plan in die Tat umsetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind alle Helden von Goldhain bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nEinige Wachen haben nördlich von hier ein kleines Lager für Übungen der Brandwache errichtet. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen oder das in der Nähe der Feuer stehende Fass verwenden.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Grunzer haben ein Übungslager zum Feuerlöschen außerhalb des Dorfes aufgebaut. In letzter Zeit fangen die Gebäude in Klingenhügel rasch Feuer - Ihr solltet helfen und Euch im Feuerlöschen üben!\n\nVerlasst den Klingenhügel in Richtung Westen und biegt rechts ab, wenn Ihr an der Stadtmauer vorbei seid. Haltet nach dem Übungslager Ausschau. Schnappt Euch Wassereimer und löscht damit die Übungsfeuer.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Klingenhügel.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Werdet alle so stark und mutig wie er, dann werdet auch ihr eines Tages für die Horde kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Keli'dans gefiederter Stab", description = "Die Geschmäcker sind sehr verschieden, nehmt zum Beispiel meinen neuesten Käufer.\n\nIn der Höllenfeuerzitadelle residiert ein Blutorc namens Keli'dan der Zerstörer. Dieser Orc ist im Besitz eines recht gewöhnlichen Stabes; nichts, was einen zweiten Blick wert wäre. Und doch ist es genau dieser Stab, den mein Kunde wünscht.\n\nWer bin ich schon, dass ich diesen Auftrag ablehnen könnte?\n\nAlso, wenn Ihr von mir entlohnt werden wollt, solltet Ihr Euch in den Blutkessel begeben, dort werdet Ihr Keli'dan und seinen Stab finden.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Keli'dans gefiederten Stab zu beschaffen. Bringt ihn zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ihr seid wieder hier... also müsst Ihr den Stab bei Euch tragen!", completion = "Möglicherweise werde ich noch einige frische Federn an den Stab anbringen lassen, bevor ich ihn seinem Käufer übergebe. Mit den ganzen Arakkoas in dieser Gegend sollte das jedoch kein großes Problem darstellen. Ein eher unwichtiges Detail und nichts, das mich davon abhalten könnte, Euch angemessen zu entlohnen.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Messerfausts Siegel", description = "Am heutigen Tage ist ein sehr reicher Sammler an mich herangetreten, dem es nach etwas besonders Einzigartigem verlangt.\n\nKriegshäuptling Kargath Messerfaust trägt sein persönliches Siegel, mit dem er alle offiziellen Dokumente abzeichnet, steht's bei sich. Ich möchte, dass Ihr es für mich beschafft.\n\nIhr findet ihn tief in den Zerschmetterten Hallen. Es besteht kein Zweifel, dass Ihr Euch zunächst durch eine recht beeindruckende Armee kämpfen müsst, bevor Ihr das Siegel in den Händen haltet. Aber ich glaube fest an Euren Erfolg!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Messerfausts Siegel zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich hörte Gerüchte, nach denen der Kriegshäuptling seine Hände durch Waffen hat ersetzen lassen. Ist das wahr?", completion = "Wahrlich eine beeindruckende Akquisition; eine, die es wert ist, dass die Barden noch in Jahrzehnten darüber berichten. Hier, Ihr habt Euch diese Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Zenturionen der Zerschmetterten Hand", description = "Zweifelt Ihr an Eurem Meister? Gut, dann verstehen wir uns, ja?\n\nEs ist das Blut der Zenturionen der Zerschmetterten Hand, nach dem es mich verlangt. Sucht sie in den Zerschmetterten Hallen der Höllenfeuerzitadelle.\n\nWenn Euch die Belohnung lieb ist, werdet Ihr erst zurückkehren, nachdem Ihr sie alle getötet habt.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Zenturionen der Zerschmetterten Hand zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ihr habt Euch Eure Belohnung in der Tat verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11365] = { id = 11365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Riesen", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Ich weiß nicht, was sie vorhaben, noch wohin sie wollen.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung. Streckt ein paar dieser Riesen nieder - dadurch werden die Runen aufhören zu leuchten, so dass man Proben aus dem Körper der Riesen brechen kann.\n\nNehmt diese Hacke mit Euch und bearbeitet mit ihrer Hilfe die runenbeschriebenen Steinriesen. Dadurch werden die Runen deaktiviert. Kehrt mit Euren Funden zu mir zurück, sobald Ihr Euch mit genug Riesen gemessen habt.", sourceObjective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr mithilfe der Hacke zum Runensuchen die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", completion = "<Der Weise lauscht Euren Worten, als Ihr von Euren Funden berichtet.>\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Ich bin zwar kein Experte, was diese Runen angeht, aber dass sie sich wiederholen deutet darauf hin, dass es ein ausdrücklicher Befehl ist.\n\nDiese Gravuren sind jedoch mehr als nur Wegweiser. Es scheint, als steuerten sie die Riesen auf etwas zu, nur was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11366] = { id = 11366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leitstein", description = "Wir müssen herausfinden, was die Riesen nach Nordwesten zieht, damit wir sie aufhalten können, bevor sie ihr Ziel erreichen.\n\nDie Runenproben gaben uns zwar einige Anhaltspunkte, doch es sind die unbekannten Runen, über die ich mir Sorgen mache.\n\nAls ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt diese Probe, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", sourceObjective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr die Runenprobe mit der zerbrochenen Schrifttafel vergleicht.", completion = "<Edan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.>\n\nMegalith? Es ist Wort für Wort das, was auf der Schrifttafel steht! Dieser Megalith muss das Herzstück der rätselhaften Pläne der Eisenhaften darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11367] = { id = 11367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megalith zertrümmern", description = "Mit Megalith schuf Binder Murdis eine Art Schlussstein in der Hierarchie der mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Ich werde Häuptling Aschtotem ersuchen, auf unserem Marsch gen Norden ein paar unserer Männer zur Beseitigung des letzten Rests dieser mit Runen versehenen Riesen einzusetzen.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", sourceObjective = "Bezwingt Megalith und kehrt anschließend zu Weiser Edan im Lager der Winterhufe zurück.", completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort mit diesem Namen ist meinem Volk unbekannt, doch es klingt, als wäre es von den \"Titanen\" geschaffen, von denen die Außenstehenden sprechen. Die Eisenzwerge waren schon immer ein gerissener und gefährlicher Feind, {name}. Wir müssen diese Riesen im Auge behalten und Steinschmiede finden, bevor sie ihre Pläne verwirklichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Das Herz von Quagmirran", description = "Ich habe einen recht ungewöhnlichen Auftrag für Euch. Eine bestimmte wohlhabende Persönlichkeit, mit der ich in außerweltlichem Kontakt stehe, interessiert sich für ein besonders makaberes Stück.\n\nGenau genommen verlangt sie das Herz von Quagmirran.\n\nWie ich hörte, verfügt dieses Biest gleich über drei Herzen, doch ich denke, eines dürfte für unsere Zwecke ausreichend sein. Soweit ich informiert bin, ruht Quagmirran in einem tiefen See in den Sklavenunterkünften des Echsenkessels.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm das Herz von Quagmirran zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ei der Schattenmutter", description = "Unter den Marschenläufern in den Zangarmarschen gibt es stets nur eine oberste Mutter. Man nennt sie die Schattenmutter und wenn sie stirbt, schlüpft ihre Nachfolgerin aus einem der hinterbliebenen Eier.\n\nEiner meiner Käufer interessiert sich für eben diese Eier. Beiläufig erwähnte er etwas davon, dass das geschlüpfte Wesen eine hervorragende Ergänzung für seinen Zoo wäre.\n\nWenn Euch meine Bezahlung angemessen erscheint, solltet Ihr in den Tiefensumpf aufbrechen und die Schattenmutter töten, um an das Ei zu gelangen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm ein Ei der Schattenmutter zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Sprechen wir uns wieder, weil Ihr das Ei habt? Fantastisch, lasst es mich sehen!", completion = "Ist es nicht fantastisch, wie sehr man das Leben in diesem Ei spüren kann? Ich werde mich beeilen und es rechtzeitig zu seinem Käufer bringen müssen. Wir wollen doch nicht, dass es hier bei uns schlüpft, nicht wahr?\n\nEure Bezahlung steht bereit.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die Aufzeichnungen des Kriegsherrn", description = "Vielen ist bekannt, dass Kriegsherr Kalithresh ein hervorragender Stratege ist, doch nur wenige wissen, dass er sein gesamtes Wissen auch niedergeschrieben hat.\n\nEiner meiner Kunden hat davon erfahren und nun wünscht er diese Aufzeichnungen in seinen Besitz zu bringen.\n\nDaher möchte ich Euch bitten, in die Dampfkammer des Echsenkessels einzudringen, um das Buch für mich zu beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Aufzeichnungen des Kriegsherren zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Myrmidonen des Echsenkessels", description = "Mah'duun hat gehört und verstanden. Jetzt sollt Ihr sein Werkzeug sein.\n\nMir wurde offenbart, dass die Myrmidonen des Echsenkessels vernichtet werden müssen. Sucht in den klammen Räumen der Dampfkammer unter dem Echsenkessel nach ihnen.\n\nIch erwarte nichts Geringeres als ihre vollständige Vernichtung.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 14 Myrmidonen des Echsenkessels zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ich nehme an, es war ein Kampf ganz nach Eurem Geschmack? Die Belohnung wird Euch ebenfalls zusagen.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die Kopfschmuckfedern von Ikiss", description = "Kürzlich ist eine Taurenfrau an mich herangetreten, deren Ehemann schon bald in den Stand eines Häuptlings erhoben wird. Sie würde ihn gerne mit einer besonderen Verzierung für seinen Federkopfschmuck überraschen.\n\nGenau genommen hätte sie gerne die Kopfschmuckfedern des niederträchtigen Klauenkönigs Ikiss.\n\nWenn Euch meine ausgesetzte Belohnung angemessen erscheint, solltet Ihr zu den Sethekkhallen von Auchindoun aufbrechen und Ikiss einen Besuch abstatten.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Kopfschmuckfedern von Ikiss zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Häuptlingszeremonie findet bald statt, beeilt Euch.", completion = "Diese Federn werden dem Kopfschmuck des Häuptlings den letzten Schliff geben. Ihr habt Euch Eure Bezahlung redlich verdient, {class}.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Shaffars wundersames Amulett", description = "Heute möchte ich Euch mit einer persönlichen Angelegenheit beauftragen. Aber keine Sorge, die Belohnung macht die Gefahr wieder mehr als wett.\n\nMeine Familie hat noch eine Rechnung mit Nexusprinz Shaffar und seinen Anhängern offen. Sollte mir sein Amulett in die Hände fallen, wäre dies ein sicheres Zeichen dafür, dass sich jemand seiner angenommen hat.\n\nWenn Euch meine Belohnung angemessen erscheint, solltet Ihr zu seinen Gemächern in der Managruft von Auchindoun aufbrechen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Shaffars wundersames Amulett zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Nur wenige wissen, dass Shaffar seine magische Macht ausschließlich aus diesem Amulett bezieht. Ohne es ist er machtlos.\n\nWenn es sich also in Eurem Besitz befindet, lässt dies nur den Schluss zu, dass er tot ist.", completion = "<Eine Woge der Zufriedenheit scheint von dem Windhändler auszugehen.>\n\nGut, es freut mich, von seinem Ende zu hören. Wer weiß, vielleicht gelingt es mir sogar, die Geheimnisse des Amuletts für mich zu nutzen und wenn nicht, werde ich es zu einem angemessenen Preis verkaufen.\n\nIch schätze diese Belohnung ist mehr als ausreichend.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der Seelenedelstein des Exarchen", description = "In dem Bestreben, die nekromantischen Künste besser zu verstehen, werden in der Auchenaikrypta von Auchindoun eine Unzahl von abscheulichen Experimenten durchgeführt. Zahlreich sind die Geister derer, die in den finsteren Hallen gefoltert und ermordet wurden.\n\nEiner meiner Kunden wünscht die Befreiung eines dieser gequälten Geister. Nach meinen Informationen ist dieser Geist in einem Seelenedelstein gefangen, der sich im Besitz von Exarch Maladaar befindet.\n\nSucht ihn mit gebotener Schnelligkeit in der Krypta auf und bringt mir seinen Edelstein.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Seelenedelstein des Exarchen zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Könnt Ihr Euch vorstellen, für alle Ewigkeit in einem Edelstein gefangen zu sein?", completion = "Ihr seid wahrlich ein Held, {name}. Ich bin mir sicher, dass mein Kunde einen Weg finden wird, um den Geist seiner Geliebten aus dem Edelstein zu befreien. Eure Belohnung für diese hervorragende Arbeit wartet bereits auf Euch.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Murmurs Flüstern", description = "Wenn ich Euch eingeweiht habe, werdet Ihr diesen Auftrag mit Sicherheit nicht mehr annehmen wollen.\n\nEiner meiner besonders exzentrischen Kunden befasst sich mit der Erforschung toter Existenzen. Wenn man diversen Gerüchten Glauben schenkt, zerstörte das als Murmur bekannte Wesen die letzte Welt von der es beschworen wurde vollständig. Der Professor würde gerne das so genannte 'Flüstern' dieser Kreatur analysieren, um zu verstehen, wie Murmur so eine Zerstörung verursachen konnte.\n\nWürdet Ihr für mich in das Schattenlabyrinth in Auchindoun eindringen und das 'Flüstern' für mich beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Murmurs Flüstern zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich bin mir nicht einmal sicher, welche Form ein Flüstern in der körperlichen Welt annimmt, aber der Professor versicherte mir, dass Ihr es erkennen werdet, wenn Ihr es seht.\n\nVielleicht ist es so etwas wie der Kehlkopf des Wesens?", completion = "Ich fürchtete schon, Ihr würdet nicht mehr zurückkehren. Ich hoffe doch, der Kampf gegen Murmur hat Euch nicht taub werden lassen?\n\nHier ist Eure Belohnung. Der Professor wird zweifellos sehr zufrieden sein. Ich fürchte mich nur davor, was er mit diesem Gegenstand anfangen wird.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Bösartige Ausbilderinnen", description = "Mah'duun hat vernommen, dass die Grausamkeit der sechsarmigen Dämonen im Schattenlabyrinth beispiellos ist.\n\nBegebt Euch nach Auchindoun, sucht und tötet sie alle.\n\nBemüht Euch nicht, mich ein zweites Mal aufzusuchen, wenn Ihr scheitert.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 3 bösartige Ausbilderinnen zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ich bin sehr zufrieden. Auch der, der über den Nether zu mir spricht, ist hoch erfreut. Mah'duun hat Eure Belohnung bereits vorbereitet.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist süß", description = "Heute Abend koche ich für eine ganz besondere Festgemeinschaft. Einer der Gäste flog vor Kurzem in Skettis herum, als er plötzlich von einem riesigen Kaliri erfasst wurde und zu Boden fiel. Er brach sich dabei sein Bein.\n\nFür seine 'Gute Besserungs'-Feier soll nun etwas ganz Besonderes auf dem Speiseplan stehen: Kalirieintopf.\n\nIch werde Euch meinen Topf zur Verfügung stellen und es wird Eure Aufgabe sein, den Eintopf zu kochen. Das Rezept ist an sich recht einfach, Ihr benötigt nur einen riesigen Kaliriflügel und einige Doppelwarper.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs einen Kalirieintopf zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Rieche ich da etwas zu essen?", completion = "Oh, das riecht aber lecker! Ich hoffe, Ihr habt dem Vogel einen guten Kampf geliefert.\n\nBitte, nehmt Euch ruhig etwas von meinen speziellen Vorräten. Jemand mit Eurem Talent sollte damit etwas anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der Kopf des Epochenjägers", description = "Die Geschmäcker meiner Kunden variieren von banal zu sehr exotisch. Und manchmal wollen sie mit den exotischen Gegenständen, die ich ihnen beschaffe, sehr banale Dinge anstellen.\n\nMein momentaner Kunde gehört zu dieser Sorte. Er, dessen Name hier unerwähnt bleiben soll, wünscht sich nichts sehnlicher, als den Kopf des Epochenjägers an seiner Wand aufzuhängen.\n\n{class}, Ihr müsst einen Weg finden, um zurück durch die Zeit ins Alte Hügelland zu reisen und besagten Kopf für unseren Trophäen sammelnden Kunden beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Kopf des Epochenjägers zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superheißes Ragout", description = "Ich versuche gerade, etwas ganz Besonderes zu kreieren. Aber um ehrlich zu sein, bin ich mittlerweile eher ein Theoretiker geworden. Irgendwie ist mir mein Sinn für Abenteuer abhandengekommen.\n\nIhr aber... Ihr erinnert mich irgendwie an mich selbst in jungen Jahren. Bereit, sich der Welt mit Schwert und Bratpfanne zu stellen.\n\nIch möchte, dass Ihr meinen Lieblingskochtopf nehmt und Euch zum Schergrat aufmacht. Füllt ihn mit ein paar Rippchen und Knusperschlangen - natürlich gekocht, für die Extraportion Würze. Zum Schluss erhitzt Ihr das Ganze über einem abyssischen Leichnam. Dies ist die einzige Wärmequelle, die heiß genug ist, um dieses Gericht perfekt zu garen.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs ein Dämonenragout Surprise, zwei Rippchen der Mok'Nathal und eine Knusperschlange zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Verlief mein kleines Experiment erfolgreich?", completion = "Nun sieh mal einer an...\n\n<Als der Rokk ein wenig von Eurem Gericht probiert, zeichnet sich auf seinem Gesicht eine Mischung aus Entzücken und abnormen Schmerzen ab.>\n\nHeiliger A'dal ist das lecker! Ein Koch mit Eurem Talent braucht stets die richtigen Zutaten! Hier, bedient Euch aus meinen Vorräten und macht mich stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaziös", description = "War ja klar! Ich denke meine Vorräte sind lückenlos und sofort kommt jemand um die Ecke, der etwas Ausgefallenes haben möchte: Manabeere Surprise.\n\nUnglücklichweise findet man Manabeeren nur in den Biokuppeln des Nethersturms. Aber macht Euch nicht die Mühe, auf der Sturmsäule zu suchen - dort ist alles abgeerntet.\n\nEs bedarf eines wahren Meisters der Kochkunst, um nur die besten Beeren zu pflücken, also enttäuscht mich nicht!", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath möchte, dass Ihr 15 Manabeeren in den Biokuppeln im Nethersturm sammelt.", progress = "Hattet Ihr Erfolg?", completion = "Noch nie sah ich so saftige Beeren! Ich fühle mich schon vom bloßen Hingucken geistig gestärkt.\n\nWarum nehmt Ihr nicht etwas von meinen Fisch- und Fleischvorräten? Anscheinend habe ich eh keine Verwendung mehr dafür. Sicherlich werdet Ihr daraus etwas ganz Besonderes kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppe für die Seele", description = "Irgendetwas liegt in der Luft. Noch nie hatte ich so viele Bestellungen für meine berühmte Suppe - sie weckt die inneren Geister und streichelt die Seele.\n\nIch erkenne einen Koch, wenn ich einen sehe! Würdet Ihr mir im Austausch gegen eine kleine Gewinnbeteiligung ein wenig aushelfen?\n\nHier, nehmt meinen Kochtopf, sammelt etwas Grollhuffleisch und ich verrate Euch ein kleines Geheimnis. Was glaubt Ihr, macht meine Suppe so angenehm für die Seele? Es hat nichts mit Hühnchen zu tun! Es liegt daran, dass ich sie beim Ahnengrund in Nagrand koche, um alles Geisterhafte, das in der Luft schwebt, einzufangen.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs eine spirituelle Suppe zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Was riecht hier so gut?", completion = "Das ist eine feine Ladung spirituelle Suppe. Es fehlt nur noch etwas Pfeffer für den richtigen Geschmack!\n\nHier, wie versprochen, Euer Anteil. Und weil Ihr so gute Arbeit geleistet habt, dürft Ihr Euch noch an meinen Vorräten bedienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Aeonus' Stundenglas", description = "Einige meiner Kunden sind wirklich verrückt. Es gibt Dinge, denen man nachjagt und andere, über die man nicht einmal nachdenken sollte!\n\nMein heutiger Kunde ist der Inbegriff von Größenwahn! Er verlangt nichts Geringeres als Aeonus' Stundenglas.\n\nJa, Ihr habt richtig gehört, das Stundenglas von Aeonus, seines Zeichens Angehöriger des ewigen Drachenschwarms!\n\nAber wer bin ich schon, dass ich widersprechen könnte? Insbesondere bei der Menge Gold, die er mir geboten hat. Also, seid Ihr bereit, die Höhlen der Zeit aufzusuchen und in den Schwarzen Morast zu reisen, um das Stundenglas zu beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Aeonus' Stundenglas zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "An Eurer Stelle wäre ich mit Zeitreisen sehr vorsichtig. Schließlich wollt Ihr ja nicht versehentlich einen Eurer eigenen Vorfahren töten und so Eure eigene Existenz in der Gegenwart auslöschen!", completion = "Seltsam, dass der Sand in diesem Ding noch immer aufwärts fließt. Ich schlage vor, wir schaffen es lieber schnellstmöglich zu seinem neuen Besitzer.\n\nIch muss Euch für diese gute Arbeit danken, {class}. Ihr habt Euch Eure Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Fürsten der Zeitenrisse", description = "Mah'duun weiß, was zu tun ist. Mah'duun weiß, dass Ihr Fürsten der Zeitenrisse töten müsst. Doch Mah'duun ist sich des Zeitpunkts nicht sicher.\n\nDas klingt alles sicherlich sehr seltsam für Euch, doch die Stimme im Wind sagte mir auch nicht viel mehr.\n\nBegebt Euch in die Höhlen der Zeit und reist in den Schwarzen Morast. Dort wird sich Euch alles offenbaren.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Fürsten der Zeitenrisse zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Anscheinend habt Ihr Euren Weg in die Vergangenheit und wieder zurück gefunden. Eure Fähigkeiten als {class} sind bemerkenswert. Die Belohnung gehört Euch.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Warpzweigsplitter", description = "Vor Kurzem trat eine Druidin der Kaldorei mit einer herzzerreißenden Bitte an mich heran. Gut, sie hatte auch eine ganze Menge Gold bei sich...\n\nEs scheint, als versuchten die Streitkräfte von Darnassus ein arkanes Urtum namens Warpzweig neu zu erschaffen. Dieses gigantische Baumwesen hat sich wohl verirrt oder wurde von der Verderbnis durchdrungen, naja, jedenfalls hält es sich zurzeit in der Botanika der Festung der Stürme auf.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm einen Warpzweigsplitter zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Schwierigkeiten die Botanika zu finden? Ihr könnt sie gar nicht verfehlen, sie ist ein Teil der Festung der Stürme am östlichen Rand des Nethersturms.", completion = "Oh, Ihr habt es tatsächlich geschafft! Er ist so klein. Unglaublich, das Warpzweig aus diesem kleinen Ding neu erstehen soll und wie man mir sagte, ist es ein ziemlich langwieriger Prozess, den die Druiden da vor sich haben.\n\nEgal, wie versprochen, habe ich hier Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kanalisierer der Sonnensucher", description = "Mah'duun wurde offenbart, dass die Kanalisierer der als Sonnensucher bekannten Kampfeinheit heute getötet werden müssen.\n\nIhr findet sie in der Botanika der Festung der Stürme.\n\nIhr wollt das Kopfgeld? Also tötet sie!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 6 Kanalisierer der Sonnensucher zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Mit den Kanalisierern ist es aus. Der, der aus dem Nether zu mir spricht ist zufrieden und Ihr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Pathaleons Projektionsgerät", description = "Ich habe stets angenommen, Pathaleon könnte sein Abbild nur mithilfe von Magie an die verschiedensten Orte in der Scherbenwelt projizieren. Offensichtlich lag ich damit falsch.\n\nMein neuester Kunde verriet mir, dass der Blutelf stattdessen ein mechanisches Gerät verwendet, um mit den diversen Offizieren von Kael'thas zu kommunizieren. Wenn ich es richtig verstanden habe, stahl er es von einigen Zaxxisrebellen im Nethersturm.\n\nMein Kunde wünscht, dieses Projektionsgerät zu besitzen. Also, warum stattet Ihr Pathaleon nicht einen Besuch ab? Ihr findet ihn in der Mechanar der Festung der Stürme.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Pathaleons Projektionsgerät zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Zerstörer der Sturmschmiede", description = "Im Inneren der Mechanar gibt es eine Vielzahl mechanischer Konstrukte und man hat Mah'duun mit ihrer Vernichtung beauftragt.\n\nBetretet die Festung der Stürme, sucht die Zerstörer der Sturmschmiede und vernichtet sie.\n\nKehrt anschließend zurück, um Eure Belohnung zu erhalten.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Zerstörer der Sturmschmiede zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle vernichtet wurden.", completion = "Mah'duun liebt es, gegen Konstrukte zu kämpfen! Sie sind nicht so fehlerbehaftet wie organische Lebewesen.\n\nIhr habt Euch die Belohnung verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Horizontiss' Schriftrolle", description = "Meinem heutigen Kunden verlangt es nach etwas besonders Ausgefallenem.\n\nMan erzählt sich, dass Herold Horizontiss ein Jünger der Alten Götter sei. Des Weiteren soll er stets eine Schriftrolle bei sich tragen, die die Anweisungen der Götter für ihn enthalten, alles Leben im Universum in ihrem Namen zu unterwerfen.\n\nObwohl er die Schriftsprache der Rolle nicht entziffern können wird, wünscht mein Kunde dennoch, diese zu besitzen.\n\nDringt in die Arkatraz der Festung der Stürme ein und beschafft sie für mich, {class}!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Horizontiss' Schriftrolle zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es muss ganz schön gefährlich sein, sich in die Angelegenheiten der Alten Götter einzumischen.\n\nNaja, besser Ihr als ich!", completion = "Bevor ich den Zorn der Alten Götter auf mich ziehe, hüte ich mich lieber davor, die Schriftrolle überhaupt zu berühren. Ich werde einen meiner Assistenten mit der Zustellung beauftragen.\n\nIhr habt Eure Belohnung mehr als verdient, {class}, und ich wünsche Euch für die Zukunft alles Glück der bekannten Welt!\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schildwachen der Arkatraz", description = "Die Schildwachen der Arkatraz sind wahnsinnig geworden. Die Gefangenen laufen Amok und die Wachen greifen all jene an, die helfen wollen.\n\nMah'duun vernimmt im Raunen des Netherwindes die Stimme des Sprechers. Der Sprecher befiehlt die Vernichtung der Schildwachen.\n\nBringt diese Aufgabe zu Ende und die heutige Belohnung gehört Euch!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Schildwachen der Arkatraz zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Vielleicht wenden die Naaru sich nach der Vernichtung der Schildwachen an das Konsortium, um Ersatz anzufordern? Mah'duun weiß es nicht und es interessiert ihn auch nicht.\n\nIhr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11390] = { id = 11390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kann fliegen!", description = "Tja, auf was wartet Ihr denn noch, es gibt viel zu tun!\n\nHier sind die Schlüssel zu unserer Flugmaschine. Schnappt Euch drei Säcke voller Relikte und befördert sie auf die Kranplattformen auf der Nord- und Südseite des Stählernen Tores. Ich werd' sie für Euch markieren.\n\nMacht schnell! Wir haben nicht den ganzen Tag Zeit!", sourceObjective = "Der Chefarchäologe des Stählernen Tores möchte, dass Ihr 3 Säcke voller Relikte vom Grund der Ausgrabungsstätte zu einer der Plattformen auf der Nord- oder Südseite des Stählernen Tores befördert.\n\nBenutzt den Enterhaken der Flugmaschine für diese Aufgabe.\n\nMeldet Euch bei ihm zurück, sobald Ihr damit fertig seid.", completion = "Gute Arbeit - ich mein' jedoch, dass Ihr über einen Auffrischungskurs in Sachen grundlegende Fliegerei nachdenken solltet.\n\nNun ja, macht nichts, einer ist so gut wie der andere. Hier ist Eure heutige Ausbeute.", sourceObjectiveStatus = "unverified-source-field" }
quests[11391] = { id = 11391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouille am Stählernen Tor", description = "Äh? Heute wieder da zum Arbeiten?\n\nNun gut, hier sind die Schlüssel. Heute muss nichts mehr befördert werden, also haltet nur nach Dingen Ausschau, die verdächtig aussehen, okay?\n\nHab' ein paar Raketen und 'n Maschinengewehr auf sie draufgepackt - für den Fall der Fälle.", sourceObjective = "Für die Leute am Stählernen Tor seid Ihr jetzt ein Fliegerass, also will der Chefarchäologe des Stählernen Tores, dass Ihr über der Ausgrabungsstätte patrouilliert und alle Angreifer bekämpft.\n\nMeldet Euch wieder bei ihm zurück, wenn Ihr Eure Patrouille geflogen habt.", completion = "Gut geschossen, Ass.\n\nHier ist Euer Lohn. Kommt morgen wieder und dreht noch 'ne Runde, hört Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein.", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11393] = { id = 11393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Forscher Jaren?", description = "{name}, mein Verlobter Jaren ging mit einer kleinen Gruppe Forscher nach Westen, um Gerüchten über Artefakte entlang der Küste des Frostmaares nachzugehen. Dort unten gibt es jedoch Murlocs und ich befürchte, dass ihnen das Schlimmste zugestoßen sein könnte.\n\nIhr hättet sicherlich Zeit um nachzusehen, ob es ihnen gut geht, oder? Gleich hier in der Nähe, im Südwesten, gibt es einen Weg hinunter zum Strand - hütet Euch jedoch vor den Worgs und anderen Dingen, die im Wald herumstreunen.", sourceObjective = "Vorarbeiterin Irena Zasterstein hat Euch gebeten, nach ihrem Verlobten Forscher Jaren zu suchen.", completion = "<Der Forscher wirf Euch ein Lächeln zu, als Ihr ihm erzählt, wer Euch geschickt hat. Mit gedämpfter Stimme fährt er fort.>\n\nIrena hat sich um mich Sorgen gemacht? Das hat sie von ihrem Vater, müsst Ihr wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11394] = { id = 11394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", description = "Ich bin ursprünglich hierhergekommen, um ein paar Gerüchten über auszugrabende Artefakte nachzugehen. Ich hab' zwar gewusst, dass es entlang dieser Küste Murlocs gibt, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde.\n\n<Der Forscher reckt seinen Hals und späht hinter dem Baum hervor.>\n\nDie Diener der Geißel sind dort draußen und sie verwandeln Murlocs und überhaupt alles, was ihnen in die Finger gerät, in wandelnde Tote!\n\n{class}, ich denke, dass es unsere Pflicht ist, etwas dagegen zu unternehmen. Wäre es denkbar für Euch, einen guten Teil dieser Geißel zu beseitigen?", sourceObjective = "Forscher Jaren hat Euch gebeten, entlang der Küste des Frostmaares wahllos 15 Diener der Geißel zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", completion = "<Jaren wirkt sehr erfreut über Euren Erfolg, macht jedoch Zeichen, dass Ihr flüstern sollt.>\n\nGute Arbeit, {name}! Eure Kleidung hat jedoch eine Menge von diesem klebrigem Geißelzeugs abbekommen. Vielleicht solltet Ihr Euch über ein kurzes Bad Gedanken machen. Das Wasser ist zwar kalt, wird Euch jedoch im Nu von dem Dreck befreien.", sourceObjectiveStatus = "unverified-source-field" }
